async def real_ping_tcp(host: str, port: int = 443, timeout: int = 3) -> Optional[float]:

    try:
        import socket
        start = time.time()
        
        
        try:
            ip = socket.gethostbyname(host)
        except:
            ip = host
        
        
        reader, writer = await asyncio.wait_for(
            asyncio.open_connection(ip, port),
            timeout=timeout
        )
        
        elapsed = (time.time() - start) * 1000
        writer.close()
        await writer.wait_closed()
        
        return elapsed
        
    except asyncio.TimeoutError:
        return None
    except Exception:
        return None


async def real_ping_icmp(host: str, timeout: int = 3) -> Optional[float]:
    
    try:
        import shutil
        if not shutil.which("ping"):
            return None
        
        process = await asyncio.create_subprocess_exec(
            "ping", "-c", "1", "-W", str(timeout), host,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE
        )
        
        stdout, _ = await asyncio.wait_for(
            process.communicate(),
            timeout=timeout + 1
        )
        
        if process.returncode != 0:
            return None
        
        output = stdout.decode()
        match = re.search(r"time[=<]([\d.]+)", output)
        
        if match:
            return float(match.group(1))
        
        return None
        
    except Exception:
        return None


async def smart_ping(host: str, timeout: int = 3) -> Optional[float]:
    
    
    tcp_result = await real_ping_tcp(host, timeout=timeout)
    if tcp_result is not None:
        return tcp_result
    
    
    icmp_result = await real_ping_icmp(host, timeout=timeout)
    return icmp_result


async def real_ping(host: str, timeout: int = 2) -> Optional[float]:
    
    return await smart_ping(host, timeout)

