async def show_inbound_manager(
    message: types.Message,
    title: str,
    current_inbound_ids: list,
    callback_data_prefix: str,
    save_callback: str,
    back_callback: str = None,
    admin_id: int = None,
    show_default_button: bool = True,
    show_clear_button: bool = True,
    update_existing: bool = False,
    extra_data: dict = None
):
    """
    صفحه پیشرفته مدیریت اینباندها
    
    Args:
        message: پیام برای ویرایش
        title: عنوان صفحه
        current_inbound_ids: لیست اینباندهای فعلی
        callback_data_prefix: پیشوند برای کالبک‌ها (مثلاً 'category_1' یا 'test_service')
        save_callback: کالبک برای ذخیره (با {prefix} ساخته می‌شود)
        back_callback: کالبک برای برگشت (اختیاری)
        admin_id: آیدی ادمین
        show_default_button: نمایش دکمه انتخاب پیش‌فرض
        show_clear_button: نمایش دکمه پاک کردن همه
        update_existing: آپدیت پیام موجود یا ارسال جدید
        extra_data: اطلاعات اضافی برای ذخیره (مثل category_id)
    """
    if admin_id != ADMIN_ID_INT:
        return
    
    lang = get_user(admin_id).get('lang', 'fa')
    
    inbounds = await xui_get_inbounds()
    active_inbounds = [i for i in inbounds if i.get('enable', True)]
    
    if not active_inbounds:
        await message.answer("❌ هیچ اینباند فعالی یافت نشد")
        return
    
    temp_key = f"{callback_data_prefix}_{admin_id}"
    if temp_key in TEMP_INBOUND_SELECTION:
        current_list = TEMP_INBOUND_SELECTION[temp_key]
    else:
        current_list = current_inbound_ids.copy() if current_inbound_ids else []
        TEMP_INBOUND_SELECTION[temp_key] = current_list.copy()
    
    if back_callback and extra_data:
        back_key = f"{callback_data_prefix}_{admin_id}_back"
        INBOUND_BACK_DATA[back_key] = {
            'back_callback': back_callback,
            'extra_data': extra_data
        }
    
    inbound_names = {}
    for ib in active_inbounds:
        inbound_id = ib.get('id')
        remark = ib.get('remark', f'ID:{inbound_id}')
        protocol = ib.get('protocol', '').upper()
        port = ib.get('port', '')
        inbound_names[inbound_id] = f"{remark} - {protocol}:{port}"
    
    if lang == "fa":
        text = f"""
📡 <b>{title}</b>

✅ روی هر اینباند کلیک کنید تا انتخاب/لغو شود.
📊 {len(current_list)} اینباند انتخاب شده

💡 پس از اتمام، روی «ذخیره» کلیک کنید.
"""
    else:
        text = f"""
📡 <b>{title}</b>

✅ Click each inbound to select/deselect.
📊 {len(current_list)} inbounds selected

💡 Click 'Save' when done.
"""
    
    buttons = []
    for inbound in active_inbounds:
        inbound_id = inbound.get('id')
        ib_name = inbound_names.get(inbound_id, f"ID: {inbound_id}")
        
        is_selected = inbound_id in current_list
        
        if is_selected:
            label = f"✅ {ib_name}"
            style = "success"
        else:
            label = f"⬜ {ib_name}"
            style = None
        
        buttons.append([InlineKeyboardButton(
            text=label[:55],
            callback_data=f"inbound_toggle_{callback_data_prefix}_{inbound_id}",
            style=style
        )])
    
    action_buttons = []
    
    if show_default_button:
        default_ids = configs_pool.get('default_inbound_ids', [])
        if default_ids:
            action_buttons.append(
                InlineKeyboardButton(
                    text="📌 انتخاب پیش‌فرض" if lang == "fa" else "📌 Select Default",
                    callback_data=f"inbound_default_{callback_data_prefix}",
                    style="primary"
                )
            )
    
    if show_clear_button:
        action_buttons.append(
            InlineKeyboardButton(
                text="🗑 پاک کردن همه" if lang == "fa" else "🗑 Clear All",
                callback_data=f"inbound_clear_{callback_data_prefix}",
                style="danger"
            )
        )
    
    if action_buttons:
        buttons.append(action_buttons)
    
    save_buttons = [
        InlineKeyboardButton(
            text="✅ ذخیره" if lang == "fa" else "✅ Save",
            callback_data=f"inbound_save_{callback_data_prefix}",
            style="success"
        )
    ]
    
    if back_callback:
        save_buttons.append(
            InlineKeyboardButton(
                text="❌ انصراف" if lang == "fa" else "❌ Cancel",
                callback_data=f"inbound_back_{callback_data_prefix}",
                style="danger"
            )
        )
    
    buttons.append(save_buttons)
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=buttons)
    
    try:
        if update_existing:
            try:
                await message.edit_text(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
            except Exception as e:
                if "message is not modified" in str(e):
                    try:
                        await message.edit_reply_markup(reply_markup=keyboard)
                    except:
                        pass
                else:
                    raise
        else:
            await message.edit_text(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        if "message is not modified" not in str(e):
            try:
                await message.delete()
            except:
                pass
            await message.answer(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
            


@dp.callback_query(F.data.startswith("inbound_toggle_"))
async def inbound_toggle(callback: CallbackQuery):
    """تغییر وضعیت یک اینباند (عمومی)"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    parts = callback.data.split("_")
    try:
        prefix_parts = parts[2:-1]  
        prefix = "_".join(prefix_parts)
        inbound_id = int(parts[-1])
    except (ValueError, IndexError):
        await callback.answer("❌ خطا در پردازش", show_alert=True)
        return
    
    temp_key = f"{prefix}_{callback.from_user.id}"
    if temp_key not in TEMP_INBOUND_SELECTION:
        await callback.answer("❌ وضعیت نامعتبر", show_alert=True)
        return
    
    current_list = TEMP_INBOUND_SELECTION[temp_key]
    
    if inbound_id in current_list:
        current_list.remove(inbound_id)
        await callback.answer(f"❌ لغو شد", show_alert=False)
    else:
        current_list.append(inbound_id)
        await callback.answer(f"✅ انتخاب شد", show_alert=False)
    
    TEMP_INBOUND_SELECTION[temp_key] = current_list
    
    back_key = f"{prefix}_{callback.from_user.id}_back"
    extra_data = INBOUND_BACK_DATA.get(back_key, {}).get('extra_data', {})
    
    await show_inbound_manager(
        message=callback.message,
        title="مدیریت اینباندها",
        current_inbound_ids=current_list,
        callback_data_prefix=prefix,
        save_callback=f"inbound_save_{prefix}",
        back_callback=f"inbound_back_{prefix}",
        admin_id=callback.from_user.id,
        update_existing=True,
        extra_data=extra_data
    )


