@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_test_user_select'))
async def admin_test_user_select_execute(message: Message):
    """دریافت آیدی کاربر و نمایش تنظیمات"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply(
            "❌ عملیات لغو شد" if lang == "fa" else "❌ Cancelled",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🔙 برگشت" if lang=="fa" else "🔙 Back", callback_data="admin_test_all_users_settings")]
            ])
        )
        return
    
    try:
        target_id = int(message.text.strip())
    except ValueError:
        await message.reply(
            "❌ لطفاً یک آیدی عددی معتبر وارد کنید!" if lang == "fa" else "❌ Please enter a valid numeric ID!"
        )
        return
    user_info = await get_user_info_from_telegram(target_id)
    
    if str(target_id) not in users:
        await message.reply(
            f"❌ کاربر {user_info['full_name']} (ID: {target_id}) در دیتابیس یافت نشد!" if lang == "fa" else f"❌ User {user_info['full_name']} (ID: {target_id}) not found!",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🔄 تلاش مجدد" if lang=="fa" else "🔄 Try Again", callback_data="admin_test_user_select")],
                [InlineKeyboardButton(text="🔙 برگشت" if lang=="fa" else "🔙 Back", callback_data="admin_test_all_users_settings")]
            ])
        )
        user_states.pop(admin_id, None)
        return
    
    user_states.pop(admin_id, None)
    await admin_test_user_settings(callback=type('obj', (object,), {
        'from_user': message.from_user,
        'message': message,
        'data': f"admin_test_user_settings_{target_id}",
        'answer': lambda *args, **kwargs: None
    })())
    
    
