@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_default_test_setting'))
async def admin_test_set_default_save(message: Message):
    """ذخیره تنظیمات پیش‌فرض تست"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply(
            "❌ عملیات لغو شد" if lang == "fa" else "❌ Cancelled",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🔙 برگشت" if lang=="fa" else "🔙 Back", callback_data="admin_test_all_users_settings")]
            ])
        )
        return
    
    try:
        parts = message.text.split('|')
        if len(parts) != 3:
            await message.reply(
                "❌ فرمت نامعتبر! لطفاً به فرمت `حجم|مدت|تعداد تست` وارد کنید." if lang == "fa" else "❌ Invalid format! Please use `volume|duration|max_tests`."
            )
            return
        
        volume = int(parts[0].strip())
        days = int(parts[1].strip())
        max_tests = int(parts[2].strip())
        if volume < 1 or volume > 100:
            await message.reply(
                "❌ حجم باید بین 1 تا 100 گیگ باشد!" if lang == "fa" else "❌ Volume must be between 1 and 100 GB!"
            )
            return
        if days < 1 or days > 30:
            await message.reply(
                "❌ مدت باید بین 1 تا 30 روز باشد!" if lang == "fa" else "❌ Duration must be between 1 and 30 days!"
            )
            return
        if max_tests < 1 or max_tests > 10:
            await message.reply(
                "❌ تعداد تست باید بین 1 تا 10 باشد!" if lang == "fa" else "❌ Max tests must be between 1 and 10!"
            )
            return
        TEST_SERVICE_STATUS['volume'] = volume
        TEST_SERVICE_STATUS['days'] = days
        TEST_SERVICE_STATUS['max_tests'] = max_tests
        TEST_SERVICE_STATUS['last_updated'] = datetime.now().isoformat()
        configs_pool['test_service'] = TEST_SERVICE_STATUS
        save_all()
        
        user_states.pop(admin_id, None)
        
        if lang == "fa":
            await message.reply(
                f"✅ تنظیمات تست پیش‌فرض بروزرسانی شد!\n\n"
                f"📦 حجم: {volume} GB\n"
                f"⏱ مدت: {days} روز\n"
                f"🔢 تعداد تست: {max_tests}",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="🔙 برگشت", callback_data="admin_test_all_users_settings")]
                ])
            )
        else:
            await message.reply(
                f"✅ Default test settings updated!\n\n"
                f"📦 Volume: {volume} GB\n"
                f"⏱ Duration: {days} days\n"
                f"🔢 Max tests: {max_tests}",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="🔙 Back", callback_data="admin_test_all_users_settings")]
                ])
            )
        
    except ValueError:
        await message.reply(
            "❌ لطفاً اعداد معتبر وارد کنید!" if lang == "fa" else "❌ Please enter valid numbers!"
        )
    except Exception as e:
        logger.error(f"خطا در ذخیره تنظیمات پیش‌فرض: {e}")
        await message.reply(f"❌ خطا: {str(e)}")
        user_states.pop(admin_id, None)
        
        
@dp.callback_query(F.data == "admin_test_users_with_settings")
async def admin_test_users_with_settings(callback: CallbackQuery):
    """نمایش لیست کاربران با تست اختصاصی"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    if not USER_TEST_SETTINGS:
        await callback.answer(
            "📭 هیچ کاربری تنظیمات تست اختصاصی ندارد!" if lang == "fa" else "📭 No users have custom test settings!",
            show_alert=True
        )
        return
    
    users_list = []
    for uid, settings in USER_TEST_SETTINGS.items():
        user_info = get_user(int(uid)) if uid in users else None
        name = user_info.get('name', f'کاربر_{uid}') if user_info else f'کاربر_{uid}'
        users_list.append({
            'id': uid,
            'name': name,
            'settings': settings
        })
    
    if lang == "fa":
        text = f"📋 <b>کاربران با تنظیمات تست اختصاصی</b>\n\n📊 تعداد: {len(users_list)}\n━━━━━━━━━━━━━━━━━━━━━━\n\n"
    else:
        text = f"📋 <b>Users with Custom Test Settings</b>\n\n📊 Count: {len(users_list)}\n━━━━━━━━━━━━━━━━━━━━━━\n\n"
    
    for i, user in enumerate(users_list[:20], 1):
        settings = user['settings']
        text += f"{i}. {user['name']} (ID: {user['id']})\n"
        text += f"   📦 {settings.get('volume', 5)}GB | ⏱ {settings.get('days', 3)} روز | 🔢 {settings.get('max_tests', 1)}\n\n"
    
    if len(users_list) > 20:
        text += f"... و {len(users_list) - 20} کاربر دیگر\n"
    
    buttons = [
        [InlineKeyboardButton(
            text="🗑 حذف همه تنظیمات اختصاصی" if lang == "fa" else "🗑 Clear All Custom Settings",
            callback_data="admin_test_clear_all_settings",
            style="danger"
        )],
        [InlineKeyboardButton(
            text="🔙 برگشت" if lang == "fa" else "🔙 Back",
            callback_data="admin_test_all_users_settings"
        )]
    ]
    
    if len(text) > 4000:
        from io import BytesIO
        from aiogram.types import BufferedInputFile
        
        file_buffer = BytesIO()
        file_buffer.write(text.encode('utf-8'))
        file_buffer.seek(0)
        
        filename = f"custom_test_users_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
        input_file = BufferedInputFile(file_buffer.read(), filename=filename)
        
        await callback.message.delete()
        await callback.message.answer_document(
            document=input_file,
            caption="📋 کاربران با تست اختصاصی" if lang == "fa" else "📋 Users with Custom Test",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons)
        )
    else:
        try:
            await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
        except Exception as e:
            try:
                await callback.message.delete()
            except:
                pass
            await callback.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")
        
        
@dp.callback_query(F.data == "admin_test_clear_all_settings")
async def admin_test_clear_all_settings_confirm(callback: CallbackQuery):
    """تأیید پاک کردن همه تنظیمات اختصاصی"""
