@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_test_user_id'))
async def admin_test_user_reset_execute(message: Message):
    """اجرای ریست تست یک کاربر"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply(
            "❌ عملیات لغو شد" if lang == "fa" else "❌ Cancelled",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🔙 مدیریت تست" if lang=="fa" else "🔙 Test Management", callback_data="admin_test_users")]
            ])
        )
        return
    
    try:
        target_id = int(message.text.strip())
    except ValueError:
        await message.reply(
            "❌ لطفاً یک آیدی عددی معتبر وارد کنید!" if lang == "fa" else "❌ Please enter a valid numeric ID!"
        )
        return
    uid = str(target_id)
    user_info = await get_user_info_from_telegram(target_id)
    user_full_name = user_info.get('full_name', f'کاربر_{target_id}')
    
    if uid not in USER_TEST_USAGE:
        await message.reply(
            f"❌ کاربر {user_full_name} (ID: {target_id}) هیچ تستی نگرفته است." if lang == "fa" else f"❌ User {user_full_name} (ID: {target_id}) has no tests.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🔄 تلاش مجدد" if lang=="fa" else "🔄 Try Again", callback_data="admin_test_user_reset")],
                [InlineKeyboardButton(text="🔙 برگشت" if lang=="fa" else "🔙 Back", callback_data="admin_test_users")]
            ])
        )
        user_states.pop(admin_id, None)
        return
    old_data = USER_TEST_USAGE[uid].copy()
    old_count = old_data.get('count', 0)
    del USER_TEST_USAGE[uid]
    save_test_usage()
    logger.info(f"🗑 تست کاربر {target_id} ({user_info.get('full_name_raw', user_full_name)}) با {old_count} تست ریست شد")
    
    if log_system:
        await log_system.log_admin_action(
            admin_id,
            "ریست تست کاربر",
            target_user=target_id,
            details=f"تعداد تست‌های حذف شده: {old_count}"
        )
    
    if lang == "fa":
        text = f"""
✅ <b>تست کاربر با موفقیت ریست شد!</b>

━━━━━━━━━━━━━━━━━━━
🆔 آیدی: <code>{target_id}</code>
👤 نام: {user_full_name}
📊 تعداد تست‌های حذف شده: {old_count}
━━━━━━━━━━━━━━━━━━━

🔓 کاربر می‌تواند دوباره تست بگیرد.
"""
        buttons = [
            [InlineKeyboardButton(text="🔄 ریست کاربر دیگر" if lang=="fa" else "🔄 Reset Another User", callback_data="admin_test_user_reset")],
            [InlineKeyboardButton(text="📋 لیست کاربران تست" if lang=="fa" else "📋 Test Users List", callback_data="admin_test_users_list")],
            [InlineKeyboardButton(text="🔙 برگشت به مدیریت" if lang=="fa" else "🔙 Back to Management", callback_data="admin_test_users")]
        ]
    else:
        text = f"""
✅ <b>User test reset successfully!</b>

━━━━━━━━━━━━━━━━━━━
🆔 ID: <code>{target_id}</code>
👤 Name: {user_full_name}
📊 Tests removed: {old_count}
━━━━━━━━━━━━━━━━━━━

🔓 User can take test again.
"""
        buttons = [
            [InlineKeyboardButton(text="🔄 Reset Another User", callback_data="admin_test_user_reset")],
            [InlineKeyboardButton(text="📋 Test Users List", callback_data="admin_test_users_list")],
            [InlineKeyboardButton(text="🔙 Back to Management", callback_data="admin_test_users")]
        ]
    
    await message.reply(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode=ParseMode.HTML)
    user_states.pop(admin_id, None)
    
    
    

@dp.callback_query(F.data == "admin_test_users_list")
async def admin_test_users_list(callback: CallbackQuery):
    """نمایش لیست کامل کاربران تست‌دهنده با امکان تنظیمات"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    if not USER_TEST_USAGE:
        await callback.answer(
            "📭 هیچ کاربری تست نگرفته است!" if lang == "fa" else "📭 No users have taken a test!",
            show_alert=True
        )
        return
    test_users = []
    for uid, data in USER_TEST_USAGE.items():
        user_info = get_user(int(uid)) if uid in users else None
        raw_name = user_info.get('name', f'کاربر_{uid}') if user_info else f'کاربر_{uid}'
        name_escaped = html.escape(raw_name)
        test_users.append({
            'id': uid,
            'name': name_escaped,  # ✅ ذخیره نام escaped
            'count': data.get('count', 0),
            'last_test': data.get('last_test', 'نامشخص'),
            'last_order_id': data.get('last_order_id', 'نامشخص')
        })
    test_users.sort(key=lambda x: x['count'], reverse=True)
    
    if lang == "fa":
        text = f"📋 <b>لیست کامل کاربران تست‌دهنده</b>\n\n📊 تعداد کل: {len(test_users)}\n━━━━━━━━━━━━━━━━━━━━━━\n\n"
    else:
        text = f"📋 <b>Full List of Test Users</b>\n\n📊 Total: {len(test_users)}\n━━━━━━━━━━━━━━━━━━━━━━\n\n"
    for i, user in enumerate(test_users[:15], 1):
        text += f"{i}. {user['name']} (ID: {user['id']}) - {user['count']} تست\n"
        if user['last_test']:
            text += f"   🕐 آخرین تست: {user['last_test'][:16]}\n"
        text += "\n"
    
    if len(test_users) > 15:
        text += f"... و {len(test_users) - 15} کاربر دیگر\n"
    buttons = []
    for user in test_users[:15]:
        buttons.append([InlineKeyboardButton(
            text=f"⚙️ تنظیمات {user['name']} (ID: {user['id']})",
            callback_data=f"admin_test_user_settings_{user['id']}",
            style="primary"
        )])
    
    buttons.append([InlineKeyboardButton(
        text="🔄 ریست تست یک کاربر" if lang == "fa" else "🔄 Reset Single User",
        callback_data="admin_test_user_reset"
    )])
    buttons.append([InlineKeyboardButton(
        text="🔙 برگشت" if lang == "fa" else "🔙 Back",
        callback_data="admin_test_users"
    )])
    if len(text) > 4000:
        from io import BytesIO
        from aiogram.types import BufferedInputFile
        
        file_buffer = BytesIO()
        file_buffer.write(text.encode('utf-8'))
        file_buffer.seek(0)
        
        filename = f"test_users_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
        input_file = BufferedInputFile(file_buffer.read(), filename=filename)
        
        await callback.message.delete()
        await callback.message.answer_document(
            document=input_file,
            caption="📋 لیست کامل کاربران تست" if lang == "fa" else "📋 Full Test Users List",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons)
        )
    else:
        try:
            await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
        except Exception as e:
            try:
                await callback.message.delete()
            except:
                pass
            await callback.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")
        
        
        


def load_user_test_settings():
    """بارگذاری تنظیمات اختصاصی تست کاربران"""
    global USER_TEST_SETTINGS
    try:
        settings_file = os.path.join(DATA_DIR, "user_test_settings.json")
        if os.path.exists(settings_file):
            with open(settings_file, 'r', encoding='utf-8') as f:
                USER_TEST_SETTINGS = json.load(f)
            logger.info(f"✅ تنظیمات اختصاصی تست {len(USER_TEST_SETTINGS)} کاربر بارگذاری شد")
        else:
            USER_TEST_SETTINGS = {}
    except Exception as e:
        logger.error(f"❌ خطا در بارگذاری تنظیمات تست کاربران: {e}")
        USER_TEST_SETTINGS = {}

def save_user_test_settings():
    """ذخیره تنظیمات اختصاصی تست کاربران"""
    try:
        settings_file = os.path.join(DATA_DIR, "user_test_settings.json")
        with open(settings_file, 'w', encoding='utf-8') as f:
            json.dump(USER_TEST_SETTINGS, f, ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        logger.error(f"❌ خطا در ذخیره تنظیمات تست کاربران: {e}")
        return False

def get_user_test_settings(user_id: int) -> dict:
    """دریافت تنظیمات اختصاصی تست کاربر"""
    uid = str(user_id)
    
    default = {
        'volume_mb': TEST_SERVICE_STATUS.get('volume_mb', 1024),
        'days': TEST_SERVICE_STATUS.get('days', 3),
        'max_tests': TEST_SERVICE_STATUS.get('max_tests', 1),
        'ip_limit': TEST_SERVICE_STATUS.get('ip_limit', 0)
    }
    
    if uid in USER_TEST_SETTINGS:
        settings = USER_TEST_SETTINGS[uid]
        for key in default:
            if key not in settings:
                settings[key] = default[key]
        return settings
    
    return default.copy()


