def _try_recover_from_backup(file_path: str) -> dict:
    """تلاش برای بازیابی فایل از بکاپ"""
    filename = os.path.basename(file_path)
    file_dir = os.path.dirname(file_path)
    backup_dir = os.path.join(file_dir, "backups")
    
    logger.info(f"🔍 تلاش برای بازیابی {filename} از بکاپ...")
    
    if not os.path.exists(backup_dir):
        logger.warning(f"⚠️ پوشه بکاپ وجود ندارد: {backup_dir}")
        return None
    backups = []
    for f in os.listdir(backup_dir):
        if f.startswith(filename) and (f.endswith('.backup') or f.endswith('.json')):
            full_path = os.path.join(backup_dir, f)
            backups.append((os.path.getmtime(full_path), full_path))
    
    if not backups:
        logger.warning(f"⚠️ هیچ بکاپی برای {filename} یافت نشد")
        return None
    backups.sort(reverse=True)
    latest_backup = backups[0][1]
    
    try:
        with open(latest_backup, 'r', encoding='utf-8') as f:
            data = json.loads(f.read())
        save_json(file_path, data)
        
        logger.warning(f"🔄 {filename} از بکاپ بازیابی شد: {os.path.basename(latest_backup)}")
        return data
        
    except Exception as e:
        logger.error(f"❌ خطا در بازیابی از بکاپ: {e}")
        return None


user_states = {}
logger.info("دیکشنری user_states ایجاد شد") 


USER_INBOUND_SELECTION = {}  # user_id -> inbound_id

def save_user_inbound_selection(user_id: int, inbound: Union[int, List[int]]):
    """ذخیره انتخاب اینباند کاربر (تک یا لیست)"""
    USER_INBOUND_SELECTION[str(user_id)] = inbound
    try:
        inbound_file = os.path.join(DATA_DIR, "user_inbounds.json")
        with open(inbound_file, 'w', encoding='utf-8') as f:
            json.dump(USER_INBOUND_SELECTION, f, ensure_ascii=False, indent=2)
        logger.info(f"✅ انتخاب اینباند برای کاربر {user_id} ذخیره شد: {inbound}")
    except Exception as e:
        logger.error(f"❌ خطا در ذخیره انتخاب اینباند: {e}")

def load_user_inbound_selections():
    """بارگذاری انتخاب‌های اینباند کاربران"""
    global USER_INBOUND_SELECTION
    try:
        inbound_file = os.path.join(DATA_DIR, "user_inbounds.json")
        if os.path.exists(inbound_file):
            with open(inbound_file, 'r', encoding='utf-8') as f:
                USER_INBOUND_SELECTION = json.load(f)
            logger.info(f"✅ انتخاب‌های اینباند کاربران بارگذاری شد: {len(USER_INBOUND_SELECTION)} کاربر")
    except Exception as e:
        logger.error(f"خطا در بارگذاری انتخاب‌های اینباند: {e}")
        USER_INBOUND_SELECTION = {}

def get_user_inbounds(user_id: int) -> List[int]:
    """دریافت لیست اینباندهای انتخاب شده برای کاربر"""
    user_inbound = USER_INBOUND_SELECTION.get(str(user_id))
    if user_inbound:
        if isinstance(user_inbound, list):
            return user_inbound
        return [user_inbound]
    default_ids = configs_pool.get('default_inbound_ids', [])
    if default_ids:
        return default_ids
    return []  # یا همه اینباندها را برگردان

def is_shop_open() -> bool:
    """بررسی وضعیت فروش"""
    return SHOP_STATUS.get('open', True)

def get_shop_status_message(lang: str = 'fa') -> str:
    """دریافت پیام وضعیت فروش"""
    if lang == 'fa':
        return SHOP_STATUS.get('message', 'فروش به دلیل بروزرسانی موقتاً بسته شده است.')
    else:
        return 'The shop is temporarily closed for updates.'

def set_shop_status(open_status: bool, message: str = None):
    """تنظیم وضعیت فروش"""
    global SHOP_STATUS
    SHOP_STATUS['open'] = open_status
    if message:
        SHOP_STATUS['message'] = message
    SHOP_STATUS['last_updated'] = datetime.now().isoformat()
    configs_pool['shop_status'] = SHOP_STATUS
    save_all()
    logger.info(f"🛒 وضعیت فروش تغییر کرد: {'باز' if open_status else 'بسته'}")
    
    
