@dp.callback_query(F.data == "admin_toggle_manual_approval")
async def admin_toggle_manual_approval(callback: CallbackQuery):
    """فعال/غیرفعال کردن تایید دستی کاربران جدید"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    manual_approval = configs_pool.get('manual_approval_settings', {})
    manual_approval['enabled'] = not manual_approval.get('enabled', False)
    manual_approval['last_updated'] = datetime.now().isoformat()
    configs_pool['manual_approval_settings'] = manual_approval
    save_all()
    
    status = "فعال" if manual_approval['enabled'] else "غیرفعال"
    await callback.answer(
        f"✅ تایید دستی کاربران جدید {status} شد!" if lang == "fa" else f"✅ Manual approval {status}d!",
        show_alert=True
    )
    await admin_shop_settings(callback)
class ConfigCache:
    """کش غیرفعال - همیشه اطلاعات را از دیتابیس می‌خواند"""
    
    def __init__(self):
        self.cache = {}
        self.cache_time = {}
        self.cache_duration = 0  # ✅ صفر = کش غیرفعال
        
    def get(self, user_id: int) -> list:
        """همیشه None برمی‌گرداند تا کش استفاده نشود"""
        return None
    
    def set(self, user_id: int, configs: list):
        """هیچ کاری نمی‌کند"""
        pass
    
    def clear(self, user_id: int = None):
        """پاک کردن کش"""
        pass
    
    def clear_all(self):
        """پاک کردن همه کش"""
        self.cache.clear()
        self.cache_time.clear()
    
    def get_stats(self) -> dict:
        """دریافت آمار کش (همیشه خالی)"""
        return {
            'total_users': 0,
            'total_configs': 0,
            'cache_duration': 0
        }
config_cache = ConfigCache()
SYNC_IN_PROGRESS = False


@dp.callback_query(F.data == "admin_pending_users")
async def admin_pending_users(callback: CallbackQuery):
    """نمایش لیست کاربران در انتظار تایید"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    pending_users = []
    for uid, user_data in users.items():
        if (user_data.get('requested_approval', False) and 
            not user_data.get('approved_by_admin', False) and
            user_data.get('registration_status') == 'requested' and
            int(uid) != ADMIN_ID_INT):
            pending_users.append({
                'id': int(uid),
                'name': user_data.get('name', f'کاربر_{uid}'),
                'join_date': user_data.get('join_date', 'نامشخص'),
                'username': user_data.get('username', ''),
                'requested_date': user_data.get('requested_date', 'نامشخص')
            })
    
    if not pending_users:
        await callback.answer(
            "✅ هیچ کاربر جدیدی در انتظار تایید نیست!" if lang == "fa" else "✅ No new users pending approval!",
            show_alert=True
        )
        return
    
    if lang == "fa":
        text = f"""
📋 <b>کاربران در انتظار تایید</b>

👥 تعداد: {len(pending_users)}

روی هر کاربر کلیک کنید تا تایید یا رد شود:
"""
    else:
        text = f"""
📋 <b>Users Pending Approval</b>

👥 Count: {len(pending_users)}

Click on each user to approve or reject:
"""
    
    buttons = []
    for user in pending_users[:20]:
        name = html.escape(user['name'][:20])
        username = f" @{html.escape(user['username'])}" if user['username'] else ""
        requested_date = user.get('requested_date', '')
        if requested_date and requested_date != 'نامشخص':
            try:
                date_obj = datetime.fromisoformat(requested_date)
                date_str = date_obj.strftime('%H:%M')
            except:
                date_str = ''
        else:
            date_str = ''
        
        label = f"🆕 {name}{username} - ID: {user['id']} {date_str}"
        buttons.append([InlineKeyboardButton(
            text=label[:55],
            callback_data=f"admin_approve_user_{user['id']}"
        )])
    
    if len(pending_users) > 20:
        buttons.append([InlineKeyboardButton(
            text=f"... و {len(pending_users) - 20} کاربر دیگر" if lang == "fa" else f"... and {len(pending_users) - 20} more users",
            callback_data="noop"
        )])
    
    buttons.append([InlineKeyboardButton(
        text="🔙 برگشت به تنظیمات فروش" if lang == "fa" else "🔙 Back to Shop Settings",
        callback_data="admin_shop_settings"
    )])
    
    await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")


