@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_shop_message'))
async def admin_shop_message_save(message: Message):
    """ذخیره پیام جدید فروش"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply("❌ لغو شد" if lang == "fa" else "❌ Cancelled")
        return
    
    new_message = message.text or message.caption or ""
    
    if not new_message.strip():
        await message.reply("❌ پیام نمی‌تواند خالی باشد!" if lang == "fa" else "❌ Message cannot be empty!")
        return
    
    SHOP_STATUS['message'] = new_message
    SHOP_STATUS['last_updated'] = datetime.now().isoformat()
    configs_pool['shop_status'] = SHOP_STATUS
    save_all()
    
    user_states.pop(admin_id, None)
    
    await message.reply(
        f"✅ پیام فروش با موفقیت بروزرسانی شد!" if lang == "fa" else "✅ Shop message updated successfully!"
    )
    class FakeCallback:
        def __init__(self, message, data):
            self.from_user = message.from_user
            self.message = message
            self.data = data
        
        async def answer(self, *args, **kwargs):
            pass
    
    fake_callback = FakeCallback(message, "admin_shop_settings")
    await admin_shop_settings(fake_callback)

@dp.callback_query(F.data.startswith("confirm_approve_user_"))
async def confirm_approve_user(callback: CallbackQuery):
    """تایید و فعال‌سازی کاربر"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    try:
        target_id = int(callback.data.split("_")[3])
    except (ValueError, IndexError):
        await callback.answer("❌ خطا در پردازش", show_alert=True)
        return
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    target = get_user(target_id)
    
    if not target:
        await callback.answer("❌ کاربر یافت نشد!", show_alert=True)
        return
    uid = str(target_id)
    if uid in users:
        users[uid]['approved_by_admin'] = True
        users[uid]['approved_date'] = datetime.now().isoformat()
        users[uid]['registration_status'] = 'approved'
        users[uid]['updated_at'] = datetime.now().isoformat()
        save_json(DB_FILES['users'], users)
        try:
            user_lang = target.get('lang', 'fa')
            if user_lang == "fa":
                await bot.send_message(
                    target_id,
                    f"{premium_emoji('success', '✅')} <b>حساب شما توسط ادمین تایید شد!</b>\n\n"
                    f"اکنون می‌توانید از تمام امکانات ربات استفاده کنید.\n"
                    f"برای شروع از منوی اصلی استفاده کنید."
                )
            else:
                await bot.send_message(
                    target_id,
                    f"{premium_emoji('success', '✅')} <b>Your account has been approved by admin!</b>\n\n"
                    f"You can now use all bot features.\n"
                    f"Use the main menu to get started."
                )
        except Exception as e:
            logger.error(f"خطا در ارسال پیام تایید به کاربر {target_id}: {e}")
        if log_system:
            await log_system.log_admin_action(
                callback.from_user.id,
                f"تایید کاربر جدید {target_id}",
                details=f"نام: {target.get('name')}"
            )
        
        name_escaped = html.escape(target.get('name', f'کاربر_{target_id}'))
        try:
            await callback.message.delete()
        except:
            pass
        
        if lang == "fa":
            text = f"""
✅ <b>کاربر با موفقیت تایید شد!</b>

👤 نام: {name_escaped}
🆔 آیدی: <code>{target_id}</code>
📛 یوزرنیم: @{html.escape(target.get('username', ''))} if target.get('username') else 'ندارد'

📨 پیام تایید به کاربر ارسال شد.
"""
        else:
            text = f"""
✅ <b>User approved successfully!</b>

👤 Name: {name_escaped}
🆔 ID: <code>{target_id}</code>
📛 Username: @{html.escape(target.get('username', ''))} if target.get('username') else 'None'

📨 Approval message sent to user.
"""
        
        buttons = [
            [InlineKeyboardButton(
                text="🔙 بازگشت به لیست" if lang == "fa" else "🔙 Back to List",
                callback_data="admin_pending_users"
            )],
            [InlineKeyboardButton(
                text="🔙 پنل ادمین" if lang == "fa" else "🔙 Admin Panel",
                callback_data="admin_panel"
            )]
        ]
        
        await callback.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode=ParseMode.HTML)
        
        await callback.answer()
    else:
        await callback.answer("❌ کاربر در دیتابیس یافت نشد!", show_alert=True)


