async def auto_save_worker():
    """کارگر پس‌زمینه برای ذخیره‌سازی خودکار"""
    logger.info("🔄 کارگر ذخیره‌سازی خودکار راه‌اندازی شد")
    
    while True:
        try:
            try:
                operation = await asyncio.wait_for(_save_queue.get(), timeout=300)
                logger.debug(f"📥 درخواست ذخیره‌سازی دریافت شد: {operation}")
            except asyncio.TimeoutError:
                logger.debug("⏰ ذخیره‌سازی دوره‌ای 5 دقیقه")
            save_all()
            while not _save_queue.empty():
                try:
                    _save_queue.get_nowait()
                except asyncio.QueueEmpty:
                    break
                    
        except asyncio.CancelledError:
            logger.info("کارگر ذخیره‌سازی متوقف شد")
            break
        except Exception as e:
            logger.error(f"❌ خطا در کارگر ذخیره‌سازی: {e}", exc_info=True)
            await asyncio.sleep(10)

@dp.message(Command("save"))
async def cmd_save(message: Message):
    """ذخیره‌سازی دستی دیتابیس + گرفتن بکاپ (فقط ادمین)"""
    if message.from_user.id != ADMIN_ID_INT:
        return
    
    logger.info(f"👑 ادمین درخواست ذخیره‌سازی دستی کرد")
    status_msg = await message.reply("⏳ در حال ذخیره‌سازی و گرفتن بکاپ...")
    
    start = time.time()
    success = save_all()
    
    if not success:
        await status_msg.edit_text("❌ خطا در ذخیره‌سازی دیتابیس! لاگ‌ها را بررسی کنید.")
        return
    try:
        backup_database()
        backup_success = True
    except Exception as e:
        logger.error(f"❌ خطا در گرفتن بکاپ: {e}")
        backup_success = False
    
    elapsed = time.time() - start
    total_size = 0
    file_sizes = {}
    for name, file_path in DB_FILES.items():
        if os.path.exists(file_path):
            size = os.path.getsize(file_path)
            total_size += size
            file_sizes[name] = size
    backup_count = len(get_backup_list())
    if backup_success:
        backup_status = "✅ بکاپ گرفته شد"
    else:
        backup_status = "❌ خطا در گرفتن بکاپ"
    def format_size(bytes_val):
        for unit in ['B', 'KB', 'MB', 'GB']:
            if bytes_val < 1024:
                return f"{bytes_val:.1f} {unit}"
            bytes_val /= 1024
        return f"{bytes_val:.1f} TB"
    
    text = f"""
✅ <b>ذخیره‌سازی کامل شد!</b>

━━━━━━━━━━━━━━━━━━━━━━
⏱ زمان: {elapsed:.2f} ثانیه
💾 حجم کل: {format_size(total_size)}
📁 تعداد بکاپ‌ها: {backup_count}
📊 وضعیت بکاپ: {backup_status}
━━━━━━━━━━━━━━━━━━━━━━

📋 <b>جزئیات فایل‌ها:</b>
"""
    
    for name, size in file_sizes.items():
        text += f"• {name}: {format_size(size)}\n"
    
    text += f"""
━━━━━━━━━━━━━━━━━━━━━━
📊 <b>آمار دیتابیس:</b>
• 👥 کاربران: {len(users)}
• 📋 سفارشات: {len(orders)}
• 📦 کانفیگ‌ها: {len(configs_pool.get('configs', []))}
• 🏷️ کوپن‌ها: {len(COUPONS)}
"""
    
    await status_msg.edit_text(text, parse_mode=ParseMode.HTML)
@dp.message(Command("dbstatus"))
async def cmd_db_status(message: Message):
    """بررسی وضعیت فایل‌های دیتابیس (فقط ادمین)"""
    if message.from_user.id != ADMIN_ID_INT:
        return
    
    logger.info(f"👑 ادمین درخواست بررسی وضعیت دیتابیس کرد")
    
    status_lines = ["📁 <b>وضعیت فایل‌های دیتابیس:</b>\n"]
    
    total_size = 0
    for name, path in DB_FILES.items():
        if os.path.exists(path):
            size = os.path.getsize(path)
            total_size += size
            modified = datetime.fromtimestamp(os.path.getmtime(path))
            status_lines.append(f"✅ {name}: {size:,} bytes | {modified.strftime('%H:%M:%S')}")
        else:
            status_lines.append(f"❌ {name}: وجود ندارد")
    
    status_lines.append(f"\n💾 حجم کل: {total_size / 1024:.1f} KB")
    status_lines.append(f"📊 داده‌های در حافظه:")
    status_lines.append(f"• کاربران: {len(users)}")
    status_lines.append(f"• سفارشات: {len(orders)}")
    status_lines.append(f"• کانفیگ‌ها: {len(configs_pool.get('configs', []))}")
    status_lines.append(f"• کش: {len(_db_cache)} فایل")
    
    await message.reply("\n".join(status_lines), parse_mode=ParseMode.HTML)
    
    
def request_save(operation: str = "unknown"):
    """درخواست ذخیره‌سازی (non-blocking)"""
    global _save_task
    current_time = time.time()
    if operation in _last_save_time:
        if current_time - _last_save_time[operation] < 10:
            return
    
    _last_save_time[operation] = current_time
    
    try:
        _save_queue.put_nowait(operation)
        logger.debug(f"📤 درخواست ذخیره‌سازی به صف اضافه شد: {operation}")
    except Exception as e:
        logger.error(f"❌ خطا در افزودن به صف ذخیره‌سازی: {e}")

   


@dp.message(Command("cleanup_backups"))
async def cmd_cleanup_backups(message: Message):
    """پاکسازی بکاپ‌های قدیمی از پوشه اصلی (فقط ادمین)"""
    if message.from_user.id != ADMIN_ID_INT:
        return
    
    logger.info("🧹 شروع پاکسازی بکاپ‌های قدیمی...")
    
    cleanup_report = []
    data_dir = DATA_DIR
    if os.path.exists(data_dir):
        for file in os.listdir(data_dir):
            if file.endswith('.backup') or file.endswith('.tmp'):
                file_path = os.path.join(data_dir, file)
                try:
                    os.remove(file_path)
                    cleanup_report.append(f"🗑 حذف شد: {file}")
                    logger.info(f"حذف فایل اضافی: {file}")
                except Exception as e:
                    cleanup_report.append(f"❌ خطا در حذف {file}: {e}")
    backup_dir = os.path.join(data_dir, "backups")
    os.makedirs(backup_dir, exist_ok=True)
    for name in ['users', 'orders', 'referrals', 'configs', 'feedback', 'chats', 'blacklist']:
        main_file = os.path.join(data_dir, f"{name}.json")
        backup_file = os.path.join(data_dir, f"{name}.json.backup")
        
        if not os.path.exists(main_file) and os.path.exists(backup_file):
            import shutil
            shutil.copy2(backup_file, main_file)
            cleanup_report.append(f"🔄 بازیابی شد: {name}.json از بکاپ")
            logger.warning(f"فایل {name}.json از بکاپ بازیابی شد")
    if cleanup_report:
        report_text = "🧹 <b>گزارش پاکسازی:</b>\n\n" + "\n".join(cleanup_report)
    else:
        report_text = "✅ هیچ فایل اضافی یافت نشد"
    
    await message.reply(report_text, parse_mode=ParseMode.HTML)
    
def _repair_json_file(file: str) -> dict:
    """تلاش برای تعمیر فایل JSON خراب"""
    try:
        backup_file = file + '.backup'
        if os.path.exists(file):
            os.rename(file, backup_file)
        logger.warning(f"🔧 فایل خراب {os.path.basename(file)} بکاپ گرفته شد")
        save_json(file, {})
        return {}
    except:
        return {}

