def load_all_data():
    """بارگذاری تمام دیتابیس‌ها - با بازیابی از بکاپ در صورت نیاز"""
    global users, orders, referrals, configs_pool, feedbacks, chats, BLACKLIST
    global AI_FEATURE_ENABLED
    global SHOP_STATUS, USER_INBOUND_SELECTION
    global TEST_SERVICE_STATUS, USER_TEST_USAGE
    global READY_PACKAGES, USER_TEST_SETTINGS
    
    logger.info("=" * 60)
    logger.info("🔄 شروع بارگذاری دیتابیس...")
    for name, path in DB_FILES.items():
        exists = os.path.exists(path)
        size = os.path.getsize(path) if exists else 0
        logger.info(f"📂 {name}: {path} - {'✅ وجود دارد' if exists else '❌ وجود ندارد'} ({size:,} bytes)")
    
    try:
        users_data = load_json(DB_FILES['users'], use_cache=False)
        orders_data = load_json(DB_FILES['orders'], use_cache=False)
        referrals_data = load_json(DB_FILES['referrals'], use_cache=False)
        configs_data = load_json(DB_FILES['configs'], use_cache=False)
        feedbacks_data = load_json(DB_FILES['feedback'], use_cache=False)
        chats_data = load_json(DB_FILES['chats'], use_cache=False)
        users = users_data if users_data and isinstance(users_data, dict) else {}
        orders = orders_data if orders_data and isinstance(orders_data, dict) else {}
        referrals = referrals_data if referrals_data and isinstance(referrals_data, dict) else {}
        feedbacks = feedbacks_data if feedbacks_data and isinstance(feedbacks_data, dict) else {}
        chats = chats_data if chats_data and isinstance(chats_data, dict) else {}
        if configs_data and isinstance(configs_data, dict):
            configs_pool = configs_data
        else:
            configs_pool = {}
        blacklist_data = load_json(DB_FILES['blacklist'], use_cache=False)
        if blacklist_data and 'users' in blacklist_data:
            BLACKLIST = set(blacklist_data.get('users', []))
        else:
            BLACKLIST = set()
        ai_settings = configs_pool.get('ai_settings', {})
        AI_FEATURE_ENABLED = ai_settings.get('button_enabled', True)
        logger.info(f"🤖 وضعیت دکمه AI: {'فعال' if AI_FEATURE_ENABLED else 'غیرفعال'}")
        if 'shop_status' in configs_pool:
            SHOP_STATUS = configs_pool['shop_status']
            logger.info(f"🛒 وضعیت فروش: {'باز' if SHOP_STATUS.get('open', True) else 'بسته'}")
        else:
            SHOP_STATUS = {
                'open': True, 
                'message': 'فروش به دلیل بروزرسانی موقتاً بسته شده است.', 
                'last_updated': datetime.now().isoformat()
            }
        test_settings = configs_pool.get('test_service', {})
        if test_settings:
            TEST_SERVICE_STATUS.update(test_settings)
            logger.info(f"🧪 تنظیمات تست بارگذاری شد: {'فعال' if TEST_SERVICE_STATUS.get('enabled') else 'غیرفعال'}")
            logger.info(f"🧪 اینباندهای تست: {TEST_SERVICE_STATUS.get('inbound_ids', [])}")
        else:
            TEST_SERVICE_STATUS = {
                'enabled': False,
                'volume': 5,
                'volume_mb': 5120,
                'days': 3,
                'max_tests': 1,
                'inbound_ids': [],  # لیست خالی
                'message': '🎁 یک سرویس تست {volume}GB / {days} روز برای شما فعال شد!',
                'last_updated': datetime.now().isoformat()
            }
            configs_pool['test_service'] = TEST_SERVICE_STATUS
            logger.info("🧪 تنظیمات پیش‌فرض تست ایجاد شد")
        load_ready_packages()
        load_user_test_settings()# این تابع READY_PACKAGES را از configs_pool بارگذاری می‌کند
        for cat in READY_PACKAGES.get('categories', []):
            inbound_ids = cat.get('inbound_ids', [])
            if inbound_ids:
                logger.info(f"📡 دسته {cat.get('name')} - اینباندها: {inbound_ids}")
        load_test_usage()
        load_user_inbound_selections()
        logger.info("=" * 60)
        logger.info(f"📊 نتایج بارگذاری:")
        logger.info(f"  ✅ کاربران: {len(users)}")
        logger.info(f"  ✅ سفارشات: {len(orders)}")
        logger.info(f"  ✅ رفرال‌ها: {len(referrals)}")
        logger.info(f"  ✅ کانفیگ‌ها: {len(configs_pool.get('configs', []))}")
        logger.info(f"  ✅ بازخوردها: {len(feedbacks)}")
        logger.info(f"  ✅ چت‌ها: {len(chats)}")
        logger.info(f"  ✅ لیست سیاه: {len(BLACKLIST)}")
        logger.info(f"  ✅ کاربران تست‌دهنده: {len(USER_TEST_USAGE)}")
        logger.info(f"  ✅ وضعیت تست: {'فعال' if TEST_SERVICE_STATUS.get('enabled') else 'غیرفعال'}")
        logger.info(f"  ✅ اینباندهای تست: {TEST_SERVICE_STATUS.get('inbound_ids', [])}")
        logger.info(f"  ✅ بسته‌های آماده: {len(READY_PACKAGES.get('categories', []))} دسته")
        logger.info("=" * 60)
        if len(users) == 0 and len(orders) == 0:
            logger.warning("⚠️ همه دیتابیس‌ها خالی هستند! تلاش برای بازیابی از بکاپ کامل...")
            try_full_restore_from_backup()
        _init_default_settings_if_needed()
        migrate_old_data()
        
        logger.info("✅ بارگذاری کامل دیتابیس با موفقیت انجام شد")
        return True
        
    except Exception as e:
        logger.error(f"❌ خطا در بارگذاری دیتابیس: {e}", exc_info=True)
        _init_empty_databases()
        return False
    
    
    
def load_test_usage():
    """بارگذاری اطلاعات تست کاربران"""
    global USER_TEST_USAGE
    try:
        test_file = os.path.join(DATA_DIR, "test_usage.json")
        if os.path.exists(test_file):
            with open(test_file, 'r', encoding='utf-8') as f:
                USER_TEST_USAGE = json.load(f)
            logger.info(f"✅ اطلاعات تست کاربران بارگذاری شد: {len(USER_TEST_USAGE)} کاربر")
        else:
            USER_TEST_USAGE = {}
            with open(test_file, 'w', encoding='utf-8') as f:
                json.dump({}, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.error(f"❌ خطا در بارگذاری تست: {e}")
        USER_TEST_USAGE = {}

def save_test_usage():
    """ذخیره اطلاعات تست کاربران"""
    try:
        test_file = os.path.join(DATA_DIR, "test_usage.json")
        with open(test_file, 'w', encoding='utf-8') as f:
            json.dump(USER_TEST_USAGE, f, ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        logger.error(f"❌ خطا در ذخیره تست: {e}")
        return False

def get_user_test_info(user_id: int) -> dict:
    """دریافت اطلاعات تست کاربر"""
    uid = str(user_id)
    return USER_TEST_USAGE.get(uid, {
        'count': 0,
        'last_test': None,
        'last_order_id': None
    })

def increment_user_test(user_id: int, order_id: int = None) -> dict:
    """افزایش تعداد تست کاربر و ذخیره"""
    uid = str(user_id)
    user_data = USER_TEST_USAGE.get(uid, {
        'count': 0,
        'last_test': None,
        'last_order_id': None
    })
    
    user_data['count'] = user_data.get('count', 0) + 1
    user_data['last_test'] = datetime.now().isoformat()
    if order_id:
        user_data['last_order_id'] = order_id
    
    USER_TEST_USAGE[uid] = user_data
    save_test_usage()
    return user_data

def can_user_take_test(user_id: int) -> tuple:
    """بررسی اینکه آیا کاربر می‌تواند تست بگیرد"""
    if not TEST_SERVICE_STATUS.get('enabled', False):
        return False, 0, "❌ تست سرویس در حال حاضر غیرفعال است."
    
    user_data = get_user_test_info(user_id)
    used = user_data.get('count', 0)
    max_tests = TEST_SERVICE_STATUS.get('max_tests', 1)
    remaining = max_tests - used
    
    if remaining <= 0:
        return False, 0, f"⚠️ شما قبلاً از سقف تست مجاز ({max_tests} بار) استفاده کرده‌اید."
    
    return True, remaining, None

def get_test_stats() -> dict:
    """دریافت آمار تست"""
    total_users = len(USER_TEST_USAGE)
    total_tests = sum(data.get('count', 0) for data in USER_TEST_USAGE.values())
    
    top_users = []
    for uid, data in USER_TEST_USAGE.items():
        top_users.append({
            'user_id': int(uid),
            'count': data.get('count', 0),
            'last_test': data.get('last_test', 'نامشخص')
        })
    top_users.sort(key=lambda x: x['count'], reverse=True)
    
    return {
        'total_users': total_users,
        'total_tests': total_tests,
        'top_users': top_users[:10]
    }

def try_restore_from_backup_for_file(file_type: str) -> Optional[dict]:
    """تلاش برای بازیابی یک فایل خاص از بکاپ"""
    backup_dir = os.path.join(DATA_DIR, 'backups')
    if not os.path.exists(backup_dir):
        return None
    backups = [f for f in os.listdir(backup_dir) if f.startswith('full_backup_') and f.endswith('.json')]
    if not backups:
        return None
    
    backups.sort(reverse=True)
    latest_backup = os.path.join(backup_dir, backups[0])
    
    try:
        with open(latest_backup, 'r', encoding='utf-8') as f:
            data = json.load(f)
        
        if file_type == 'users':
            return data.get('users', {})
        elif file_type == 'orders':
            return data.get('orders', {})
        elif file_type == 'referrals':
            return data.get('referrals', {})
        elif file_type == 'configs':
            return data.get('configs', {'configs': [], 'last_id': 0})
        elif file_type == 'feedback':
            return data.get('feedback', {})
        elif file_type == 'chats':
            return data.get('chats', {})
    except Exception as e:
        logger.error(f"خطا در بازیابی {file_type} از بکاپ: {e}")
        return None

def try_full_restore_from_backup():
    """تلاش برای بازیابی کامل از آخرین بکاپ"""
    global users, orders, referrals, configs_pool, feedbacks, chats, BLACKLIST
    
    backup_dir = os.path.join(DATA_DIR, 'backups')
    backups = [f for f in os.listdir(backup_dir) if f.startswith('full_backup_') and f.endswith('.json')]
    
    if not backups:
        logger.warning("⚠️ هیچ بکاپ کاملی یافت نشد")
        return False
    
    backups.sort(reverse=True)
    latest_backup = os.path.join(backup_dir, backups[0])
    
    logger.info(f"🔄 تلاش برای بازیابی کامل از بکاپ: {backups[0]}")
    
    try:
        with open(latest_backup, 'r', encoding='utf-8') as f:
            data = json.load(f)
        
        if data.get('users'):
            users = data['users']
            logger.info(f"✅ {len(users)} کاربر از بکاپ بازیابی شد")
        if data.get('orders'):
            orders = data['orders']
            logger.info(f"✅ {len(orders)} سفارش از بکاپ بازیابی شد")
        if data.get('referrals'):
            referrals = data['referrals']
            logger.info(f"✅ {len(referrals)} رفرال از بکاپ بازیابی شد")
        if data.get('configs'):
            configs_pool = data['configs']
            logger.info(f"✅ {len(configs_pool.get('configs', []))} کانفیگ از بکاپ بازیابی شد")
        if data.get('feedback'):
            feedbacks = data['feedback']
        if data.get('chats'):
            chats = data['chats']
        if data.get('blacklist'):
            BLACKLIST = set(data['blacklist'].get('users', []))
        save_all()
        
        logger.info(f"✅ بازیابی کامل از بکاپ با موفقیت انجام شد")
        return True
        
    except Exception as e:
        logger.error(f"❌ خطا در بازیابی کامل از بکاپ: {e}")
        return False

