@dp.message(Command("checkdata"))
async def cmd_check_data(message: Message):
    """بررسی محتوای فایل‌های دیتابیس (فقط ادمین)"""
    if message.from_user.id != ADMIN_ID_INT:
        return
    
    logger.info(f"👑 ادمین درخواست بررسی داده‌ها کرد")
    
    report = []
    report.append("📊 <b>بررسی فایل‌های دیتابیس:</b>\n")
    
    for name, path in DB_FILES.items():
        if os.path.exists(path):
            size = os.path.getsize(path)
            with open(path, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                    if isinstance(data, dict):
                        count = len(data)
                    elif isinstance(data, list):
                        count = len(data)
                    else:
                        count = "نامشخص"
                    report.append(f"✅ {name}: {size:,} bytes - {count} آیتم")
                except:
                    report.append(f"❌ {name}: {size:,} bytes - خطا در خواندن")
        else:
            report.append(f"❌ {name}: وجود ندارد")
    report.append(f"\n📊 <b>آمار حافظه:</b>")
    report.append(f"👥 کاربران در RAM: {len(users)}")
    report.append(f"📋 سفارشات در RAM: {len(orders)}")
    report.append(f"📦 کانفیگ‌ها در RAM: {len(configs_pool.get('configs', []))}")
    
    await message.reply("\n".join(report), parse_mode=ParseMode.HTML)
    
