@dp.message(Command("blacklist"))
async def cmd_blacklist(message: Message):
    """دستور مشاهده لیست سیاه (فقط ادمین)"""
    if message.from_user.id != ADMIN_ID_INT:
        return
    
    if not BLACKLIST:
        await message.reply("✅ لیست سیاه خالی است.")
        return
    
    users_info = []
    for uid in BLACKLIST:
        user_info = await get_user_info_from_telegram(uid)
        users_info.append(f"🆔 {uid} - 👤 {user_info['full_name']} - 📛 @{user_info['username']}" if user_info['username'] else f"🆔 {uid} - 👤 {user_info['full_name']}")
    
    text = "🚫 لیست سیاه:\n\n" + "\n".join(users_info)
    await message.reply(text)

async def block_unauthorized(message: Message, user_id: int) -> bool:
    """بلاک کاربر غیرمجاز - چک لیست سیاه"""
    user_state = user_states.get(user_id, {})
    if user_state.get('awaiting_receipt'):
        return False
    if user_id == ADMIN_ID_INT:
        return False
    if user_id in BLACKLIST:
        logger.warning(f"⛔ کاربر مسدود {user_id} تلاش به استفاده از ربات کرد")
        await notify_blacklisted_user(user_id, message)
        return True
    
    return False

async def notify_blacklisted_user(user_id: int, message: Message = None):
    """ارسال پیام به کاربر مسدود شده"""
    try:
        lang = get_user(user_id).get('lang', 'fa')
        logger.info(f"🔍 SUPPORT_USERNAME from config: '{SUPPORT_USERNAME}'")
        if SUPPORT_USERNAME and SUPPORT_USERNAME.strip():
            support_contact = SUPPORT_USERNAME
        else:
            support_contact = "@my_name_is_navid"
            logger.warning(f"⚠️ SUPPORT_USERNAME خالی است، از مقدار پیش‌فرض استفاده شد: {support_contact}")
        emoji_result = premium_emoji('access_denied', '⛔')
        logger.info(f"🔍 premium_emoji('access_denied', '⛔') = '{emoji_result}'")
        
        if lang == "fa":
            text = f"""
{emoji_result} <b>دسترسی مسدود شده</b>

شما در لیست سیاه قرار دارید و امکان استفاده از ربات را ندارید.

در صورت نیاز با پشتیبانی تماس بگیرید:
{support_contact}
"""
        else:
            text = f"""
{emoji_result} <b>Access Blocked</b>

You are blacklisted and cannot use this bot.

Contact support if needed:
{support_contact}
"""
        logger.info(f"🔍 متن ارسالی: {text[:200]}...")
        
        if message:
            await message.reply(text, parse_mode=ParseMode.HTML)
        else:
            await bot.send_message(user_id, text, parse_mode=ParseMode.HTML)
            
        logger.info(f"📨 پیام مسدودیت به کاربر {user_id} ارسال شد")
        return True
    except Exception as e:
        logger.error(f"❌ خطا در ارسال پیام به کاربر مسدود {user_id}: {e}")
        return False

import html  # ✅ حتماً در بالای فایل import شده باشد

async def get_user_info_from_telegram(user_id: int) -> dict:
    """دریافت اطلاعات کاربر از تلگرام با escape برای استفاده در HTML"""
    try:
        chat = await bot.get_chat(user_id)
        first_name_raw = chat.first_name or 'نامشخص'
        last_name_raw = chat.last_name or ''
        full_name_raw = f"{first_name_raw} {last_name_raw}".strip() or 'کاربر ناشناس'
        username_raw = chat.username or ''
        
        return {
            'id': user_id,
            'first_name': html.escape(first_name_raw),
            'last_name': html.escape(last_name_raw),
            'username': html.escape(username_raw),
            'full_name': html.escape(full_name_raw)
        }
    except Exception as e:
        logger.error(f"خطا در دریافت اطلاعات کاربر {user_id}: {e}")
        return {
            'id': user_id,
            'first_name': 'نامشخص',
            'last_name': '',
            'username': '',
            'full_name': f'کاربر ناشناس ({user_id})'
        }



def save_blacklist():
    """ذخیره لیست سیاه در فایل"""
    try:
        blacklist_file = os.path.join(DATA_DIR, "blacklist.json")
        blacklist_data = {
            'users': list(BLACKLIST),  # تبدیل set به list برای JSON
            'last_updated': datetime.now().isoformat(),
            'count': len(BLACKLIST)
        }
        with open(blacklist_file, 'w', encoding='utf-8') as f:
            json.dump(blacklist_data, f, ensure_ascii=False, indent=2)
        logger.info(f"✅ لیست سیاه ذخیره شد - {len(BLACKLIST)} کاربر")
        return True
    except Exception as e:
        logger.error(f"❌ خطا در ذخیره لیست سیاه: {e}")
        return False


def load_blacklist():
    """بارگذاری لیست سیاه از فایل"""
    global BLACKLIST
    try:
        blacklist_file = os.path.join(DATA_DIR, "blacklist.json")
        if os.path.exists(blacklist_file):
            with open(blacklist_file, 'r', encoding='utf-8') as f:
                data = json.load(f)
            users_list = data.get('users', [])
            BLACKLIST = set(users_list)
            
            logger.info(f"✅ لیست سیاه بارگذاری شد - {len(BLACKLIST)} کاربر")
            if BLACKLIST:
                logger.info(f"📋 کاربران مسدود: {BLACKLIST}")
        else:
            BLACKLIST = set()
            logger.info("📭 فایل لیست سیاه وجود ندارد - ایجاد set خالی")
            save_blacklist()
    except Exception as e:
        logger.error(f"❌ خطا در بارگذاری لیست سیاه: {e}")
        BLACKLIST = set()


def add_to_blacklist(user_id: int, notify: bool = True) -> bool:
    """افزودن کاربر به لیست سیاه"""
    global BLACKLIST
    if user_id not in BLACKLIST:
        BLACKLIST.add(user_id)
        save_json(DB_FILES['blacklist'], {
            'users': list(BLACKLIST),
            'last_updated': datetime.now().isoformat(),
            'count': len(BLACKLIST)
        })
        logger.info(f"🚫 کاربر {user_id} به لیست سیاه اضافه شد - تعداد: {len(BLACKLIST)}")
        if notify:
            asyncio.create_task(notify_blacklisted_user(user_id))
        
        return True
    return False




def remove_from_blacklist(user_id: int) -> bool:
    """حذف کاربر از لیست سیاه"""
    global BLACKLIST
    if user_id in BLACKLIST:
        BLACKLIST.discard(user_id)
        save_json(DB_FILES['blacklist'], {
            'users': list(BLACKLIST),
            'last_updated': datetime.now().isoformat(),
            'count': len(BLACKLIST)
        })
        logger.info(f"✅ کاربر {user_id} از لیست سیاه خارج شد - تعداد: {len(BLACKLIST)}")
        return True
    return False


def is_blacklisted(user_id: int) -> bool:
    """بررسی وجود کاربر در لیست سیاه"""
    return user_id in BLACKLIST


def get_blacklist_users() -> list:
    """دریافت لیست کاربران مسدود"""
    return list(BLACKLIST)


def clear_blacklist() -> int:
    """پاکسازی کامل لیست سیاه"""
    global BLACKLIST
    count = len(BLACKLIST)
    BLACKLIST.clear()
    save_json(DB_FILES['blacklist'], {
        'users': [],
        'last_updated': datetime.now().isoformat(),
        'count': 0
    })
    logger.info(f"🗑 لیست سیاه پاکسازی شد - {count} کاربر")
    return count
def get_user(user_id: int, username: str = None) -> dict:
    """دریافت اطلاعات کاربر یا ایجاد کاربر جدید با وضعیت‌های مختلف"""
    uid = str(user_id)
    if uid not in users:
        user_name = username or f"کاربر_{user_id}"
        
        logger.info(f"👤 ایجاد کاربر جدید: {user_id} - نام: {user_name}")
        manual_approval = configs_pool.get('manual_approval_settings', {})
        approval_enabled = manual_approval.get('enabled', False)
        is_admin = (user_id == ADMIN_ID_INT)
        users[uid] = {
            'id': user_id,
            'name': user_name,
            'username': username or '',
            'telegram_username': username or '',
            'balance': 0,
            'total_spent': 0,
            'total_purchases': 0,
            'last_purchase_date': None,
            'volume': 1,
            'days': 30,
            'lang': 'fa',
            'is_active': True,
            'verified': False,
            'has_purchased': False,
            'referred_by': None,
            'join_date': datetime.now().strftime('%Y/%m/%d'),
            'created_at': datetime.now().isoformat(),
            'updated_at': datetime.now().isoformat(),
            'notes': '',
            'coupon_code': None,
            'coupon_discount': 0,
            'coupon_applied': False,
            'approved_by_admin': True if is_admin else False,  # ✅ ادمین همیشه تایید شده
            'approved_date': datetime.now().isoformat() if is_admin else None,
            'requested_approval': False,
            'registration_status': 'approved' if is_admin else 'pending'  # ✅ ادمین وضعیت approved
        }
        
        save_json(DB_FILES['users'], users)
        
        if is_admin:
            logger.info(f"👑 کاربر ادمین {user_id} ایجاد شد - وضعیت: approved")
        else:
            logger.info(f"✅ کاربر جدید {user_id} ایجاد شد - وضعیت: pending")
        
        return users[uid]
    user = users[uid]
    modified = False
    if username and user.get('telegram_username') != username:
        user['telegram_username'] = username
        user['username'] = username
        modified = True
    required_fields = {
        'name': f"کاربر_{user_id}",
        'username': '',
        'telegram_username': '',
        'balance': 0,
        'total_spent': 0,
        'total_purchases': 0,
        'last_purchase_date': None,
        'volume': 1,
        'days': 30,
        'lang': 'fa',
        'is_active': True,
        'verified': False,
        'has_purchased': False,
        'referred_by': None,
        'join_date': datetime.now().strftime('%Y/%m/%d'),
        'created_at': datetime.now().isoformat(),
        'updated_at': datetime.now().isoformat(),
        'notes': '',
        'coupon_code': None,
        'coupon_discount': 0,
        'coupon_applied': False,
        'approved_by_admin': False,
        'approved_date': None,
        'requested_approval': False,
        'registration_status': 'pending'
    }
    
    for key, default_value in required_fields.items():
        if key not in user:
            user[key] = default_value
            modified = True
    if user_id == ADMIN_ID_INT:
        if not user.get('approved_by_admin', False):
            user['approved_by_admin'] = True
            user['approved_date'] = datetime.now().isoformat()
            user['registration_status'] = 'approved'
            modified = True
            logger.info(f"👑 کاربر ادمین {user_id} تایید شد")
    if user.get('has_purchased', False) and not user.get('approved_by_admin', False):
        user['approved_by_admin'] = True
        user['approved_date'] = datetime.now().isoformat()
        user['registration_status'] = 'approved'
        modified = True
        logger.info(f"✅ کاربر {user_id} به دلیل داشتن خرید، خودکار تایید شد")
    if not user.get('approved_by_admin', False) and user_id != ADMIN_ID_INT:
        manual_approval = configs_pool.get('manual_approval_settings', {})
        if not manual_approval.get('enabled', False):
            user['approved_by_admin'] = True
            user['approved_date'] = datetime.now().isoformat()
            user['registration_status'] = 'approved'
            modified = True
            logger.info(f"✅ کاربر {user_id} به دلیل غیرفعال بودن تایید دستی، خودکار تایید شد")
    if modified:
        user['updated_at'] = datetime.now().isoformat()
        save_json(DB_FILES['users'], users)
    
    return user



def can_user_purchase(user_id: int) -> tuple:
    """
    بررسی اینکه کاربر مجاز به خرید و مشاهده موجودی است یا خیر
    
    Returns:
        (can_purchase: bool, message: str)
    """
    manual_approval = configs_pool.get('manual_approval_settings', {})
    if not manual_approval.get('enabled', False):
        return True, None
    
    user = get_user(user_id)
    if user.get('has_purchased', False):
        return True, None
    if user.get('approved_by_admin', False):
        return True, None
    lang = user.get('lang', 'fa')
    if lang == "fa":
        msg = "⚠️ حساب کاربری شما در انتظار تایید ادمین است.\nلطفاً پس از تایید، مجدداً تلاش کنید."
    else:
        msg = "⚠️ Your account is pending admin approval.\nPlease try again after approval."
    
    return False, msg

def save_coupon_to_user_db(user_id: int):
    """ذخیره کوپن در دیتابیس کاربر"""
    try:
        uid = str(user_id)
        if uid not in users:
            return
        
        user_state = user_states.get(user_id, {})
        coupon_code = user_state.get('coupon_code')
        coupon_applied = user_state.get('coupon_applied', False)
        coupon_discount = user_state.get('coupon_discount', 0)
        if coupon_applied and coupon_code:
            coupon = COUPONS.get(coupon_code)
            if coupon and coupon.get('status') == 'active':
                if user_id not in coupon.get('used_by', []):
                    users[uid]['coupon_code'] = coupon_code
                    users[uid]['coupon_discount'] = coupon_discount
                    users[uid]['coupon_applied'] = True
                    save_json(DB_FILES['users'], users)
                    logger.info(f"📁 [save_coupon_to_user_db] کوپن {coupon_code} برای کاربر {user_id} در دیتابیس ذخیره شد")
                    return
                else:
                    logger.warning(f"⚠️ [save_coupon_to_user_db] کوپن {coupon_code} قبلاً مصرف شده است")
                    users[uid]['coupon_code'] = None
                    users[uid]['coupon_discount'] = 0
                    users[uid]['coupon_applied'] = False
                    save_json(DB_FILES['users'], users)
                    return
            else:
                logger.warning(f"⚠️ [save_coupon_to_user_db] کوپن {coupon_code} نامعتبر است")
                users[uid]['coupon_code'] = None
                users[uid]['coupon_discount'] = 0
                users[uid]['coupon_applied'] = False
                save_json(DB_FILES['users'], users)
                return
        if users[uid].get('coupon_applied', False):
            users[uid]['coupon_code'] = None
            users[uid]['coupon_discount'] = 0
            users[uid]['coupon_applied'] = False
            save_json(DB_FILES['users'], users)
            logger.info(f"🗑️ [save_coupon_to_user_db] کوپن کاربر {user_id} از دیتابیس پاک شد")
            
    except Exception as e:
        logger.error(f"❌ [save_coupon_to_user_db] خطا: {e}")

def load_coupon_from_user_db(user_id: int) -> dict:
    """بازیابی کوپن از دیتابیس کاربر"""
    result = {
        'coupon_code': None,
        'coupon_discount': 0,
        'coupon_applied': False
    }
    
    try:
        uid = str(user_id)
        if uid not in users:
            return result
        
        user = users[uid]
        coupon_code = user.get('coupon_code')
        coupon_applied = user.get('coupon_applied', False)
        coupon_discount = user.get('coupon_discount', 0)
        
        if coupon_applied and coupon_code:
            coupon = COUPONS.get(coupon_code)
            if coupon and coupon.get('status') == 'active':
                if user_id not in coupon.get('used_by', []):
                    logger.info(f"📁 [load_coupon_from_user_db] کوپن {coupon_code} از دیتابیس کاربر بازیابی شد")
                    return {
                        'coupon_code': coupon_code,
                        'coupon_discount': coupon_discount,
                        'coupon_applied': True
                    }
                else:
                    logger.warning(f"⚠️ [load_coupon_from_user_db] کوپن {coupon_code} قبلاً مصرف شده است")
                    users[uid]['coupon_code'] = None
                    users[uid]['coupon_discount'] = 0
                    users[uid]['coupon_applied'] = False
                    save_json(DB_FILES['users'], users)
            else:
                logger.warning(f"⚠️ [load_coupon_from_user_db] کوپن {coupon_code} نامعتبر است")
                users[uid]['coupon_code'] = None
                users[uid]['coupon_discount'] = 0
                users[uid]['coupon_applied'] = False
                save_json(DB_FILES['users'], users)
                
    except Exception as e:
        logger.error(f"❌ [load_coupon_from_user_db] خطا: {e}")
    
    return result

def clear_coupon_from_user_db(user_id: int):
    """پاک کردن کوپن از دیتابیس کاربر"""
    try:
        uid = str(user_id)
        if uid in users:
            users[uid]['coupon_code'] = None
            users[uid]['coupon_discount'] = 0
            users[uid]['coupon_applied'] = False
            save_json(DB_FILES['users'], users)
            logger.info(f"🗑️ [clear_coupon_from_user_db] کوپن کاربر {user_id} از دیتابیس پاک شد")
    except Exception as e:
        logger.error(f"❌ [clear_coupon_from_user_db] خطا: {e}")
