async def blacklist_add_user(message: Message):
    """دریافت آیدی کاربر و افزودن به لیست سیاه"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply(
            "❌ عملیات لغو شد" if lang == "fa" else "❌ Cancelled",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🔙 لیست سیاه" if lang=="fa" else "🔙 Blacklist", callback_data="admin_blacklist")]
            ])
        )
        return
    try:
        target_id = int(message.text.strip())
    except ValueError:
        await message.reply(
            "❌ لطفاً یک آیدی عددی معتبر وارد کنید!" if lang == "fa" else "❌ Please enter a valid numeric ID!"
        )
        return
    if target_id == ADMIN_ID_INT:
        await message.reply(
            "❌ نمی‌توانید ادمین را مسدود کنید!" if lang == "fa" else "❌ Cannot block admin!"
        )
