import asyncio
import time
from typing import Optional
from yarl import URL
import aiohttp
from aiohttp import ClientTimeout, CookieJar
CONNECTOR = None
HTTP_SESSION: Optional[aiohttp.ClientSession] = None
SENAI_COOKIE = None
COOKIE_TIME = 0
COOKIE_TTL = 3600  # یک ساعت

SENAI_CSRF = None
CSRF_TIME = 0
CSRF_TTL = 1800  # نیم ساعت

LOGIN_LOCK = asyncio.Lock()
INBOUND_CACHE = {
    "data": [],
    "time": 0,
    "loaded": False
}
INBOUND_CACHE_TTL = 30  # ثانیه
INBOUND_LOCK = asyncio.Lock()
LOGIN_TIMEOUT = ClientTimeout(total=10, connect=3)
API_TIMEOUT = ClientTimeout(total=5, connect=3)


def _get_base_url() -> URL:
    """دریافت Base URL بدون path"""
    panel_url = URL(SENAI_PANEL_URL)
    return URL(f"{panel_url.scheme}://{panel_url.host}:{panel_url.port}")


def _get_panel_host() -> str:
    """دریافت host پنل"""
    return URL(SENAI_PANEL_URL).host


async def _ensure_session():
    """اطمینان از وجود Session فعال"""
    global HTTP_SESSION, CONNECTOR
    
    if HTTP_SESSION is None or HTTP_SESSION.closed:
        CONNECTOR = aiohttp.TCPConnector(
            ssl=False,
            limit=50,
            limit_per_host=20,
            ttl_dns_cache=300,
            keepalive_timeout=300,
            force_close=False
        )
        
        HTTP_SESSION = aiohttp.ClientSession(
            connector=CONNECTOR,
            cookie_jar=CookieJar(unsafe=True)
        )


async def init_http_session():
    """فقط یک بار در startup ربات صدا زده شود"""
    await _ensure_session()


async def close_http_session():
    global HTTP_SESSION, CONNECTOR
    global SENAI_COOKIE, COOKIE_TIME
    global SENAI_CSRF, CSRF_TIME
    global INBOUND_CACHE

    if HTTP_SESSION and not HTTP_SESSION.closed:
        await HTTP_SESSION.close()

    HTTP_SESSION = None
    CONNECTOR = None

    SENAI_COOKIE = None
    COOKIE_TIME = 0

    SENAI_CSRF = None
    CSRF_TIME = 0

    INBOUND_CACHE = {
        "data": [],
        "time": 0,
        "loaded": False
    }


def _get_cookie_from_session() -> Optional[str]:
    """استخراج کوکی از CookieJar خود Session - منبع اصلی"""
    if HTTP_SESSION is None or HTTP_SESSION.closed:
        return None
    
    base_url = _get_base_url()
    jar = HTTP_SESSION.cookie_jar.filter_cookies(base_url)
    
    for name in ("3x-ui", "session"):
        cookie = jar.get(name)
        if cookie and cookie.value:
            return cookie.value
    
    return None


async def _do_login() -> Optional[str]:
    """عملیات واقعی لاگین (داخل Lock صدا زده شود)"""
    global SENAI_COOKIE, COOKIE_TIME, SENAI_CSRF, CSRF_TIME
    
    try:
        await _ensure_session()
        async with HTTP_SESSION.get(
            f"{SENAI_PANEL_URL}/csrf-token",
            timeout=LOGIN_TIMEOUT
        ) as resp:
            if resp.status != 200:
                return None
            data = await resp.json(content_type=None)
            if not data.get("success"):
                return None
            SENAI_CSRF = data.get("obj")
            CSRF_TIME = time.time()
            logger.debug("CSRF token دریافت شد")
        async with HTTP_SESSION.post(
            f"{SENAI_PANEL_URL}/login",
            data={
                "username": SENAI_PANEL_USERNAME,
                "password": SENAI_PANEL_PASSWORD
            },
            headers={"X-CSRF-Token": SENAI_CSRF},
            allow_redirects=False,
            timeout=LOGIN_TIMEOUT
        ) as resp:
            if resp.status in (200, 302):
                jar_cookie = _get_cookie_from_session()
                if jar_cookie:
                    SENAI_COOKIE = jar_cookie
                    COOKIE_TIME = time.time()
                    logger.debug("لاگین موفق (از CookieJar)")
                    return SENAI_COOKIE
                for name in ("3x-ui", "session"):
                    cookie = resp.cookies.get(name)
                    if cookie and cookie.value:
                        SENAI_COOKIE = cookie.value
                        COOKIE_TIME = time.time()
                        logger.debug("لاگین موفق (از response.cookies)")
                        return SENAI_COOKIE
                
                logger.error("کوکی در response و CookieJar پیدا نشد")
            
            return None
            
    except Exception as e:
        logger.error(f"خطا در لاگین: {e}")
        return None


async def xui_login() -> Optional[str]:
    """ورود به پنل 3X-UI"""
    global SENAI_COOKIE, COOKIE_TIME
    
    if not SENAI_PANEL_ENABLED:
        return None
    
    current_time = time.time()
    cookie = _get_cookie_from_session()
    if cookie:
        SENAI_COOKIE = cookie
        COOKIE_TIME = current_time
        return cookie
    if SENAI_COOKIE and (current_time - COOKIE_TIME) < COOKIE_TTL:
        return SENAI_COOKIE
    
    async with LOGIN_LOCK:
        current_time = time.time()
        if SENAI_COOKIE and (current_time - COOKIE_TIME) < COOKIE_TTL:
            return SENAI_COOKIE
        
        cookie = _get_cookie_from_session()
        if cookie:
            SENAI_COOKIE = cookie
            COOKIE_TIME = current_time
            return cookie
        
        return await _do_login()


async def xui_get_csrf_token(session=None) -> Optional[str]:
    """دریافت CSRF token با TTL"""
    global SENAI_CSRF, CSRF_TIME
    
    current_time = time.time()
    
    if SENAI_CSRF and (current_time - CSRF_TIME) < CSRF_TTL:
        return SENAI_CSRF
    
    await _ensure_session()
    
    async with HTTP_SESSION.get(
        f"{SENAI_PANEL_URL}/csrf-token",
        timeout=API_TIMEOUT
    ) as resp:
        if resp.status == 200:
            data = await resp.json(content_type=None)
            if data.get("success"):
                SENAI_CSRF = data.get("obj")
                CSRF_TIME = current_time
                logger.debug(f"CSRF token: {SENAI_CSRF[:20]}...")
    
    return SENAI_CSRF


async def test_cookie() -> bool:
    """تست اعتبار کوکی فعلی (برای compatibility)"""
    if not SENAI_COOKIE:
        return False
    
    try:
        await _ensure_session()
        
        async with HTTP_SESSION.get(
            f"{SENAI_PANEL_URL}/panel/api/inbounds/list",
            timeout=API_TIMEOUT
        ) as resp:
            return resp.status == 200
    except:
        return False


async def _api_request(method: str, path: str, **kwargs) -> Optional[dict]:
    """درخواست به API با retry خودکار در صورت 401"""
    global SENAI_COOKIE, COOKIE_TIME, SENAI_CSRF, CSRF_TIME
    
    await _ensure_session()
    await xui_login()
    if not SENAI_COOKIE:
        return None
    
    headers = kwargs.pop("headers", {})
    if method.upper() != "GET" and SENAI_CSRF:
        headers["X-CSRF-Token"] = SENAI_CSRF
    
    url = f"{SENAI_PANEL_URL}{path}"
    
    try:
        async with HTTP_SESSION.request(
            method, url,
            headers=headers,
            timeout=API_TIMEOUT,
            **kwargs
        ) as resp:
            if resp.status == 401:
                logger.warning("401 - لاگین مجدد...")
                
                async with LOGIN_LOCK:
                    cookie_check = _get_cookie_from_session()
                    if cookie_check and cookie_check != SENAI_COOKIE:
                        SENAI_COOKIE = cookie_check
                        COOKIE_TIME = time.time()
                        SENAI_CSRF = None
                        CSRF_TIME = 0
                        logger.debug("لاگین همزمان تشخیص داده شد")
                    else:
                        SENAI_COOKIE = None
                        COOKIE_TIME = 0
                        SENAI_CSRF = None
                        CSRF_TIME = 0
                        HTTP_SESSION.cookie_jar.clear()
                        await _do_login()
                
                if not SENAI_COOKIE:
                    return None
                headers_retry = {}
                if method.upper() != "GET" and SENAI_CSRF:
                    headers_retry["X-CSRF-Token"] = SENAI_CSRF
                
                async with HTTP_SESSION.request(
                    method, url,
                    headers=headers_retry,
                    timeout=API_TIMEOUT,
                    **kwargs
                ) as retry_resp:
                    if retry_resp.status == 200:
                        return await retry_resp.json(content_type=None)
                    return None
            if resp.status == 200:
                return await resp.json(content_type=None)
            
            return None
            
    except Exception as e:
        logger.error(f"API request error: {e}")
        return None


async def xui_get_inbounds() -> list:
    """دریافت لیست اینباندها با کش و Lock"""
    global INBOUND_CACHE
    
    current_time = time.time()
    if INBOUND_CACHE["loaded"] and (current_time - INBOUND_CACHE["time"]) < INBOUND_CACHE_TTL:
        logger.debug(f"کش اینباندها: {len(INBOUND_CACHE['data'])} عدد")
        return INBOUND_CACHE["data"]
    async with INBOUND_LOCK:
        current_time = time.time()
        if INBOUND_CACHE["loaded"] and (current_time - INBOUND_CACHE["time"]) < INBOUND_CACHE_TTL:
            return INBOUND_CACHE["data"]
        
        result = await _api_request("GET", "/panel/api/inbounds/list")
        if result and result.get("success"):
            inbounds = [i for i in result.get("obj", []) if i.get("enable", True)]
            INBOUND_CACHE["data"] = inbounds
            INBOUND_CACHE["time"] = current_time
            INBOUND_CACHE["loaded"] = True
            
            logger.debug(f"{len(inbounds)} اینباند فعال دریافت شد")
            return inbounds
        if INBOUND_CACHE["loaded"]:
            logger.warning("خطا در دریافت اینباندها، استفاده از کش قبلی")
            return INBOUND_CACHE["data"]
        
        return []
panel_semaphore = asyncio.Semaphore(3)  # حداکثر 3 درخواست همزمان
class PanelRateLimiter:
    """محدود کننده نرخ درخواست به پنل"""
    
    def __init__(self, requests_per_minute: int = 30):
        self.requests_per_minute = requests_per_minute
        self.interval = 60.0 / requests_per_minute
        self.last_request_time = 0
        self._lock = asyncio.Lock()
    
    async def wait_if_needed(self):
        """اگر لازم باشد، صبر کن تا نرخ درخواست محدود نشود"""
        async with self._lock:
            now = time.time()
            time_since_last = now - self.last_request_time
            
            if time_since_last < self.interval:
                wait_time = self.interval - time_since_last
                logger.debug(f"⏳ Rate limit: waiting {wait_time:.2f}s before next request")
                await asyncio.sleep(wait_time)
            
            self.last_request_time = time.time()
panel_rate_limiter = PanelRateLimiter(requests_per_minute=30)
async def check_shop_status_and_notify(user_id: int, callback: CallbackQuery = None) -> bool:
    """بررسی وضعیت فروش و ارسال پیام در صورت بسته بودن
    
    Returns:
        True اگر فروش باز است، False اگر بسته است
    """
    if is_shop_open():
        return True
    
    lang = get_user(user_id).get('lang', 'fa')
    message = get_shop_status_message(lang)
    
    if callback:
        await callback.message.edit_text(
            f"🛒 <b>فروش موقتاً بسته است</b>\n\n{message}",
            reply_markup=get_back_only_keyboard(lang),
            parse_mode=ParseMode.HTML
        )
        try:
            await callback.answer()
        except:
            pass
    else:
        pass
    
    return False

async def xui_create_client_with_inbound(
    email: str, 
    volume_gb: int, 
    days: int, 
    user_name: str = None, 
    user_id: int = None, 
    inbound_id: int = None,
    ip_limit: int = 0  # ✅ جدید: محدودیت IP (0 = نامحدود)
) -> Optional[str]:
    """ساخت کلاینت با اینباند مشخص (یا پیش‌فرض) - پشتیبانی از چندین اینباند و IP Limit"""
    inbound_ids = []
    if inbound_id is not None:
        if isinstance(inbound_id, list):
            inbound_ids = inbound_id
            logger.info(f"📡 استفاده از لیست اینباندهای مشخص: {inbound_ids}")
        else:
            inbound_ids = [inbound_id]
            logger.info(f"📡 استفاده از اینباند مشخص: {inbound_id}")
    elif user_id:
        user_inbound = get_user_inbound(user_id)
        if user_inbound:
            if isinstance(user_inbound, list):
                inbound_ids = user_inbound
                logger.info(f"👤 استفاده از اینباندهای کاربر {user_id}: {inbound_ids}")
            else:
                inbound_ids = [user_inbound]
                logger.info(f"👤 استفاده از اینباند کاربر {user_id}: {user_inbound}")
    if not inbound_ids:
        default_ids = configs_pool.get('default_inbound_ids', [])
        if default_ids:
            inbound_ids = default_ids
            logger.info(f"📌 استفاده از اینباندهای پیش‌فرض: {default_ids}")
    for attempt in range(3):  # 3 تلاش برای دریافت اینباندها
        if attempt > 0:
            logger.info(f"🔄 تلاش مجدد {attempt+1}/3 برای دریافت اینباندها")
            await asyncio.sleep(2 * attempt)
        
        try:
            async with panel_semaphore:
                await panel_rate_limiter.wait_if_needed()
                
                cookie = await xui_login()
                if not cookie:
                    logger.error("❌ عدم موفقیت در لاگین به پنل")
                    continue
                
                inbounds = await xui_get_inbounds()
                if not inbounds:
                    logger.error("❌ هیچ اینباند فعالی یافت نشد")
                    continue
                if not inbound_ids:
                    inbound_ids = [i.get('id') for i in inbounds if i.get('enable', True)]
                    logger.info(f"📡 استفاده از همه اینباندهای فعال: {inbound_ids}")
                valid_inbound_ids = []
                invalid_inbounds = []
                
                for ib_id in inbound_ids:
                    found = False
                    for i in inbounds:
                        if i.get('id') == ib_id and i.get('enable', True):
                            valid_inbound_ids.append(ib_id)
                            found = True
                            break
                    if not found:
                        invalid_inbounds.append(ib_id)
                
                if invalid_inbounds:
                    logger.warning(f"⚠️ اینباندهای نامعتبر: {invalid_inbounds}")
                
                if not valid_inbound_ids:
                    valid_inbound_ids = [i.get('id') for i in inbounds if i.get('enable', True)]
                    logger.info(f"📡 استفاده از همه اینباندهای فعال (به دلیل نامعتبر بودن اینباندهای قبلی): {valid_inbound_ids}")
                
                if not valid_inbound_ids:
                    logger.error("❌ هیچ اینباند معتبری یافت نشد")
                    continue
                expiry_time = int(datetime.now().timestamp() * 1000) + (days * 24 * 60 * 60 * 1000)
                if volume_gb == 0:
                    total_bytes = 0  # 0 در پنل به معنی نامحدود است
                    logger.info(f"📦 حجم: نامحدود (0 bytes)")
                else:
                    total_bytes = int(volume_gb * 1024 * 1024 * 1024)
                    logger.info(f"📦 حجم: {volume_gb} GB = {total_bytes:,} bytes")
                
                logger.info(f"⏱ انقضا: {days} روز = {expiry_time}")
                comment_parts = []
                if user_name:
                    comment_parts.append(user_name)
                if user_id:
                    comment_parts.append(f"(ID:{user_id})")  # ✅ فرمت قدیمی: نام (ID:123)
                if volume_gb == 0:
                    comment_parts.append("نامحدود")
                if ip_limit > 0:
                    comment_parts.append(f"IP:{ip_limit}")
                comment_text = " ".join(comment_parts) if comment_parts else email
                
                if len(comment_text) > 100:
                    comment_text = comment_text[:97] + "..."
                
                logger.info(f"📝 کامنت: {comment_text}")
                bulk_data = [
                    {
                        "client": {
                            "email": email,
                            "enable": True,
                            "expiryTime": expiry_time,
                            "totalGB": total_bytes,  # 0 = نامحدود
                            "limitIp": ip_limit,  # ✅ محدودیت IP
                            "subId": email,
                            "resetStrategy": "no_reset",
                            "comment": comment_text  # ✅ فرمت قدیمی
                        },
                        "inboundIds": valid_inbound_ids  # ✅ لیست اینباندها
                    }
                ]
                logger.info(f"📤 ارسال به پنل: {json.dumps(bulk_data, indent=2)[:500]}...")
                logger.info(f"📡 اینباندهای ارسالی: {valid_inbound_ids}")
                logger.info(f"👤 محدودیت IP: {ip_limit if ip_limit > 0 else 'نامحدود'}")
                logger.info(f"📦 حجم: {'نامحدود' if volume_gb == 0 else f'{volume_gb} GB'}")
                connector = aiohttp.TCPConnector(ssl=False)
                
                async with aiohttp.ClientSession(connector=connector) as session:
                    csrf = await xui_get_csrf_token(session)
                    headers = {"X-CSRF-Token": csrf} if csrf else {}
                    
                    async with session.post(
                        f"{SENAI_PANEL_URL}/panel/api/clients/bulkCreate",
                        cookies={"3x-ui": cookie},
                        headers=headers,
                        json=bulk_data,
                        timeout=aiohttp.ClientTimeout(total=30)  # افزایش تایم‌اوت
                    ) as response:
                        response_text = await response.text()
                        logger.info(f"📥 پاسخ پنل: Status {response.status}")
                        if response.status == 200:
                            try:
                                data = json.loads(response_text)
                                if data.get("success"):
                                    logger.info(f"✅ کلاینت {email} با اینباندهای {valid_inbound_ids} ساخته شد!")
                                    logger.info(f"   📦 حجم: {'نامحدود' if volume_gb == 0 else f'{volume_gb} GB'}")
                                    logger.info(f"   👤 محدودیت IP: {ip_limit if ip_limit > 0 else 'نامحدود'}")
                                    logger.info(f"   📡 اینباندها: {valid_inbound_ids}")
                                    logger.info(f"   📝 کامنت: {comment_text}")
                                    return f"{SENAI_SUB_URL}/sub/{email}"
                                else:
                                    error_msg = data.get('msg', 'Unknown error')
                                    logger.error(f"❌ خطا در ساخت کلاینت: {error_msg}")
                                    logger.info(f"📝 پاسخ کامل: {response_text[:500]}")
                            except json.JSONDecodeError:
                                logger.error(f"❌ پاسخ JSON نامعتبر: {response_text[:200]}")
                        elif response.status == 403:
                            logger.error("❌ خطای 403 - دسترسی غیرمجاز")
                            SENAI_COOKIE = None
                            SENAI_CSRF = None
                            await asyncio.sleep(3)
                        elif response.status == 429:
                            logger.warning("⚠️ محدودیت نرخ درخواست (429)")
                            await asyncio.sleep(5 * (attempt + 1))
                        else:
                            logger.error(f"❌ خطا در ساخت کلاینت: Status {response.status}")
                            logger.info(f"📝 پاسخ: {response_text[:200]}")
                    
        except asyncio.TimeoutError:
            logger.error(f"⏰ تایم‌اوت در ساخت کلاینت {email} (تلاش {attempt+1}/3)")
            await asyncio.sleep(5 * (attempt + 1))
        except aiohttp.ClientError as e:
            logger.error(f"🌐 خطای شبکه در ساخت کلاینت {email} (تلاش {attempt+1}/3): {e}")
            await asyncio.sleep(3 * (attempt + 1))
        except Exception as e:
            logger.error(f"❌ خطای غیرمنتظره در ساخت کلاینت (تلاش {attempt+1}/3): {e}")
            import traceback
            traceback.print_exc()
            SENAI_COOKIE = None
            SENAI_CSRF = None
            await asyncio.sleep(3 * (attempt + 1))
    
    logger.error(f"❌ ساخت کلاینت {email} پس از 3 تلاش ناموفق بود")
    return None

def get_user_inbound(user_id: int) -> Optional[Union[int, List[int]]]:
    """دریافت اینباند انتخاب شده برای کاربر (تک یا لیست)"""
    user_inbound = USER_INBOUND_SELECTION.get(str(user_id))
    
    if user_inbound:
        return user_inbound
    default_ids = configs_pool.get('default_inbound_ids', [])
    if default_ids:
        return default_ids
    
    return None
async def xui_safe_request(method: str, endpoint: str, **kwargs) -> Optional[dict]:
    """درخواست امن به پنل با رعایت محدودیت‌ها
    
    Args:
        method: متد HTTP ('GET', 'POST', 'PUT', 'DELETE')
        endpoint: آدرس نسبی endpoint (مثل '/panel/api/inbounds/list')
        **kwargs: پارامترهای اضافی برای requests
    
    Returns:
        پاسخ JSON در صورت موفقیت، None در صورت خطا
    """
    async with panel_semaphore:
        await panel_rate_limiter.wait_if_needed()
        
        cookie = await xui_login()
        if not cookie:
            logger.error("❌ عدم موفقیت در لاگین به پنل")
            return None
        
        try:
            connector = aiohttp.TCPConnector(ssl=False)
            async with aiohttp.ClientSession(connector=connector) as session:
                csrf = await xui_get_csrf_token(session)
                headers = {"X-CSRF-Token": csrf} if csrf else {}
                
                url = f"{SENAI_PANEL_URL}{endpoint}"
                
                async with session.request(
                    method=method,
                    url=url,
                    cookies={"3x-ui": cookie},
                    headers=headers,
                    timeout=aiohttp.ClientTimeout(total=15),
                    **kwargs
                ) as response:
                    if response.status == 200:
                        data = await response.json()
                        if data.get("success"):
                            return data
                    elif response.status == 429:
                        logger.warning("⚠️ محدودیت نرخ درخواست، 10 ثانیه صبر...")
                        await asyncio.sleep(10)
                    else:
                        logger.error(f"❌ خطا در درخواست {endpoint}: {response.status}")
                    return None
                    
        except asyncio.TimeoutError:
            logger.error(f"❌ تایم‌اوت در درخواست {endpoint}")
            return None
        except Exception as e:
            logger.error(f"❌ خطا در درخواست {endpoint}: {e}")
            return None


async def xui_create_client_with_retry(email: str, volume_gb: int, days: int, user_name: str = None, user_id: int = None) -> Optional[str]:
    """ساخت کلاینت با حداکثر تلاش و مدیریت هوشمند محدودیت‌ها"""
    
    max_retries = 5
    base_delay = 2
    
    for attempt in range(max_retries):
        result = await xui_create_client_with_inbound(email, volume_gb, days, user_name, user_id, retry=1)
        
        if result:
            return result
        delay = base_delay * (2 ** attempt)  # 2, 4, 8, 16, 32 ثانیه
        logger.warning(f"⚠️ تلاش {attempt + 1}/{max_retries} ناموفق بود، {delay} ثانیه صبر می‌کنم...")
        await asyncio.sleep(min(delay, 60))  # حداکثر 60 ثانیه
    
    logger.error(f"❌ ساخت کلاینت {email} پس از {max_retries} تلاش ناموفق بود")
    return None
async def get_panel_rate_stats() -> dict:
    """دریافت آمار درخواست‌های پنل"""
    return {
        'current_semaphore_value': panel_semaphore._value,
        'rate_limiter_interval': panel_rate_limiter.interval,
        'last_request_time': panel_rate_limiter.last_request_time,
        'is_rate_limited': (time.time() - panel_rate_limiter.last_request_time) < panel_rate_limiter.interval
    }
async def reset_panel_rate_limits():
    """ریست کردن محدودیت‌های پنل"""
    global panel_semaphore, panel_rate_limiter
    panel_semaphore = asyncio.Semaphore(3)
    panel_rate_limiter = PanelRateLimiter(requests_per_minute=30)
    
    logger.info("🔄 محدودیت‌های پنل ریست شدند")
    return True
from typing import Optional, Dict, List
import aiohttp
