import aiohttp
import json

class GeminiClient:
    """کلاینت اتصال به Google Gemini API با مدیریت هوشمند توکن"""
    
    def __init__(self, api_key: str, model: str):
        self.api_key = api_key
        self.model = model
        self.base_url = "https://generativelanguage.googleapis.com/v1beta"
        self.system_prompt = GEMINI_SYSTEM_PROMPT
    
    async def test_connection(self) -> Dict:
        """تست اتصال به Gemini API"""
        try:
            url = f"{self.base_url}/models?key={self.api_key}"
            async with aiohttp.ClientSession() as session:
                async with session.get(url, timeout=aiohttp.ClientTimeout(total=10)) as response:
                    if response.status == 200:
                        data = await response.json()
                        models = data.get('models', [])
                        gemini_models = [m['name'].split('/')[-1] for m in models if 'gemini' in m['name']]
                        
                        if self.model in gemini_models:
                            return {'success': True, 'message': 'مدل موجود است'}
                        else:
                            return {'success': False, 'error': f'مدل {self.model} یافت نشد', 'available': gemini_models[:5]}
                    else:
                        text = await response.text()
                        return {'success': False, 'error': f"HTTP {response.status}: {text[:100]}"}
        except Exception as e:
            return {'success': False, 'error': str(e)}
    
    async def chat(self, user_message: str, user_id: int = None, username: str = None, retry: int = 2) -> str:
        """ارسال پیام به Gemini با مدیریت خودکار توکن"""
        estimated_tokens = len(user_message) // 4 + 100  # 100 توکن برای System Prompt
        if len(user_message) < 50:
            max_tokens = 300  # سوال کوتاه
        elif len(user_message) < 100:
            max_tokens = 500  # سوال متوسط
        elif len(user_message) < 200:
            max_tokens = 800  # سوال بلند
        else:
            max_tokens = 1024  # سوال خیلی بلند
        if GEMINI_MAX_TOKENS > max_tokens:
            max_tokens = GEMINI_MAX_TOKENS
        
        for attempt in range(retry):
            if attempt > 0:
                await asyncio.sleep(2 * attempt)
            
            try:
                if user_id:
                    user_info = get_user(user_id) if 'get_user' in globals() else {}
                    user_name = user_info.get('name', 'کاربر') if user_info else username or f"کاربر_{user_id}"
                    user_content = f"کاربر: {user_name}\nسوال: {user_message}"
                else:
                    user_content = user_message
                payload = {
                    "system_instruction": {
                        "parts": [{"text": self.system_prompt}]
                    },
                    "contents": [{
                        "parts": [{"text": user_content}]
                    }],
                    "generationConfig": {
                        "temperature": GEMINI_TEMPERATURE,
                        "maxOutputTokens": max_tokens,
                        "topP": 0.9,
                        "topK": 40,
                        "stopSequences": ["\n\n\n"]  # توقف در صورت 3 خط خالی
                    }
                }
                url = f"{self.base_url}/models/{self.model}:generateContent?key={self.api_key}"
                
                async with aiohttp.ClientSession() as session:
                    async with session.post(
                        url,
                        json=payload,
                        timeout=aiohttp.ClientTimeout(total=30)
                    ) as response:
                        if response.status == 200:
                            data = await response.json()
                            
                            try:
                                candidates = data.get('candidates', [])
                                if candidates:
                                    finish_reason = candidates[0].get('finishReason', '')
                                    reply = candidates[0].get('content', {}).get('parts', [{}])[0].get('text', '')
                                    
                                    if reply:
                                        if finish_reason == 'MAX_TOKENS' and attempt < retry - 1:
                                            logger.warning(f"⚠️ پاسخ ناقص است (MAX_TOKENS)، تلاش مجدد با توکن بیشتر...")
                                            max_tokens = min(max_tokens * 2, 2048)
                                            continue
                                        
                                        return reply.strip()
                                
                                return "متأسفانه نتوانستم پاسخ مناسبی پیدا کنم."
                                
                            except Exception as e:
                                logger.error(f"خطا در پردازش پاسخ: {e}")
                                return "خطا در پردازش پاسخ"
                        
                        elif response.status == 404:
                            error_text = await response.text()
                            logger.error(f"❌ مدل {self.model} یافت نشد: {error_text[:200]}")
                            return f"❌ مدل {self.model} در دسترس نیست. لطفاً مدل دیگری امتحان کنید."
                        
                        elif response.status == 429:
                            logger.warning(f"Rate limit (تلاش {attempt+1}/{retry})")
                            if attempt == retry - 1:
                                return "⚠️ محدودیت درخواست. لطفاً چند لحظه صبر کنید."
                            continue
                        
                        elif response.status == 403:
                            return "❌ خطای احراز هویت. لطفاً کلید API را بررسی کنید."
                        
                        else:
                            error_text = await response.text()
                            logger.error(f"خطا: {response.status} - {error_text[:200]}")
                            return f"❌ خطا در ارتباط با هوش مصنوعی. کد: {response.status}"
                            
            except asyncio.TimeoutError:
                logger.error(f"Timeout (تلاش {attempt+1}/{retry})")
                if attempt == retry - 1:
                    return "⏰ زمان پاسخگویی به پایان رسید. لطفاً دوباره تلاش کنید."
                    
            except Exception as e:
                logger.error(f"خطا: {e}")
                if attempt == retry - 1:
                    return f"❌ خطا: {str(e)[:100]}"
        
        return "❌ خطا در پردازش درخواست."
from collections import defaultdict
from datetime import datetime, timedelta

class ConversationMemory:
    """مدیریت حافظه مکالمه برای هر کاربر"""
    
    def __init__(self, max_history: int = 10, expire_minutes: int = 60):
        self.max_history = max_history
        self.expire_minutes = expire_minutes
        self.memories = defaultdict(list)  # user_id -> list of messages
        self.last_activity = defaultdict(datetime)  # user_id -> last activity time
    
    def add_message(self, user_id: int, role: str, content: str):
        """اضافه کردن پیام به حافظه کاربر"""
        self._clean_expired(user_id)
        if len(self.memories[user_id]) >= self.max_history * 2:
            self.memories[user_id] = self.memories[user_id][-self.max_history:]
        
        self.memories[user_id].append({
            'role': role,  # 'user' یا 'assistant'
            'content': content,
            'timestamp': datetime.now().isoformat()
        })
        self.last_activity[user_id] = datetime.now()
    
    def get_history(self, user_id: int) -> list:
        """دریافت تاریخچه مکالمه کاربر"""
        self._clean_expired(user_id)
        return self.memories.get(user_id, [])
    
    def get_context(self, user_id: int, max_messages: int = 6) -> str:
        """دریافت متن مکالمه برای ارسال به AI"""
        history = self.get_history(user_id)
        if not history:
            return ""
        recent = history[-max_messages:]
        
        context = "تاریخچه مکالمه:\n"
        for msg in recent:
            role = "کاربر" if msg['role'] == 'user' else "دستیار"
            context += f"{role}: {msg['content']}\n"
        
        return context
    
    def has_history(self, user_id: int) -> bool:
        """آیا کاربر تاریخچه دارد؟"""
        self._clean_expired(user_id)
        return len(self.memories.get(user_id, [])) > 0
    
    def clear(self, user_id: int):
        """پاک کردن حافظه کاربر"""
        if user_id in self.memories:
            del self.memories[user_id]
        if user_id in self.last_activity:
            del self.last_activity[user_id]
    
    def _clean_expired(self, user_id: int):
        """پاک کردن حافظه منقضی شده"""
        if user_id in self.last_activity:
            elapsed = datetime.now() - self.last_activity[user_id]
            if elapsed.total_seconds() > self.expire_minutes * 60:
                self.clear(user_id)
    
    def get_stats(self) -> dict:
        """دریافت آمار حافظه"""
        total_users = len(self.memories)
        total_messages = sum(len(msgs) for msgs in self.memories.values())
        return {
            'total_users': total_users,
            'total_messages': total_messages,
            'active_users': len([uid for uid in self.last_activity 
                               if (datetime.now() - self.last_activity[uid]).total_seconds() < 600])
        }
conversation_memory = ConversationMemory(max_history=10, expire_minutes=30)
class OpenRouterClient:
    """کلاینت اتصال به OpenRouter API (بدون تغییر)"""
    
    def __init__(self, api_key: str, base_url: str):
        self.api_key = api_key
        self.base_url = base_url.rstrip('/')
        self.headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "HTTP-Referer": "https://t.me/velorazoko_bot",
            "X-Title": "VPN Config Bot"
        }
        self.available_models = []
        self.default_model = None
    
    async def test_connection(self) -> Dict:
        """تست اتصال به OpenRouter"""
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(
                    f"{self.base_url}/api/v1/models",
                    headers=self.headers,
                    timeout=aiohttp.ClientTimeout(total=10)
                ) as response:
                    if response.status == 200:
                        data = await response.json()
                        models = data.get('data', [])
                        free_models = [m['id'] for m in models if ':free' in m.get('id', '')]
                        
                        for model in OPENROUTER_MODELS:
                            if model in free_models:
                                self.default_model = model
                                break
                        
                        if not self.default_model and free_models:
                            self.default_model = free_models[0]
                        
                        return {
                            'success': True,
                            'free_models': len(free_models),
                            'default_model': self.default_model
                        }
                    else:
                        text = await response.text()
                        return {'success': False, 'error': f"HTTP {response.status}: {text[:100]}"}
        except Exception as e:
            return {'success': False, 'error': str(e)}
    
    async def chat(self, user_message: str, user_id: int = None, username: str = None, retry: int = 2) -> str:
        """ارسال پیام به OpenRouter"""
        if not self.default_model:
            return "❌ مشکلی در اتصال به هوش مصنوعی وجود دارد."
        
        for attempt in range(retry):
            if attempt > 0:
                await asyncio.sleep(2 * attempt)
            
            try:
                messages = [
                    {"role": "system", "content": OPENROUTER_SYSTEM_PROMPT},
                    {"role": "user", "content": user_message}
                ]
                
                async with aiohttp.ClientSession() as session:
                    async with session.post(
                        f"{self.base_url}/api/v1/chat/completions",
                        headers=self.headers,
                        json={
                            "model": self.default_model,
                            "messages": messages,
                            "temperature": OPENROUTER_TEMPERATURE,
                            "max_tokens": OPENROUTER_MAX_TOKENS
                        },
                        timeout=aiohttp.ClientTimeout(total=30)
                    ) as response:
                        if response.status == 200:
                            data = await response.json()
                            reply = data.get('choices', [{}])[0].get('message', {}).get('content', '')
                            return reply.strip() if reply else "متأسفانه نتوانستم پاسخ مناسبی پیدا کنم."
                        elif response.status == 429:
                            if attempt == retry - 1:
                                return "⚠️ محدودیت درخواست. لطفاً چند لحظه صبر کنید."
                            continue
                        else:
                            return f"❌ خطا: {response.status}"
            except Exception as e:
                logger.error(f"OpenRouter Error: {e}")
                if attempt == retry - 1:
                    return f"❌ خطا: {str(e)[:100]}"
        
        return "❌ خطا در پردازش درخواست."
def check_ai_limit(user_id: int) -> tuple:
    """بررسی محدودیت روزانه کاربر برای استفاده از AI
    
    Returns:
        (can_use: bool, remaining: int, message: str)
    """
    today = datetime.now().date().isoformat()
    daily_limit = GEMINI_DAILY_LIMIT if gemini_client else OPENROUTER_DAILY_LIMIT
    
    if user_id not in user_ai_requests:
        user_ai_requests[user_id] = {'date': today, 'count': 0}
    
    if user_ai_requests[user_id]['date'] != today:
        user_ai_requests[user_id] = {'date': today, 'count': 0}
    
    used = user_ai_requests[user_id]['count']
    remaining = daily_limit - used
    
    if remaining <= 0:
        return False, 0, f"⚠️ شما به سقف {daily_limit} سوال در روز رسیده‌اید. فردا دوباره امتحان کنید."
    
    return True, remaining, None


def increment_ai_usage(user_id: int):
    """افزایش شمارش استفاده کاربر از AI"""
    today = datetime.now().date().isoformat()
    
    if user_id not in user_ai_requests or user_ai_requests[user_id]['date'] != today:
        user_ai_requests[user_id] = {'date': today, 'count': 0}
    
    user_ai_requests[user_id]['count'] += 1


def reset_ai_limits():
    """ریست محدودیت‌های روزانه (برای استفاده در تسک روزانه)"""
    global user_ai_requests
    
    today = datetime.now().date().isoformat()
    before_count = sum(u['count'] for u in user_ai_requests.values() if u.get('date') == today)
    before_users = len([u for u in user_ai_requests.values() if u.get('date') == today])
    user_ai_requests = {uid: data for uid, data in user_ai_requests.items() if data['date'] == today}
    for uid in list(user_ai_requests.keys()):
        if user_ai_requests[uid]['date'] == today:
            user_ai_requests[uid]['count'] = 0
    configs_pool['user_ai_requests'] = user_ai_requests
    save_all()
    
    logger.info(f"🔄 ریست محدودیت‌های AI - {before_users} کاربر با {before_count} سوال ریست شد")
    
    return before_users, before_count


def is_ai_question(text: str) -> bool:
    """تشخیص اینکه آیا سوال مربوط به کانفیگ و VPN است"""
    ai_keywords = [
        'چطور', 'چگونه', 'راهنمایی', 'مشکل', 'ارور', 'اتصال', 'قطع', ' وصل',
        'vpn', 'v2ray', 'vless', 'trojan', 'shadow', 'socks', 'http',
        'اندروید', 'ios', 'ویندوز', 'مک', 'لینوکس', 'موبایل', 'کامپیوتر',
        'کانفیگ', 'کانفیک', 'کانف', 'ساب', 'لینک', 'اشتراک',
        'حجم', 'مدت', 'قیمت', 'خرید', 'شارژ', 'پرداخت', 'فیش', 'کارت',
        'رفرال', 'دعوت', 'کد تخفیف', 'پشتیبانی', 'مشاوره', 'آموزش'
    ]
    
    text_lower = text.lower()
    simple_keywords = ['چطوری', 'چجوری', 'چه جوری', 'نمیشه', 'کار نمیکنه']
    
    for kw in ai_keywords + simple_keywords:
        if kw in text_lower:
            return True
    
    return False
@dp.message(Command("ai"))
async def cmd_ai(message: Message):
    """دستور استفاده از هوش مصنوعی"""
    user_id = message.from_user.id
    lang = get_user(user_id).get('lang', 'fa')
    ai_available = (OPENROUTER_ENABLED and openrouter_client) or (GEMINI_ENABLED and gemini_client)
    
    if not ai_available:
        text = "❌ هوش مصنوعی در حال حاضر در دسترس نیست." if lang == "fa" else "❌ AI is currently unavailable."
        await message.reply(text)
        return
    if not message.text or len(message.text.split()) < 2:
        if lang == "fa":
            text = f"""
🤖 <b>دستیار هوش مصنوعی</b>

برای استفاده از AI، پیام خود را همراه دستور ارسال کنید:

<code>/ai نحوه اتصال کانفیگ در اندروید</code>

<b>📋 موضوعات پشتیبانی:</b>
• نحوه خرید و قیمت‌ها
• راهنمای اتصال در دستگاه‌های مختلف
• حل مشکلات اتصال VPN
• راهنمای شارژ حساب

<b>⚠️ محدودیت:</b> {OPENROUTER_DAILY_LIMIT} سوال در روز

برای لغو وضعیت، /cancel را ارسال کنید.
"""
        else:
            text = f"""
🤖 <b>AI Assistant</b>

To use AI, send your message with the command:

<code>/ai how to connect config on Android</code>

<b>📋 Support topics:</b>
• Purchasing and pricing
• Connection guide for different devices
• VPN connection issues
• Balance recharge guide

<b>⚠️ Limit:</b> {OPENROUTER_DAILY_LIMIT} questions per day

Send /cancel to abort.
"""
        await message.reply(text, parse_mode=ParseMode.HTML)
        return
    question = message.text.replace("/ai", "").strip()
    if not question:
        return
    can_use, remaining, limit_msg = check_ai_limit(user_id)
    if not can_use:
        await message.reply(limit_msg)
        return
    processing_msg = await message.reply("🤖 در حال پردازش سوال شما..." if lang == "fa" else "🤖 Processing your question...")
    
    try:
        answer = await openrouter_client.chat(question, user_id, message.from_user.username)
        increment_ai_usage(user_id)
        if lang == "fa":
            response_text = f"""
{premium_emoji('star', '🤖')} <b>پاسخ هوش مصنوعی:</b>

{answer}

━━━━━━━━━━━━━━━━━━━━
📊 سوالات باقیمانده امروز: {remaining - 1}/{OPENROUTER_DAILY_LIMIT}
"""
        else:
            response_text = f"""
{premium_emoji('star', '🤖')} <b>AI Response:</b>

{answer}

━━━━━━━━━━━━━━━━━━━━
📊 Remaining questions today: {remaining - 1}/{OPENROUTER_DAILY_LIMIT}
"""
        
        await processing_msg.edit_text(response_text, parse_mode=ParseMode.HTML)
        logger.info(f"AI سوال از کاربر {user_id}: {question[:50]}...")
        
    except Exception as e:
        logger.error(f"خطا در پاسخ AI برای کاربر {user_id}: {e}")
        await processing_msg.edit_text(
            "❌ خطا در پردازش درخواست. لطفاً بعداً تلاش کنید." if lang == "fa" else "❌ Error processing request. Please try again later."
        )

        

@dp.message(Command("memory"))
async def cmd_memory(message: Message):
    """مشاهده و مدیریت حافظه مکالمه (فقط ادمین)"""
    
    if message.from_user.id != ADMIN_ID_INT:
        return
    
    parts = message.text.split()
    
    if len(parts) == 1:
        stats = conversation_memory.get_stats()
        if conversation_memory.has_history(ADMIN_ID_INT):
            history = conversation_memory.get_history(ADMIN_ID_INT)
            history_text = "\n".join([
                f"{'👤' if msg['role']=='user' else '🤖'} {msg['content'][:50]}..."
                for msg in history[-5:]
            ])
        else:
            history_text = "هیچ تاریخی وجود ندارد"
        
        text = f"""
🧠 <b>وضعیت حافظه مکالمه</b>

📊 <b>آمار:</b>
• کاربران فعال: {stats['total_users']}
• کل پیام‌ها: {stats['total_messages']}
• کاربران آنلاین: {stats['active_users']}

📝 <b>تاریخچه شما (۵ پیام آخر):</b>
{history_text}

💡 <b>دستورات:</b>
• <code>/memory clear</code> - پاک کردن حافظه شما
• <code>/memory clear_all</code> - پاک کردن همه حافظه‌ها (فقط ادمین)
• <code>/memory user [ID]</code> - مشاهده تاریخچه یک کاربر
"""
        await message.reply(text, parse_mode=ParseMode.HTML)
    
    elif len(parts) >= 2 and parts[1] == "clear":
        conversation_memory.clear(message.from_user.id)
        await message.reply("🧹 حافظه مکالمه شما پاک شد!")
    
    elif len(parts) >= 2 and parts[1] == "clear_all":
        if message.from_user.id == ADMIN_ID_INT:
            conversation_memory.memories.clear()
            conversation_memory.last_activity.clear()
            await message.reply("🧹 همه حافظه‌ها پاک شدند!")
    
    elif len(parts) >= 2 and parts[1] == "user" and len(parts) >= 3:
        if message.from_user.id == ADMIN_ID_INT:
            try:
                target_id = int(parts[2])
                if conversation_memory.has_history(target_id):
                    history = conversation_memory.get_history(target_id)
                    text = f"🧠 <b>تاریخچه کاربر {target_id}</b>\n\n"
                    for msg in history[-10:]:
                        role = "👤 کاربر" if msg['role'] == 'user' else "🤖 دستیار"
                        text += f"{role}: {msg['content'][:100]}\n"
                    await message.reply(text, parse_mode=ParseMode.HTML)
                else:
                    await message.reply(f"❌ کاربر {target_id} هیچ تاریخی ندارد")
            except:
                await message.reply("❌ آیدی نامعتبر")
