async def xui_get_client_info(email: str) -> Optional[dict]:
    """دریافت اطلاعات کلاینت از پنل 3X-UI با مدیریت خطا"""
    cookie = await xui_login()
    if not cookie:
        return None
    
    try:
        connector = aiohttp.TCPConnector(ssl=False)
        
        async with aiohttp.ClientSession(connector=connector) as session:
            csrf = await xui_get_csrf_token(session)
            headers = {"X-CSRF-Token": csrf} if csrf else {}
            
            async with session.get(
                f"{SENAI_PANEL_URL}/panel/api/clients/get/{email}",
                cookies={"3x-ui": cookie},
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as response:
                if response.status == 200:
                    data = await response.json()
                    if data.get("success"):
                        obj = data.get("obj", {})
                        client = obj.get("client", obj)
                        
                        expiry = client.get('expiryTime', 0)
                        if expiry > 0:
                            try:
                                expiry_date = datetime.fromtimestamp(expiry / 1000)
                                logger.info(f"📅 تاریخ انقضا: {expiry_date.strftime('%Y-%m-%d %H:%M:%S')}")
                            except:
                                pass
                        
                        return client
                    else:
                        logger.info(f"ℹ️ کلاینت {email} در پنل یافت نشد (success: false)")
                        return None
                elif response.status == 404:
                    logger.info(f"ℹ️ کلاینت {email} در پنل یافت نشد (404)")
                    return None
                else:
                    logger.warning(f"⚠️ خطا در دریافت کلاینت {email}: Status {response.status}")
                    if response.status >= 500:
                        logger.warning(f"⚠️ خطای سرور {response.status} - کلاینت {email} ممکنه وجود داشته باشه")
                        return {}  # آبجکت خالی یعنی "کلاینت وجود داره ولی نتونستیم اطلاعاتش رو بگیریم"
                    return None
    except asyncio.TimeoutError:
        logger.warning(f"⏰ تایم‌اوت در دریافت کلاینت {email}")
        return {}
    except aiohttp.ClientError as e:
        logger.warning(f"🌐 خطای شبکه در دریافت کلاینت {email}: {e}")
        return {}
    except Exception as e:
        logger.error(f"❌ خطا در دریافت اطلاعات کلاینت {email}: {e}")
        return None


def extract_email_from_sub_link(sub_link: str) -> Optional[str]:
    """استخراج email از لینک ساب"""
    if not sub_link:
        return None
    parts = sub_link.rstrip('/').split('/')
    if parts:
        return parts[-1]  # آخرین قسمت = email
    return None

async def xui_get_client_traffic(email: str) -> Optional[dict]:
    """دریافت ترافیک کلاینت"""
    cookie = await xui_login()
    if not cookie:
        return None
    
    try:
        connector = aiohttp.TCPConnector(ssl=False)
        async with aiohttp.ClientSession(connector=connector) as session:
            csrf = await xui_get_csrf_token(session)
            headers = {"X-CSRF-Token": csrf} if csrf else {}
            
            async with session.get(
                f"{SENAI_PANEL_URL}/panel/api/clients/traffic/{email}",
                cookies={"3x-ui": cookie},
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as response:
                if response.status == 200:
                    data = await response.json()
                    if data.get("success"):
                        return data.get("obj", {})
                return None
    except Exception as e:
        logger.error(f"❌ خطا در دریافت ترافیک: {e}")
        return None


def progress_bar(percent: float, length: int = 12) -> str:
    """ساخت نوار پیشرفت"""

    percent = max(0, min(100, percent))
    filled = round(length * percent / 100)
    empty = length - filled

    if percent < 50:
        color = "🟩"
    elif percent < 80:
        color = "🟨"
    else:
        color = "🟥"

    return color * filled + "⬜" * empty


def format_traffic_info(client: dict, traffic: dict = None, lang: str = "fa") -> str:
    """نمایش اطلاعات کانفیگ با پشتیبانی کامل از دو زبان فارسی و انگلیسی"""
    
    if not client:
        if lang == "fa":
            return "❌ اطلاعاتی در دسترس نیست."
        else:
            return "❌ No information available."

    enabled = client.get("enable", True)
    status_emoji = premium_emoji('success', '✅') if enabled else premium_emoji('cancel', '❌')
    
    if lang == "fa":
        status = f"{status_emoji} {'فعال' if enabled else 'غیرفعال'}"
    else:
        status = f"{status_emoji} {'Active' if enabled else 'Inactive'}"

    total_bytes = client.get("totalGB", 0)
    if total_bytes == 0:
        total_display = "♾️ نامحدود" if lang == "fa" else "♾️ Unlimited"
    else:
        total_gb = total_bytes / (1024 ** 3)
        email = client.get("email", "")
        is_test = email.startswith("test_")
        
        if is_test:
            total_mb = total_gb * 1024
            total_display = format_volume(total_mb, is_test=True)
        else:
            total_display = format_volume(total_gb, is_test=False)

    ip_limit = client.get("limitIp", 0)
    if lang == "fa":
        if ip_limit == 0:
            ip_display = f"{premium_emoji('user', '👤')} تعداد کاربر: ♾️ نامحدود"
        elif ip_limit == 1:
            ip_display = f"{premium_emoji('user', '👤')} تعداد کاربر: ۱ دستگاه"
        else:
            ip_display = f"{premium_emoji('user', '👤')} تعداد کاربر: {ip_limit} دستگاه"
    else:
        if ip_limit == 0:
            ip_display = f"{premium_emoji('user', '👤')} Users: ♾️ Unlimited"
        elif ip_limit == 1:
            ip_display = f"{premium_emoji('user', '👤')} Users: 1 Device"
        else:
            ip_display = f"{premium_emoji('user', '👤')} Users: {ip_limit} Devices"

    if total_bytes > 0:
        total_gb = total_bytes / (1024 ** 3)
        up = 0
        down = 0
        if traffic:
            up = traffic.get("up", 0) / (1024 ** 3)
            down = traffic.get("down", 0) / (1024 ** 3)
        
        used = up + down
        remain = max(0, total_gb - used)
        percent = (used / total_gb * 100) if total_gb else 0
        percent = min(percent, 100)
        
        email = client.get("email", "")
        is_test = email.startswith("test_")
        
        # ✅ نمایش مصرف و باقیمانده بر اساس زبان
        if lang == "fa":
            if is_test:
                used_mb = used * 1024
                remain_mb = remain * 1024
                used_display = "0 MB" if used <= 0 else f"{round(used_mb, 2)} MB"
                remain_display = "0 MB" if remain <= 0 else f"{round(remain_mb, 2)} MB"
            else:
                if used <= 0:
                    used_display = "0 MB"
                elif used < 1:
                    used_display = f"{round(used * 1024, 2)} MB"
                else:
                    used_display = f"{round(used, 2)} GB"
                
                if remain <= 0:
                    remain_display = "0 MB"
                elif remain < 1:
                    remain_display = f"{round(remain * 1024, 2)} MB"
                else:
                    remain_display = f"{round(remain, 2)} GB"
        else:
            # زبان انگلیسی
            if is_test:
                used_mb = used * 1024
                remain_mb = remain * 1024
                used_display = "0 MB" if used <= 0 else f"{round(used_mb, 2)} MB"
                remain_display = "0 MB" if remain <= 0 else f"{round(remain_mb, 2)} MB"
            else:
                if used <= 0:
                    used_display = "0 MB"
                elif used < 1:
                    used_display = f"{round(used * 1024, 2)} MB"
                else:
                    used_display = f"{round(used, 2)} GB"
                
                if remain <= 0:
                    remain_display = "0 MB"
                elif remain < 1:
                    remain_display = f"{round(remain * 1024, 2)} MB"
                else:
                    remain_display = f"{round(remain, 2)} GB"
        
        bar = progress_bar(percent)
        
        # ✅ بخش حجم بر اساس زبان
        if lang == "fa":
            volume_info = f"""
{premium_emoji('box','📦')} حجم کل: {total_display}
{premium_emoji('upload','📤')} مصرف: {used_display}
{premium_emoji('download','📥')} باقی‌مانده: {remain_display}

{premium_emoji('amar','📊')} میزان مصرف

{bar} {percent:.0f}%
"""
        else:
            volume_info = f"""
{premium_emoji('box','📦')} Total Volume: {total_display}
{premium_emoji('upload','📤')} Used: {used_display}
{premium_emoji('download','📥')} Remaining: {remain_display}

{premium_emoji('amar','📊')} Usage

{bar} {percent:.0f}%
"""
    else:
        if lang == "fa":
            volume_info = f"""
{premium_emoji('box','📦')} حجم کل: ♾️ نامحدود
"""
        else:
            volume_info = f"""
{premium_emoji('box','📦')} Total Volume: ♾️ Unlimited
"""

    expiry = client.get("expiryTime", 0)
    days_left = "♾️" if lang == "fa" else "♾️ Unlimited"

    if expiry > 0:
        try:
            expire_time = datetime.fromtimestamp(expiry / 1000)
            delta = expire_time - datetime.now()

            if delta.total_seconds() <= 0:
                days_left = "منقضی" if lang == "fa" else "Expired"
            elif delta.days == 0:
                hours = max(1, int(delta.total_seconds() // 3600))
                days_left = f"{hours} ساعت" if lang == "fa" else f"{hours} Hours"
            else:
                days_left = f"{delta.days} روز" if lang == "fa" else f"{delta.days} Days"

        except Exception as e:
            logger.error(e)
            days_left = "❌"

    # ✅ بخش پایانی بر اساس زبان
    if lang == "fa":
        return f"""
{status}

{ip_display}
{volume_info}
{premium_emoji('hourglass','⏳')} اعتبار: {days_left}
"""
    else:
        return f"""
{status}

{ip_display}
{volume_info}
{premium_emoji('hourglass','⏳')} Expiry: {days_left}
"""
from aiogram.types import BufferedInputFile

def generate_qr_code(data: str, order_id: int):
    """ساخت QR Code و برگردوندن به فرمت مناسب aiogram 3.x"""
    logger.debug(f"تولید QR Code برای سفارش #{order_id}")
    qr = qrcode.QRCode(
        version=5,
        error_correction=qrcode.constants.ERROR_CORRECT_H,
        box_size=14,
        border=2
    )
    qr.add_data(data)
    qr.make(fit=True)
    qr_img = qr.make_image(fill_color="#000000", back_color="#FFFFFF").convert('RGB')
    bio = BytesIO()
    bio.name = f'qrcode_{order_id}.png'
    qr_img.save(bio, 'PNG', quality=95)
    bio.seek(0)
    return BufferedInputFile(bio.read(), filename=f'qrcode_{order_id}.png')

