@dp.callback_query(F.data.startswith("admin_test_user_reset_single_"))
async def admin_test_user_reset_single(callback: CallbackQuery):
    """ریست تست یک کاربر خاص"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
   
    
    try:
        target_id = int(callback.data.split("_")[-1])  # ✅ گرفتن آخرین قسمت
    except (ValueError, IndexError):
        await callback.answer("❌ خطا در پردازش شناسه کاربر", show_alert=True)
        return
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    uid = str(target_id)
    if uid not in USER_TEST_USAGE:
        await callback.answer(
            "❌ این کاربر هیچ تستی نگرفته است!" if lang == "fa" else "❌ This user has no tests!",
            show_alert=True
        )
        return
    
    old_data = USER_TEST_USAGE[uid].copy()
    old_count = old_data.get('count', 0)
    
    
    del USER_TEST_USAGE[uid]
    save_test_usage()
    
    user_info = await get_user_info_from_telegram(target_id)
    
    if lang == "fa":
        await callback.answer(
            f"✅ تست کاربر {user_info['full_name']} با {old_count} تست ریست شد!",
            show_alert=True
        )
    else:
        await callback.answer(
            f"✅ User {user_info['full_name']} test reset with {old_count} tests!",
            show_alert=True
        )
    await admin_test_user_settings(callback)
    
    
    
    
def migrate_test_inbound_data():
    """مهاجرت داده‌های اینباند تست از تک به چندتایی"""
    if 'inbound_id' in TEST_SERVICE_STATUS:
        old_inbound = TEST_SERVICE_STATUS.get('inbound_id')
        if old_inbound and 'inbound_ids' not in TEST_SERVICE_STATUS:
            TEST_SERVICE_STATUS['inbound_ids'] = [old_inbound]
            logger.info(f"✅ مهاجرت اینباند تست: {old_inbound} -> {TEST_SERVICE_STATUS['inbound_ids']}")
        del TEST_SERVICE_STATUS['inbound_id']
        configs_pool['test_service'] = TEST_SERVICE_STATUS
        save_all()
        
@dp.callback_query(F.data == "ai_chat")
async def ai_chat_start(callback: CallbackQuery):
    """شروع چت با هوش مصنوعی - با حفظ کوپن"""
    user_id = callback.from_user.id
    lang = get_user(user_id).get('lang', 'fa')
    user_state = user_states.get(user_id, {})
    coupon_code = user_state.get('coupon_code')
    coupon_discount = user_state.get('coupon_discount')
    coupon_applied = user_state.get('coupon_applied', False)
    
    logger.info(f"🔍 [ai_chat_start] کوپن قبل: code={coupon_code}, applied={coupon_applied}")
    ai_available = (OPENROUTER_ENABLED and openrouter_client) or (GEMINI_ENABLED and gemini_client)
    if not ai_available:
        await callback.answer("❌ هوش مصنوعی در حال حاضر در دسترس نیست.", show_alert=True)
        return
    if user_id in user_states:
        user_states.pop(user_id, None)
    
    user_states[user_id] = {
        'ai_chat_mode': True,
        'timestamp': datetime.now().isoformat()
    }
    if coupon_applied and coupon_code:
        user_states[user_id]['coupon_code'] = coupon_code
        user_states[user_id]['coupon_applied'] = True
        user_states[user_id]['coupon_discount'] = coupon_discount
        logger.info(f"🏷️ [ai_chat_start] کوپن {coupon_code} حفظ شد")
    if conversation_memory.has_history(user_id):
        history = conversation_memory.get_history(user_id)
        last_message = history[-1] if history else None
        
        if last_message and last_message['role'] == 'assistant':
            welcome_text = (
                "👋 به مکالمه قبلی برگشتیم!\n"
                "سوال بعدی خود را بپرسید..."
            ) if lang == "fa" else (
                "👋 Welcome back to our conversation!\n"
                "Ask your next question..."
            )
        else:
            welcome_text = (
                "💬 ادامه می‌دهیم...\n"
                "سوال خود را بپرسید."
            ) if lang == "fa" else (
                "💬 Let's continue...\n"
                "Ask your question."
            )
    else:
        if lang == "fa":
            await send_sticker(user_id, 'robot', '🤖')
            welcome_text = f"""
{premium_emoji('robot','🤖')} <b>چت با هوش مصنوعی</b>

به بخش پشتیبانی هوشمند خوش آمدید!

<b>{premium_emoji('note','📋')} چه سوالاتی می‌توانید بپرسید؟</b>
• نحوه خرید کانفیگ و قیمت‌ها
• راهنمای اتصال با دستگاه های مختلف با لینک دانلود
• حل مشکلات اتصال VPN
• راهنمای شارژ حساب و پرداخت
• پرسیدن سوال در رابطه با سرعت و پایداری

<b>{premium_emoji('danger','⚠️')} محدودیت:</b> {GEMINI_DAILY_LIMIT if gemini_client else OPENROUTER_DAILY_LIMIT} سوال در روز

<tg-emoji emoji-id="5472146462362048818">💡</tg-emoji> سوال خود را بپرسید...
"""
        else:
            await send_sticker(user_id, 'robot', '🤖')
            welcome_text = f"""
{premium_emoji('robot','🤖')} <b>AI Chat</b>

Welcome to AI Support!

<b>{premium_emoji('note','📋')} What can you ask?</b>
• How to purchase configs and pricing
• Connection guide for different devices
• VPN connection issues
• Balance recharge and payment guide

<b>{premium_emoji('danger','⚠️')} Limit:</b> {GEMINI_DAILY_LIMIT if gemini_client else OPENROUTER_DAILY_LIMIT} questions per day

<tg-emoji emoji-id="5472146462362048818">💡</tg-emoji> Ask your question...
"""
    
    await callback.message.answer(
        welcome_text,
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="🧹 پاک کردن حافظه" if lang == "fa" else "🧹 Clear Memory", callback_data="clear_ai_memory")],
            [InlineKeyboardButton(text="❌ خروج از چت AI" if lang == "fa" else "❌ Exit AI Chat", callback_data="exit_ai_chat", style="danger")]
        ])
    )
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")
       
@dp.callback_query(F.data == "clear_ai_memory")
async def clear_ai_memory(callback: CallbackQuery):
    """پاک کردن حافظه مکالمه کاربر - با حفظ کوپن"""
    user_id = callback.from_user.id
    lang = get_user(user_id).get('lang', 'fa')
    user_state = user_states.get(user_id, {})
    coupon_code = user_state.get('coupon_code')
    coupon_discount = user_state.get('coupon_discount')
    coupon_applied = user_state.get('coupon_applied', False)
    
    logger.info(f"🔍 [clear_ai_memory] کوپن قبل: code={coupon_code}, applied={coupon_applied}")
    
    conversation_memory.clear(user_id)
    await callback.answer(
        "🧹 حافظه مکالمه پاک شد!" if lang == "fa" else "🧹 Memory cleared!",
        show_alert=True
    )
    if coupon_applied and coupon_code:
        user_states[user_id]['coupon_code'] = coupon_code
        user_states[user_id]['coupon_applied'] = True
        user_states[user_id]['coupon_discount'] = coupon_discount
        logger.info(f"🏷️ [clear_ai_memory] کوپن {coupon_code} حفظ شد")
    await callback.message.delete()
    await ai_chat_start(callback)
        
@dp.callback_query(F.data == "exit_ai_chat")
async def exit_ai_chat(callback: CallbackQuery):
    """خروج از حالت چت با AI - با حفظ کوپن"""
    user_id = callback.from_user.id
    save_coupon_to_user_db(user_id)
    lang = get_user(user_id).get('lang', 'fa')
    user_state = user_states.get(user_id, {})
    coupon_code = user_state.get('coupon_code')
    coupon_discount = user_state.get('coupon_discount')
    coupon_applied = user_state.get('coupon_applied', False)
    
    logger.info(f"🔍 [exit_ai_chat] کوپن قبل: code={coupon_code}, applied={coupon_applied}")
    if user_id in user_states:
        user_states.pop(user_id, None)
    if coupon_applied and coupon_code:
        user_states[user_id] = {
            'coupon_code': coupon_code,
            'coupon_discount': coupon_discount,
            'coupon_applied': True
        }
        logger.info(f"🏷️ [exit_ai_chat] کوپن {coupon_code} برای کاربر {user_id} حفظ شد")
    else:
        logger.warning(f"⚠️ [exit_ai_chat] کوپنی برای کاربر {user_id} یافت نشد")
    is_admin = (user_id == ADMIN_ID_INT)
    
    coupon_message = ""
    if coupon_applied and coupon_code:
        coupon_message = f"\n\n🏷️ کوپن شما ({coupon_code}) همچنان معتبر است."
    
    if lang == "fa":
        text = f"{premium_emoji('rocket', '🚀')} منوی اصلی{coupon_message}"
    else:
        text = f"{premium_emoji('rocket', '🚀')} Main Menu{coupon_message}"
    
    await callback.message.edit_text(
        text,
        reply_markup=get_main_keyboard(is_admin, lang)
    )
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")
        
        

@dp.callback_query(F.data.startswith("admin_reset_verification_"))
async def admin_reset_verification(callback: CallbackQuery):
    """ادمین می‌تواند وضعیت verified کاربر را ریست کند"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    target_id = int(callback.data.split("_")[3])
    user = get_user(target_id)
    
    user['verified'] = False
    save_all()
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    await callback.answer(f"✅ وضعیت عضویت کاربر {user.get('name')} ریست شد" if lang == "fa" else f"✅ User {user.get('name')} verification reset", show_alert=True)
    try:
        await bot.send_message(
            target_id,
            "⚠️ وضعیت عضویت شما توسط ادمین ریست شد. لطفاً مجدداً عضویت خود را تأیید کنید." if lang == "fa" else "⚠️ Your membership status has been reset by admin. Please verify your membership again."
        )
    except:
        pass
    
    
async def safe_edit_message(callback: CallbackQuery, text: str = None, reply_markup: InlineKeyboardMarkup = None):
    """ویرایش امن پیام با مدیریت خطای message not modified"""
    try:
        if text and reply_markup:
            await callback.message.edit_text(text, reply_markup=reply_markup)
        elif reply_markup:
            await callback.message.edit_reply_markup(reply_markup=reply_markup)
        elif text:
            await callback.message.edit_text(text)
    except Exception as e:
        if "message is not modified" in str(e):
            logger.debug(f"Message not modified for user {callback.from_user.id}")
        else:
            logger.error(f"Error in safe_edit_message: {e}")
            raise
        
        
def get_purchase_keyboard(volume: int, days: int, lang: str = "fa") -> InlineKeyboardMarkup:
    buttons = []
    try:
        ready_enabled = READY_PACKAGES.get('enabled', True)
        categories = READY_PACKAGES.get('categories', [])
        has_packages = False
        if ready_enabled and categories:
            for cat in categories:
                if cat.get('is_active', True):
                    active_packages = [p for p in cat.get('packages', []) if p.get('is_active', True)]
                    if active_packages:
                        has_packages = True
                        break
        if ready_enabled and has_packages:
            buttons.append([
                InlineKeyboardButton(
                    text="📦 خرید از بسته‌های آماده" if lang == "fa" else "📦 Buy Ready Packages",
                    callback_data="show_ready_categories",
                    style="primary"
                )
            ])
            logger.info("✅ دکمه بسته‌های آماده به کیبورد اضافه شد")
        else:
            logger.warning(f"⚠️ بسته‌های آماده نمایش داده نمی‌شوند - enabled: {ready_enabled}, has_packages: {has_packages}")
            
    except Exception as e:
        logger.error(f"❌ خطا در بررسی بسته‌های آماده: {e}", exc_info=True)
    buttons.extend([
        [
            InlineKeyboardButton(text="➖", callback_data="vol_down"),
            InlineKeyboardButton(text=f"{volume}GB", callback_data="noop", style="primary"),
            InlineKeyboardButton(text="➕", callback_data="vol_up")
        ],
        [
            InlineKeyboardButton(text="➖", callback_data="day_down"),
            InlineKeyboardButton(text=f"{days} {'روز' if lang=='fa' else 'days'}", callback_data="noop", style="primary"),
            InlineKeyboardButton(text="➕", callback_data="day_up")
        ],
        [
            InlineKeyboardButton(text=f"💳 {'پرداخت از کارت' if lang=='fa' else 'Pay by Card'}", callback_data="pay_card", style="success"),
            InlineKeyboardButton(text=f"💰{'پرداخت از موجودی' if lang=='fa' else 'Pay by Balance'}", callback_data="pay_balance", style="success")
        ],
        [
            InlineKeyboardButton(text=f"🔙 {'صفحه اصلی' if lang=='fa' else 'Main Menu'}", callback_data="back_to_main", style="danger")
        ]
    ])
    
    return InlineKeyboardMarkup(inline_keyboard=buttons)

