@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_coupon_create'))
async def admin_coupon_create_process(message: Message):
    """پردازش مراحل ایجاد کوپن - بدون تغییر حروف"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply("❌ ایجاد کوپن لغو شد" if lang == "fa" else "❌ Cancelled")
        return
    
    state = user_states.get(admin_id, {})
    step = state.get('step')
    coupon_data = state.get('coupon_data', {})
    
    if not step:
        user_states.pop(admin_id, None)
        await message.reply("❌ خطا: وضعیت نامعتبر")
        return
    
    try:
        if step == 'code':
            code = message.text.strip().replace(' ', '')
            
            if len(code) < 3:
                await message.reply("❌ کد کوپن باید حداقل ۳ کاراکتر باشد!" if lang == "fa" else "❌ Coupon code must be at least 3 characters!")
                return
            
            if not code.isalnum():
                await message.reply("❌ کد کوپن باید فقط شامل حروف و اعداد انگلیسی باشد!" if lang == "fa" else "❌ Coupon code must contain only English letters and numbers!")
                return
            if code in COUPONS:
                await message.reply(f"❌ کد {code} قبلاً استفاده شده است!" if lang == "fa" else f"❌ Code {code} already exists!")
                return
            
            coupon_data['code'] = code
            user_states[admin_id] = {
                'awaiting_coupon_create': True,
                'step': 'discount',
                'coupon_data': coupon_data
            }
            
            if lang == "fa":
                await message.reply(
                    "✏️ <b>مرحله ۲ از ۴ - درصد تخفیف</b>\n\n"
                    "📝 لطفاً <b>درصد تخفیف</b> را وارد کنید:\n"
                    "(۱ تا ۱۰۰)\n\n"
                    "مثال: <code>20</code>\n\n"
                    "برای لغو /cancel را بفرستید",
                    parse_mode=ParseMode.HTML
                )
            else:
                await message.reply(
                    "✏️ <b>Step 2 of 4 - Discount Percentage</b>\n\n"
                    "📝 Please enter <b>discount percentage</b>:\n"
                    "(1 to 100)\n\n"
                    "Example: <code>20</code>\n\n"
                    "Send /cancel to abort",
                    parse_mode=ParseMode.HTML
                )
        
        elif step == 'discount':
            discount = int(message.text.replace(',', '').replace(' ', '').strip())
            
            if discount < 1 or discount > 100:
                await message.reply("❌ درصد تخفیف باید بین ۱ تا ۱۰۰ باشد!" if lang == "fa" else "❌ Discount must be between 1 and 100!")
                return
            
            coupon_data['discount'] = discount
            user_states[admin_id] = {
                'awaiting_coupon_create': True,
                'step': 'usage_limit',
                'coupon_data': coupon_data
            }
            
            if lang == "fa":
                await message.reply(
                    "✏️ <b>مرحله ۳ از ۴ - تعداد استفاده</b>\n\n"
                    "📝 لطفاً <b>تعداد دفعات استفاده</b> را وارد کنید:\n"
                    "(۱ تا ۱۰۰۰، ۰ = نامحدود)\n\n"
                    "مثال: <code>10</code>\n\n"
                    "برای لغو /cancel را بفرستید",
                    parse_mode=ParseMode.HTML
                )
            else:
                await message.reply(
                    "✏️ <b>Step 3 of 4 - Usage Limit</b>\n\n"
                    "📝 Please enter <b>usage limit</b>:\n"
                    "(1 to 1000, 0 = unlimited)\n\n"
                    "Example: <code>10</code>\n\n"
                    "Send /cancel to abort",
                    parse_mode=ParseMode.HTML
                )
        
        elif step == 'usage_limit':
            usage_limit = int(message.text.replace(',', '').replace(' ', '').strip())
            
            if usage_limit < 0:
                await message.reply("❌ تعداد استفاده نمی‌تواند منفی باشد!" if lang == "fa" else "❌ Usage limit cannot be negative!")
                return
            
            if usage_limit > 1000:
                await message.reply("❌ تعداد استفاده نمی‌تواند بیشتر از ۱۰۰۰ باشد!" if lang == "fa" else "❌ Usage limit cannot exceed 1000!")
                return
            
            coupon_data['usage_limit'] = usage_limit
            user_states[admin_id] = {
                'awaiting_coupon_create': True,
                'step': 'expiry_days',
                'coupon_data': coupon_data
            }
            
            if lang == "fa":
                await message.reply(
                    "✏️ <b>مرحله ۴ از ۴ - مدت اعتبار</b>\n\n"
                    "📝 لطفاً <b>مدت اعتبار</b> را به روز وارد کنید:\n"
                    "(۱ تا ۳۶۵، ۰ = نامحدود)\n\n"
                    "مثال: <code>30</code>\n\n"
                    "برای لغو /cancel را بفرستید",
                    parse_mode=ParseMode.HTML
                )
            else:
                await message.reply(
                    "✏️ <b>Step 4 of 4 - Expiry Days</b>\n\n"
                    "📝 Please enter <b>expiry days</b>:\n"
                    "(1 to 365, 0 = unlimited)\n\n"
                    "Example: <code>30</code>\n\n"
                    "Send /cancel to abort",
                    parse_mode=ParseMode.HTML
                )
        
        elif step == 'expiry_days':
            expiry_days = int(message.text.replace(',', '').replace(' ', '').strip())
            
            if expiry_days < 0:
                await message.reply("❌ مدت اعتبار نمی‌تواند منفی باشد!" if lang == "fa" else "❌ Expiry days cannot be negative!")
                return
            
            if expiry_days > 365:
                await message.reply("❌ مدت اعتبار نمی‌تواند بیشتر از ۳۶۵ روز باشد!" if lang == "fa" else "❌ Expiry days cannot exceed 365!")
                return
            
            coupon_data['expiry_days'] = expiry_days
            coupon_data['created_at'] = datetime.now().isoformat()
            coupon_data['status'] = 'active'
            coupon_data['used_count'] = 0
            coupon_data['used_by'] = []
            if expiry_days > 0:
                expiry_date = datetime.now() + timedelta(days=expiry_days)
                coupon_data['expiry_date'] = expiry_date.isoformat()
            else:
                coupon_data['expiry_date'] = None
            code = coupon_data.get('code', '')
            discount = coupon_data.get('discount', 0)
            usage_limit = coupon_data.get('usage_limit', 0)
            COUPONS[code] = coupon_data
            save_coupons(COUPONS)
            
            user_states.pop(admin_id, None)
            expiry_text = f"{expiry_days} روز" if expiry_days > 0 else "نامحدود"
            limit_text = f"{usage_limit} بار" if usage_limit > 0 else "نامحدود"
            
            if lang == "fa":
                text = f"""
✅ <b>کوپن با موفقیت ایجاد شد!</b>

━━━━━━━━━━━━━━━━━━━━━━
🏷️ کد: <code>{code}</code>
💳 درصد تخفیف: {discount}%
🔢 تعداد استفاده: {limit_text}
📅 مدت اعتبار: {expiry_text}
📊 وضعیت: 🟢 فعال
━━━━━━━━━━━━━━━━━━━━━━

⚠️ توجه: کد کوپن به <b>حروف بزرگ و کوچک</b> حساس است!
🔗 لینک استفاده: <code>/use_coupon {code}</code>
"""
            else:
                text = f"""
✅ <b>Coupon created successfully!</b>

━━━━━━━━━━━━━━━━━━━━━━
🏷️ Code: <code>{code}</code>
💳 Discount: {discount}%
🔢 Usage limit: {limit_text}
📅 Expiry: {expiry_text}
📊 Status: 🟢 Active
━━━━━━━━━━━━━━━━━━━━━━

⚠️ Note: Coupon code is <b>case-sensitive</b>!
🔗 Use link: <code>/use_coupon {code}</code>
"""
            
            buttons = [
                [InlineKeyboardButton(text="➕ ایجاد کوپن دیگر" if lang=="fa" else "➕ Create Another", callback_data="admin_coupon_create")],
                [InlineKeyboardButton(text="📋 لیست کوپن‌ها" if lang=="fa" else "📋 Coupons List", callback_data="admin_coupons_list")],
                [InlineKeyboardButton(text="🔙 برگشت" if lang=="fa" else "🔙 Back", callback_data="admin_coupons")]
            ]
            
            await message.reply(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons), parse_mode=ParseMode.HTML)
            
    except ValueError as e:
        await message.reply(f"❌ لطفاً یک عدد معتبر وارد کنید! ({str(e)})" if lang == "fa" else f"❌ Please enter a valid number! ({str(e)})")
    except Exception as e:
        logger.error(f"خطا در ایجاد کوپن: {e}")
        import traceback
        traceback.print_exc()
        await message.reply(f"❌ خطا: {str(e)}" if lang == "fa" else f"❌ Error: {str(e)}")
        user_states.pop(admin_id, None)
        
