    buttons.append([InlineKeyboardButton(
        text="🔙 برگشت" if lang == "fa" else "🔙 Back",
        callback_data="admin_coupons"
    )])
    
    await safe_edit_message(callback, text, InlineKeyboardMarkup(inline_keyboard=buttons))
    
    
