@dp.callback_query(F.data.startswith("pay_ready_package_balance_"))
async def pay_ready_package_balance(callback: CallbackQuery):
    """پرداخت از موجودی برای بسته آماده"""
    user_id = callback.from_user.id
    
    if user_id in BLACKLIST:
        await notify_blacklisted_user(user_id)
        await callback.answer("⛔ دسترسی مسدود شده", show_alert=True)
        return
    
    if not await check_membership(user_id):
        lang = get_user(user_id).get('lang', 'fa')
        await callback.answer("❌ لطفاً ابتدا عضویت خود را تأیید کنید!" if lang == "fa" else "❌ Please verify your membership first!", show_alert=True)
        return
    
    if not await check_shop_status_and_notify(user_id, callback):
        return
    
    try:
        parts = callback.data.split("_")
        category_id = int(parts[3])
        package_id = int(parts[4])
    except (ValueError, IndexError):
        await callback.answer("❌ خطا در پردازش", show_alert=True)
        return
    
    category = None
    package = None
    
    for c in READY_PACKAGES.get('categories', []):
        if c.get('id') == category_id and c.get('is_active', True):
            category = c
            for p in c.get('packages', []):
                if p.get('id') == package_id and p.get('is_active', True):
                    package = p
                    break
            break
    
    if not category or not package:
        await callback.answer("❌ بسته یافت نشد", show_alert=True)
        return
    
    lang = get_user(user_id).get('lang', 'fa')
    user = get_user(user_id)
    
    volume = package.get('volume', 0)
    days = package.get('days', 30)
    price = package.get('price', 0)
    balance = user.get('balance', 0)
    inbound_id = category.get('inbound_id')
    
    if balance < price:
        await callback.answer(
            f"❌ موجودی کافی نیست!\n💰 موجودی: {balance:,} | نیاز: {price:,}" if lang == "fa" 
            else f"❌ Insufficient balance!\n💰 Balance: {balance:,} | Needed: {price:,}",
            show_alert=True
        )
        return
    
    await callback.message.edit_text("⏳ در حال پردازش...")
    
    new_balance = balance - price
    update_user(user_id, 'balance', new_balance)
    
    order_id = create_order(user_id, volume, days, price, "ready_package")
    update_order(order_id, 
                status='approved',
                category_id=category_id,
                category_name=category.get('name'),
                package_id=package_id,
                inbound_id=inbound_id,
                payment_method='balance',
                approved_date=datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
    
    record_purchase(user_id, price)
    await check_referral_bonus(user_id)
    
    await callback.message.edit_text("⏳ در حال ساخت کانفیگ در پنل...")
    
    timestamp = int(datetime.now().timestamp())
    email = f"user{user_id}_{timestamp}"
    user_name = user.get('name', f'کاربر_{user_id}')
    
    
    sub_link = await xui_create_client_with_inbound(email, volume, days, user_name, user_id, inbound_id)
    
    if sub_link:
        update_order(order_id, config_link=sub_link, sub_link=sub_link, email=email)
        
        await send_config_with_qr_option(user_id, order_id, volume, days, price, sub_link, lang)
        
        cat_name = category.get('name') if lang == "fa" else category.get('name_en', category.get('name'))
        
        if lang == "fa":
            success_text = f"""
✅ <b>خرید با موفقیت انجام شد!</b>

{category.get('icon', '📦')} <b>{cat_name}</b>
📦 حجم: {volume} GB
⏱ مدت: {days} روز
💰 قیمت: {price:,} تومان
💰 موجودی جدید: {new_balance:,} تومان

✅ کانفیگ شما در بخش "کانفیگ‌های من" موجود است.
"""
        else:
            success_text = f"""
✅ <b>Purchase successful!</b>

{category.get('icon', '📦')} <b>{cat_name}</b>
📦 Volume: {volume} GB
⏱ Duration: {days} days
💰 Price: {price:,} Toman
💰 New balance: {new_balance:,} Toman

✅ Your config is available in "My Configs".
"""
        
        await callback.message.answer(
            success_text,
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(
                    text="📁 مشاهده کانفیگ‌ها" if lang == "fa" else "📁 View Configs",
                    callback_data="my_configs"
                )],
                [InlineKeyboardButton(
                    text="🔙 صفحه اصلی" if lang == "fa" else "🔙 Main Menu",
                    callback_data="back_to_main"
                )]
            ])
        )
        
        try:
            await bot.send_message(
                user_id,
                f"{premium_emoji('star', '⭐')} {'لطفا به سرویس ما امتیاز دهید:' if lang=='fa' else 'Please rate our service:'}",
                reply_markup=get_feedback_keyboard(order_id, lang)
            )
        except Exception as e:
            logger.error(f"خطا در ارسال درخواست بازخورد: {e}")
        
        logger.info(f"✅ خرید بسته آماده برای کاربر {user_id} - سفارش #{order_id} - {volume}GB/{days} روز - {price:,} تومان")
        
        if log_system:
            await log_system.log_purchase(user_id, order_id, volume, days, price, f"بسته آماده - {cat_name}")
        
    else:
        update_user(user_id, 'balance', balance)
        
        error_msg = "❌ خطا در ساخت کانفیگ. موجودی شما برگشت داده شد." if lang == "fa" else "❌ Error creating config. Your balance has been refunded."
        await callback.message.answer(
            error_msg,
            reply_markup=get_back_only_keyboard(lang)
        )
        logger.error(f"❌ خطا در ساخت کلاینت برای کاربر {user_id}")
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")
        
        
