@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_package_edit'))
async def save_package_edit(message: Message):
    """ذخیره ویرایش فیلد بسته با پشتیبانی از IP Limit و حجم نامحدود"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply("❌ ویرایش لغو شد" if lang == "fa" else "❌ Cancelled")
        return
    
    state = user_states.get(admin_id, {})
    category_id = state.get('category_id')
    package_id = state.get('package_id')
    edit_field = state.get('edit_field')
    
    if not category_id or not package_id or not edit_field:
        user_states.pop(admin_id, None)
        await message.reply("❌ خطا: اطلاعات نامعتبر")
        return
    
    try:
        new_value = int(message.text.replace(',', '').replace(' ', '').strip())
        if edit_field == 'volume' and (new_value < 0 or new_value > 1000):
            await message.reply("❌ حجم باید بین ۰ تا ۱۰۰۰ گیگ باشد! (۰ = نامحدود)" if lang == "fa" else "❌ Volume must be between 0 and 1000 GB! (0 = Unlimited)")
            return
        
        if edit_field == 'days' and (new_value < 1 or new_value > 365):
            await message.reply("❌ مدت باید بین ۱ تا ۳۶۵ روز باشد!" if lang == "fa" else "❌ Duration must be between 1 and 365 days!")
            return
        
        if edit_field == 'price' and new_value <= 0:
            await message.reply("❌ قیمت باید بزرگتر از صفر باشد!" if lang == "fa" else "❌ Price must be greater than zero!")
            return
        
        if edit_field == 'ip_limit' and new_value < 0:
            await message.reply("❌ محدودیت IP نمی‌تواند منفی باشد! (۰ = نامحدود)" if lang == "fa" else "❌ IP limit cannot be negative! (0 = Unlimited)")
            return
        for cat in READY_PACKAGES.get('categories', []):
            if cat.get('id') == category_id:
                for pkg in cat.get('packages', []):
                    if pkg.get('id') == package_id:
                        old_value = pkg.get(edit_field)
                        pkg[edit_field] = new_value
                        READY_PACKAGES['last_updated'] = datetime.now().isoformat()
                        configs_pool['ready_packages'] = READY_PACKAGES
                        save_all()
                        
                        field_names = {
                            'volume': 'حجم' if lang == "fa" else 'Volume',
                            'days': 'مدت' if lang == "fa" else 'Duration',
                            'price': 'قیمت' if lang == "fa" else 'Price',
                            'ip_limit': 'محدودیت IP' if lang == "fa" else 'IP Limit'
                        }
                        
                        display_value = "نامحدود" if edit_field == 'volume' and new_value == 0 else new_value
                        if edit_field == 'ip_limit':
                            display_value = "نامحدود" if new_value == 0 else new_value
                        
                        await message.reply(
                            f"✅ <b>{field_names.get(edit_field, edit_field)} با موفقیت بروزرسانی شد!</b>\n\n"
                            f"📊 مقدار قدیم: {old_value}\n"
                            f"📊 مقدار جدید: {display_value}",
                            parse_mode=ParseMode.HTML
                        )
                        
                        user_states.pop(admin_id, None)
                        keyboard = InlineKeyboardMarkup(inline_keyboard=[
                            [InlineKeyboardButton(
                                text="🔙 بازگشت به ویرایش بسته" if lang == "fa" else "🔙 Back to Package Edit",
                                callback_data=f"admin_package_edit_{category_id}_{package_id}"
                            )]
                        ])
                        await message.answer("🔄" if lang == "fa" else "🔄", reply_markup=keyboard)
                        return
        
        await message.reply("❌ بسته یافت نشد!" if lang == "fa" else "❌ Package not found!")
        user_states.pop(admin_id, None)
        
    except ValueError:
        await message.reply("❌ لطفاً یک عدد معتبر وارد کنید!" if lang == "fa" else "❌ Please enter a valid number!")
    except Exception as e:
        logger.error(f"خطا در ویرایش بسته: {e}")
        await message.reply(f"❌ خطا: {str(e)}")
        user_states.pop(admin_id, None)
        
@dp.callback_query(F.data.startswith("package_toggle_"))
async def package_toggle(callback: CallbackQuery):
    """فعال/غیرفعال کردن یک بسته"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    parts = callback.data.split("_")
    try:
        category_id = int(parts[2])
        package_id = int(parts[3])
    except (ValueError, IndexError):
        await callback.answer("❌ خطا در پردازش", show_alert=True)
        return
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    for cat in READY_PACKAGES.get('categories', []):
        if cat.get('id') == category_id:
            for pkg in cat.get('packages', []):
                if pkg.get('id') == package_id:
                    pkg['is_active'] = not pkg.get('is_active', True)
                    READY_PACKAGES['last_updated'] = datetime.now().isoformat()
                    configs_pool['ready_packages'] = READY_PACKAGES
                    save_all()
                    
                    status = "فعال" if pkg['is_active'] else "غیرفعال"
                    await callback.answer(
                        f"✅ بسته {status} شد!" if lang == "fa" else f"✅ Package {status}d!",
                        show_alert=True
                    )
                    await admin_package_edit(callback)
                    return
    
    await callback.answer("❌ بسته یافت نشد!", show_alert=True)

