@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_package_add'))
async def admin_package_add_process(message: Message):
    """پردازش مراحل افزودن بسته با پشتیبانی از IP Limit و حجم نامحدود"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply("❌ افزودن بسته لغو شد" if lang == "fa" else "❌ Cancelled")
        return
    
    state = user_states.get(admin_id, {})
    step = state.get('step')
    category_id = state.get('category_id')
    package_data = state.get('package_data', {})
    
    if not step or not category_id:
        user_states.pop(admin_id, None)
        await message.reply("❌ خطا: وضعیت نامعتبر")
        return
    
    try:
        if step == 'volume':
            volume = int(message.text.replace(',', '').replace(' ', '').strip())
            if volume < 0 or volume > 1000:
                await message.reply("❌ حجم باید بین ۰ تا ۱۰۰۰ گیگ باشد! (۰ = نامحدود)" if lang == "fa" else "❌ Volume must be between 0 and 1000 GB! (0 = Unlimited)")
                return
            
            package_data['volume'] = volume
            user_states[admin_id] = {
                'awaiting_package_add': True,
                'category_id': category_id,
                'step': 'days',
                'package_data': package_data
            }
            
            if lang == "fa":
                await message.reply(
                    "📝 <b>مرحله ۲ از ۴ - مدت (روز)</b>\n\n"
                    "لطفاً <b>مدت</b> را به روز وارد کنید:\n"
                    "(۱ تا ۳۶۵)\n\n"
                    "برای لغو /cancel را بفرستید",
                    parse_mode=ParseMode.HTML
                )
            else:
                await message.reply(
                    "📝 <b>Step 2 of 4 - Duration (days)</b>\n\n"
                    "Please enter <b>duration</b> in days:\n"
                    "(1 to 365)\n\n"
                    "Send /cancel to abort",
                    parse_mode=ParseMode.HTML
                )
        
        elif step == 'days':
            days = int(message.text.replace(',', '').replace(' ', '').strip())
            if days < 1 or days > 365:
                await message.reply("❌ مدت باید بین ۱ تا ۳۶۵ روز باشد!" if lang == "fa" else "❌ Duration must be between 1 and 365 days!")
                return
            
            package_data['days'] = days
            user_states[admin_id] = {
                'awaiting_package_add': True,
                'category_id': category_id,
                'step': 'price',
                'package_data': package_data
            }
            
            if lang == "fa":
                await message.reply(
                    "📝 <b>مرحله ۳ از ۴ - قیمت (تومان)</b>\n\n"
                    "لطفاً <b>قیمت</b> را به تومان وارد کنید:\n"
                    "(بزرگتر از صفر)\n\n"
                    "برای لغو /cancel را بفرستید",
                    parse_mode=ParseMode.HTML
                )
            else:
                await message.reply(
                    "📝 <b>Step 3 of 4 - Price (Toman)</b>\n\n"
                    "Please enter <b>price</b> in Toman:\n"
                    "(Greater than zero)\n\n"
                    "Send /cancel to abort",
                    parse_mode=ParseMode.HTML
                )
        
        elif step == 'price':
            price = int(message.text.replace(',', '').replace(' ', '').strip())
            if price <= 0:
                await message.reply("❌ قیمت باید بزرگتر از صفر باشد!" if lang == "fa" else "❌ Price must be greater than zero!")
                return
            
            package_data['price'] = price
            user_states[admin_id] = {
                'awaiting_package_add': True,
                'category_id': category_id,
                'step': 'ip_limit',
                'package_data': package_data
            }
            
            if lang == "fa":
                await message.reply(
                    "📝 <b>مرحله ۴ از ۴ - محدودیت IP</b>\n\n"
                    "لطفاً <b>محدودیت IP</b> را وارد کنید:\n"
                    "(۰ = نامحدود، ۱ = فقط یک دستگاه، و غیره)\n\n"
                    "برای لغو /cancel را بفرستید",
                    parse_mode=ParseMode.HTML
                )
            else:
                await message.reply(
                    "📝 <b>Step 4 of 4 - IP Limit</b>\n\n"
                    "Please enter <b>IP limit</b>:\n"
                    "(0 = unlimited, 1 = only one device, etc.)\n\n"
                    "Send /cancel to abort",
                    parse_mode=ParseMode.HTML
                )
        
        elif step == 'ip_limit':
            ip_limit = int(message.text.replace(',', '').replace(' ', '').strip())
            if ip_limit < 0:
                await message.reply("❌ محدودیت IP نمی‌تواند منفی باشد! (۰ = نامحدود)" if lang == "fa" else "❌ IP limit cannot be negative! (0 = Unlimited)")
                return
            
            package_data['ip_limit'] = ip_limit
            package_data['is_active'] = True
            
            for cat in READY_PACKAGES.get('categories', []):
                if cat.get('id') == category_id:
                    existing_ids = [p.get('id', 0) for p in cat.get('packages', [])]
                    package_data['id'] = max(existing_ids) + 1 if existing_ids else 1
                    
                    cat['packages'].append(package_data)
                    READY_PACKAGES['last_updated'] = datetime.now().isoformat()
                    
                    configs_pool['ready_packages'] = READY_PACKAGES
                    save_all()
                    
                    volume_display = "نامحدود" if package_data.get('volume', 0) == 0 else f"{package_data.get('volume')} GB"
                    ip_display = "نامحدود" if package_data.get('ip_limit', 0) == 0 else package_data.get('ip_limit')
                    
                    if lang == "fa":
                        await message.reply(
                            f"✅ <b>بسته با موفقیت اضافه شد!</b>\n\n"
                            f"📦 دسته: {cat.get('name')}\n"
                            f"📊 حجم: {volume_display}\n"
                            f"⏱ مدت: {package_data.get('days')} روز\n"
                            f"💰 قیمت: {package_data.get('price'):,} تومان\n"
                            f"👤 محدودیت IP: {ip_display}\n"
                            f"🆔 آیدی: {package_data.get('id')}",
                            parse_mode=ParseMode.HTML
                        )
                    else:
                        await message.reply(
                            f"✅ <b>Package added successfully!</b>\n\n"
                            f"📦 Category: {cat.get('name')}\n"
                            f"📊 Volume: {volume_display}\n"
                            f"⏱ Duration: {package_data.get('days')} days\n"
                            f"💰 Price: {package_data.get('price'):,} Toman\n"
                            f"👤 IP Limit: {ip_display}\n"
                            f"🆔 ID: {package_data.get('id')}",
                            parse_mode=ParseMode.HTML
                        )
                    
                    user_states.pop(admin_id, None)
                    await show_ready_packages_menu(message)
                    return
            
            await message.reply("❌ دسته یافت نشد!" if lang == "fa" else "❌ Category not found!")
            user_states.pop(admin_id, None)
    
    except ValueError:
        await message.reply("❌ لطفاً یک عدد معتبر وارد کنید!" if lang == "fa" else "❌ Please enter a valid number!")
    except Exception as e:
        logger.error(f"خطا در افزودن بسته: {e}", exc_info=True)
        await message.reply(f"❌ خطا: {str(e)}")
        user_states.pop(admin_id, None)







def save_ready_packages():
    """ذخیره تنظیمات بسته‌های آماده در دیتابیس"""
    try:
        for cat in READY_PACKAGES.get('categories', []):
            if 'inbound_ids' not in cat:
                old_inbound = cat.get('inbound_id')
                if old_inbound:
                    cat['inbound_ids'] = [old_inbound]
                else:
                    cat['inbound_ids'] = []
                cat['inbound_id'] = None
        
        configs_pool['ready_packages'] = READY_PACKAGES
        save_all()
        logger.info("📦 بسته‌های آماده با موفقیت ذخیره شدند")
        
        for cat in READY_PACKAGES.get('categories', []):
            inbound_ids = cat.get('inbound_ids', [])
            logger.info(f"  📡 {cat.get('name')}: اینباندهای ذخیره شده = {inbound_ids if inbound_ids else 'پیش‌فرض'}")
        
        return True
    except Exception as e:
        logger.error(f"❌ خطا در ذخیره بسته‌های آماده: {e}")
        return False

