@dp.message(lambda m: m.from_user.id == ADMIN_ID_INT and user_states.get(m.from_user.id, {}).get('awaiting_channel_id'))
async def force_join_add_channel(message: Message):
    """دریافت و افزودن کانال"""
    admin_id = message.from_user.id
    lang = get_user(admin_id).get('lang', 'fa')
    
    if message.text and message.text.strip() == '/cancel':
        user_states.pop(admin_id, None)
        await message.reply("❌ عملیات لغو شد" if lang=="fa" else "❌ Cancelled")
        return
    
    channel_input = message.text.strip()
    
    try:
        if channel_input.startswith('@'):
            chat = await bot.get_chat(channel_input)
            channel_id = chat.id
            channel_name = chat.title or channel_input
            channel_username = channel_input  # ذخیره یوزرنیم
        else:
            channel_id = int(channel_input)
            try:
                chat = await bot.get_chat(channel_id)
                channel_name = chat.title or str(channel_id)
                channel_username = chat.username if chat.username else None  # ذخیره یوزرنیم اگر وجود دارد
            except:
                channel_name = str(channel_id)
                channel_username = None
        bot_member = await bot.get_chat_member(channel_id, bot.id)
        if bot_member.status not in ['administrator', 'creator']:
            await message.reply("❌ ربات در این کانال ادمین نیست!" if lang=="fa" else "❌ Bot is not admin!")
            user_states.pop(admin_id, None)
            return
        settings = configs_pool.get('force_join_settings', {})
        channels = settings.get('channels', [])
        
        existing = [c for c in channels if c.get('id') == channel_id or c.get('id') == channel_input]
        if existing:
            await message.reply("❌ این کانال قبلاً اضافه شده است!" if lang=="fa" else "❌ Channel already exists!")
            user_states.pop(admin_id, None)
            return
        
        channels.append({
            'id': channel_id,
            'name': channel_name,
            'username': channel_username,  # ذخیره یوزرنیم
            'added_at': datetime.now().isoformat()
        })
        
        settings['channels'] = channels
        settings['last_updated'] = datetime.now().isoformat()
        configs_pool['force_join_settings'] = settings
        save_all()
        
        await message.reply(f"✅ کانال {channel_name} با موفقیت اضافه شد!" if lang=="fa" else f"✅ Channel {channel_name} added!")
        
        if log_system:
            await log_system.log_admin_action(admin_id, "افزودن کانال به عضویت اجباری", details=f"کانال: {channel_name}")
        
    except ValueError:
        await message.reply("❌ آیدی کانال نامعتبر است!" if lang=="fa" else "❌ Invalid channel ID!")
    except Exception as e:
        logger.error(f"خطا در افزودن کانال: {e}")
        await message.reply(f"❌ خطا: {str(e)[:100]}" if lang=="fa" else f"❌ Error: {str(e)[:100]}")
    
    user_states.pop(admin_id, None)
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="🔙 بازگشت به تنظیمات" if lang=="fa" else "🔙 Back to Settings", callback_data="admin_force_join")]
    ])
    await message.reply("🔄" if lang=="fa" else "🔄", reply_markup=keyboard)


