@dp.callback_query(F.data.startswith("force_join_remove_channel_"))
async def force_join_remove_channel(callback: CallbackQuery):
    """حذف کانال از لیست"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    channel_id = int(callback.data.split("_")[-1])
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    settings = configs_pool.get('force_join_settings', {})
    channels = settings.get('channels', [])
    
    removed = None
    for ch in channels:
        if ch.get('id') == channel_id:
            removed = ch
            channels.remove(ch)
            break
    
    if removed:
        settings['channels'] = channels
        settings['last_updated'] = datetime.now().isoformat()
        configs_pool['force_join_settings'] = settings
        save_all()
        
        await callback.answer(f"✅ کانال {removed.get('name')} حذف شد" if lang=="fa" else f"✅ Channel {removed.get('name')} removed", show_alert=True)
        
        if log_system:
            await log_system.log_admin_action(
                callback.from_user.id,
                "حذف کانال از لیست عضویت اجباری",
                details=f"کانال: {removed.get('name')} (ID: {channel_id})"
            )
    else:
        await callback.answer("❌ کانال یافت نشد" if lang=="fa" else "❌ Channel not found", show_alert=True)
    
    await admin_force_join_settings(callback)


@dp.callback_query(F.data == "force_join_check")
async def force_join_check_membership(callback: CallbackQuery):
    """بررسی عضویت کاربر فعلی"""
    user_id = callback.from_user.id
    if user_id == ADMIN_ID_INT:
        await callback.answer("👑 شما ادمین هستید!", show_alert=True)
        return
    
    settings = configs_pool.get('force_join_settings', {})
    
    if not settings.get('enabled', False):
        await callback.answer("✅ قابلیت عضویت اجباری غیرفعال است" if get_user(user_id).get('lang', 'fa') == "fa" else "✅ Force join is disabled", show_alert=True)
        return
    
    channels = settings.get('channels', [])
    
    if not channels:
        await callback.answer("✅ هیچ کانالی ثبت نشده است" if get_user(user_id).get('lang', 'fa') == "fa" else "✅ No channels registered", show_alert=True)
        return
    
    not_joined = []
    
    for ch in channels:
        try:
            member = await bot.get_chat_member(ch.get('id'), user_id)
            if member.status in ['left', 'kicked']:
                not_joined.append(ch)
        except Exception as e:
            logger.error(f"خطا در بررسی عضویت کانال {ch.get('id')}: {e}")
            not_joined.append(ch)
    
    lang = get_user(user_id).get('lang', 'fa')
    
    if not_joined:
        text = "❌ شما در کانال‌های زیر عضو نیستید:\n\n" if lang == "fa" else "❌ You are not a member of:\n\n"
        for ch in not_joined:
            text += f"• {ch.get('name', ch.get('id'))}\n"
        text += f"\nلطفاً ابتدا عضو شوید سپس دوباره تلاش کنید." if lang == "fa" else f"\nPlease join first then try again."
        await callback.answer(text, show_alert=True)
    else:
        await callback.answer("✅ شما در تمام کانال‌های اجباری عضو هستید!" if lang == "fa" else "✅ You are a member of all required channels!", show_alert=True)
        
        
        
        
async def check_membership(user_id: int) -> bool:
    """
    بررسی کامل عضویت کاربر در کانال‌های اجباری
    """
    if user_id == ADMIN_ID_INT:
        return True
    
    settings = configs_pool.get('force_join_settings', {})
    
    if not settings.get('enabled', False):
        return True
    
    channels = settings.get('channels', [])
    
    if not channels:
        return True
    
    # بررسی واقعی عضویت
    for ch in channels:
        try:
            channel_id = ch.get('id')
            member = await bot.get_chat_member(channel_id, user_id)
            if member.status in ['left', 'kicked']:
                return False
        except Exception as e:
            logger.error(f"خطا در بررسی عضویت کاربر {user_id} در کانال {channel_id}: {e}")
            return False
    
    return True

async def verify_membership(user_id: int) -> bool:
    """
    بررسی و ثبت عضویت کاربر - نسخه ساده
    """
    if user_id == ADMIN_ID_INT:
        return True
    
    # استفاده از تابع دقیق
    membership_report = await check_membership_detailed(user_id)
    
    if membership_report['is_all_joined']:
        # اگر کاربر عضو همه کانال‌هاست، وضعیت verified را ثبت کن
        user = get_user(user_id)
        if user:
            user['verified'] = True
            user['updated_at'] = datetime.now().isoformat()
            save_json(DB_FILES['users'], users)
            logger.info(f"✅ کاربر {user_id} عضویت در کانال‌ها را تایید کرد")
        return True
    else:
        # اگر کاربر عضو نیست، verified را False کن
        user = get_user(user_id)
        if user and user.get('verified', False):
            user['verified'] = False
            user['updated_at'] = datetime.now().isoformat()
            save_json(DB_FILES['users'], users)
            logger.warning(f"⚠️ کاربر {user_id} از کانال لفت داده، verified به False تغییر کرد")
        return False

@dp.callback_query(F.data == "verify_membership")
async def process_verify_membership(callback: CallbackQuery):
    """
    بررسی عضویت کاربر بعد از کلیک روی دکمه تایید
    """
    user_id = callback.from_user.id
    lang = get_user(user_id).get('lang', 'fa')
    
    try:
        # بررسی دقیق عضویت با جزئیات
        membership_report = await check_membership_detailed(user_id)
        
        if membership_report['is_all_joined']:
            # کاربر عضو همه کانال‌هاست - ثبت وضعیت
            user = get_user(user_id)
            if user:
                user['verified'] = True
                user['updated_at'] = datetime.now().isoformat()
                save_json(DB_FILES['users'], users)
                logger.info(f"✅ کاربر {user_id} عضویت در همه کانال‌ها تایید شد")
            
            if lang == "fa":
                success_text = f"""
{premium_emoji('success', '✅')} <b>عضویت شما تایید شد!</b>

{premium_emoji('rocket', '🚀')} به ربات خوش آمدید.
"""
            else:
                success_text = f"""
{premium_emoji('success', '✅')} <b>Membership confirmed!</b>

{premium_emoji('rocket', '🚀')} Welcome to the bot.
"""
            
            await callback.message.delete()
            await callback.message.answer(
                success_text,
                parse_mode=ParseMode.HTML,
                reply_markup=get_main_keyboard(False, lang, user_id)
            )
            
        else:
            # کاربر عضو همه کانال‌ها نیست
            not_joined = membership_report['not_joined']
            left_channels = membership_report['left_channels']
            kicked_channels = membership_report['kicked_channels']
            
            # ساخت پیام خطا با جزئیات
            if lang == "fa":
                warning_text = f"""
{premium_emoji('danger', '⚠️')} <b>عضویت شما کامل نیست!</b>

"""
                if left_channels:
                    warning_text += f"""
{premium_emoji('exit', '🚪')} <b>کانال‌هایی که لفت دادید:</b>
{chr(10).join([f"• {ch}" for ch in left_channels])}

"""
                
                if kicked_channels:
                    warning_text += f"""
{premium_emoji('ban', '⛔')} <b>کانال‌هایی که بن شدید:</b>
{chr(10).join([f"• {ch}" for ch in kicked_channels])}

"""
                
                warning_text += f"""
{premium_emoji('info', 'ℹ️')} لطفاً ابتدا در همه کانال‌ها عضو شوید و سپس دوباره تلاش کنید.
"""
            else:
                warning_text = f"""
{premium_emoji('danger', '⚠️')} <b>Membership incomplete!</b>

"""
                if left_channels:
                    warning_text += f"""
{premium_emoji('exit', '🚪')} <b>Left channels:</b>
{chr(10).join([f"• {ch}" for ch in left_channels])}

"""
                
                if kicked_channels:
                    warning_text += f"""
{premium_emoji('ban', '⛔')} <b>Kicked from:</b>
{chr(10).join([f"• {ch}" for ch in kicked_channels])}

"""
                
                warning_text += f"""
{premium_emoji('info', 'ℹ️')} Please join all channels first and try again.
"""
            
            # به‌روزرسانی وضعیت verified به False
            user = get_user(user_id)
            if user and user.get('verified', False):
                user['verified'] = False
                user['updated_at'] = datetime.now().isoformat()
                save_json(DB_FILES['users'], users)
                logger.warning(f"⚠️ کاربر {user_id} از کانال لفت داده، verified به False تغییر کرد")
            
            await callback.answer("❌ هنوز عضو نشده‌اید!", show_alert=True)
            
            # نمایش مجدد صفحه عضویت با لینک‌ها
            try:
                await callback.message.delete()
            except:
                pass
            
            await show_verification_page(callback.message, user_id, lang)
            
    except Exception as e:
        logger.error(f"❌ خطا در بررسی عضویت: {e}")
        await callback.answer("❌ خطا در بررسی، لطفاً دوباره تلاش کنید", show_alert=True)

async def show_verification_page(message: Message, user_id: int, lang: str = "fa"):
    """نمایش صفحه تایید عضویت با لینک کانال‌ها"""
    settings = configs_pool.get('force_join_settings', {})
    channels = settings.get('channels', [])
    buttons = []
    
    for ch in channels:
        channel_name = ch.get('name', 'کانال')
        channel_username = ch.get('username')
        
        # ساخت لینک مناسب
        if channel_username and channel_username.startswith('@'):
            channel_link = f"https://t.me/{channel_username[1:]}"
        elif channel_username:
            channel_link = f"https://t.me/{channel_username}"
        else:
            channel_id = ch.get('id')
            if isinstance(channel_id, int) and channel_id < 0:
                # برای کانال‌های خصوصی
                channel_id_str = str(channel_id).replace('-100', '')
                channel_link = f"https://t.me/c/{channel_id_str}"
            else:
                channel_link = f"https://t.me/{channel_id}"
        
        buttons.append([InlineKeyboardButton(
            text=f"📢 عضویت در {channel_name}",
            url=channel_link
        )])
    
    buttons.append([InlineKeyboardButton(
        text="✅ تایید عضویت",
        callback_data="verify_membership",
        style="primary"
    )])
    
    if lang == "fa":
        text = f"""
🔒 <b>تایید عضویت</b>

{premium_emoji('warning', '⚠️')} برای استفاده از ربات، ابتدا باید در کانال‌های زیر عضو شوید:

"""
        for ch in channels:
            text += f"• {ch.get('name', ch.get('id'))}\n"
        
        text += f"""

{premium_emoji('link', '🔗')} روی دکمه هر کانال کلیک کنید و عضو شوید.

{premium_emoji('info', 'ℹ️')} پس از عضویت در تمام کانال‌ها، دکمه <b>تایید عضویت</b> را بزنید.
"""
    else:
        text = f"""
🔒 <b>Membership Verification</b>

{premium_emoji('warning', '⚠️')} To use the bot, you must join the following channels:

"""
        for ch in channels:
            text += f"• {ch.get('name', ch.get('id'))}\n"
        
        text += f"""

{premium_emoji('link', '🔗')} Click the button of each channel and join.

{premium_emoji('info', 'ℹ️')} After joining all channels, click the <b>Verify Membership</b> button.
"""
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=buttons)
    
    await message.answer(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    
    
@dp.message(lambda message: message.from_user.id == ADMIN_ID_INT and user_states.get(message.from_user.id, {}).get('awaiting_config', False))
async def catch_admin_messages(message: Message):
    """هندلر مخصوص ادمین - تایید خودکار از طریق پنل"""
    admin_id = message.from_user.id
    state = user_states.get(admin_id, {})
    
    order_id = state.get('order_id')
    user_id = state.get('user_id')
    volume = state.get('volume')
    days = state.get('days')
    price = state.get('price')
    user_info = get_user(user_id)
    user_name = user_info.get('name', f'کاربر_{user_id}')
    lang = user_info.get('lang', 'fa')
    
    logger.info(f"🔴 تایید خودکار سفارش #{order_id} - ساخت کلاینت در پنل...")
    update_order(order_id, status='approved', approved_date=datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
    await check_referral_bonus(user_id)
    if SENAI_PANEL_ENABLED:
        await message.reply(f"⏳ در حال ساخت کلاینت در پنل برای سفارش #{order_id}...")
        
        timestamp = int(datetime.now().timestamp())
        email = f"user{user_id}_{timestamp}"
        ip_limit = state.get('ip_limit', 0)
        sub_link = await create_client_in_panel(user_id, email, volume, days, user_name, ip_limit=ip_limit)
        
        if sub_link:
            update_order(order_id, config_link=sub_link, email=email)
            await send_config_with_qr_option(user_id, order_id, volume, days, price, sub_link, lang)
            try:
                await bot.send_message(user_id, 
                    f"{premium_emoji('star', '⭐')} {'لطفا به سرویس ما امتیاز دهید:' if lang=='fa' else 'Please rate our service:'}",
                    reply_markup=get_feedback_keyboard(order_id, lang)
                )
            except Exception as e:
                logger.error(f"خطا در ارسال درخواست بازخورد: {e}")
            
            await message.reply(
                f"✅ سفارش #{order_id} تایید شد!\n"
                f"👤 کاربر: {user_name} ({user_id})\n"
                f"📦 {volume}GB / {days} روز\n"
                f"🔗 لینک ساب: {sub_link[:50]}..."
            )
        else:
            await message.reply(f"❌ خطا در ساخت کلاینت برای سفارش #{order_id}")
            user = get_user(user_id)
            update_user(user_id, 'balance', user['balance'] + price)
            
            try:
                await bot.send_message(user_id,
                    f"{premium_emoji('danger', '❌')} {'متاسفانه خطایی رخ داد. موجودی شما برگشت داده شد.' if lang=='fa' else 'An error occurred. Your balance has been refunded.'}"
                )
            except:
                pass
    else:
        config_link = message.text.strip()
        
        update_order(order_id, config_link=config_link)
        await send_config_with_qr_option(user_id, order_id, volume, days, price, config_link, lang)
        
        try:
            await bot.send_message(user_id, 
                f"{premium_emoji('star', '⭐')} {'لطفا به سرویس ما امتیاز دهید:' if lang=='fa' else 'Please rate our service:'}",
                reply_markup=get_feedback_keyboard(order_id, lang)
            )
        except Exception as e:
            logger.error(f"خطا در ارسال درخواست بازخورد: {e}")
        
        await message.reply(f"✅ کانفیگ سفارش #{order_id} با موفقیت ارسال شد!")
    user_states.pop(admin_id, None)
    logger.info(f"وضعیت ادمین پاک شد")
@dp.callback_query(F.data == "back_to_main")
async def back_to_main(callback: CallbackQuery):
    user_id = callback.from_user.id
    save_coupon_to_user_db(user_id)
    debug_coupon_state(user_id, "back_to_main_start")
    user = get_user(user_id)
    lang = user.get('lang', 'fa')
    is_admin = (user_id == ADMIN_ID_INT)
    before_state = user_states.get(user_id, {})
    logger.debug(f"کاربر {user_id} به منوی اصلی برگشت - وضعیت قبلی: {before_state}")
    coupon_code = before_state.get('coupon_code')
    coupon_discount = before_state.get('coupon_discount')
    coupon_applied = before_state.get('coupon_applied')
    
    logger.info(f"🔍 کوپن در back_to_main - code: {coupon_code}, applied: {coupon_applied}, discount: {coupon_discount}")
    if user_id in user_states:
        user_states.pop(user_id, None)
    if coupon_applied and coupon_code:
        user_states[user_id] = {
            'coupon_code': coupon_code,
            'coupon_discount': coupon_discount,
            'coupon_applied': True
        }
        logger.info(f"🏷️ کوپن {coupon_code} برای کاربر {user_id} در back_to_main حفظ شد")
    else:
        logger.warning(f"⚠️ کوپنی برای کاربر {user_id} در back_to_main یافت نشد - coupon_applied: {coupon_applied}, coupon_code: {coupon_code}")
    after_state = user_states.get(user_id, {})
    logger.info(f"🔍 وضعیت نهایی user_states در back_to_main: {after_state}")
    
    if lang == "fa":
        text = f"{premium_emoji('rocket', '🚀')} منوی اصلی"
    else:
        text = f"{premium_emoji('rocket', '🚀')} Main Menu"
    if callback.message.content_type == 'text':
        await callback.message.edit_text(text, reply_markup=get_main_keyboard(is_admin, lang))
    else:
        try:
            await callback.message.delete()
        except Exception as e:
            logger.warning(f"نتوانست پیام را حذف کند: {e}")
        
        await bot.send_message(
            callback.message.chat.id,
            text,
            reply_markup=get_main_keyboard(is_admin, lang)
        )
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")
        
        
def preserve_coupon_in_state(user_id: int) -> bool:
    """
    اطمینان از وجود کوپن در user_states
    اگر کوپن در جای دیگری ذخیره شده باشد، آن را به user_states اضافه می‌کند
    """
    user_state = user_states.get(user_id, {})
    if user_state.get('coupon_applied') and user_state.get('coupon_code'):
        logger.info(f"🏷️ کوپن {user_state.get('coupon_code')} قبلاً در user_states وجود دارد")
        return True
    return False

def debug_coupon_state(user_id: int, location: str):
    """دیباگ وضعیت کوپن در نقاط مختلف"""
    user_state = user_states.get(user_id, {})
    coupon_code = user_state.get('coupon_code')
    coupon_applied = user_state.get('coupon_applied', False)
    
    logger.info(f"🔍 [{location}] کوپن: code={coupon_code}, applied={coupon_applied}, state={user_state}")
    if location not in ['back_to_main', 'cancel_order_direct', 'cancel_payment']:
        if not coupon_applied or not coupon_code:
            logger.warning(f"⚠️ [{location}] کوپن وجود ندارد!")      
        
