@dp.callback_query(F.data == "retry_broadcast_failed")
async def retry_broadcast_failed(callback: CallbackQuery):
    """ارسال مجدد به کاربرانی که پیام را دریافت نکرده‌اند"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    await callback.message.edit_text(
        "⏳ در حال ارسال مجدد به کاربران ناموفق..." if lang=="fa" else "⏳ Retrying failed users..."
    )
    
    await callback.message.edit_text(
        "🔄 قابلیت ارسال مجدد به کاربران ناموفق در حال توسعه است.\n"
        "لطفاً پیام را دوباره ارسال کنید." if lang=="fa" else 
        "🔄 Retry for failed users is under development.\n"
        "Please send the message again.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(
                text="🔙 برگشت به پنل" if lang=="fa" else "🔙 Back to Panel",
                callback_data="admin_panel"
            )]
        ])
    )
    
    try:
        await callback.answer()
    except:
        pass                              
@dp.callback_query(F.data == "confirm_broadcast")
async def confirm_broadcast(callback: CallbackQuery):
    """تأیید نهایی و ارسال پیام همگانی"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    state = user_states.get(callback.from_user.id, {})
    broadcast_data = state.get('broadcast_data', {})
    
    if not broadcast_data:
        await callback.answer("❌ داده‌ای برای ارسال وجود ندارد" if lang=="fa" else "❌ No data to send", show_alert=True)
        return
    logger.info(f"📢 شروع ارسال پیام همگانی:")
    logger.info(f"  - نوع: {broadcast_data.get('type')}")
    logger.info(f"  - media: {broadcast_data.get('media')}")
    logger.info(f"  - caption: {broadcast_data.get('caption', '')[:50]}...")
    logger.info(f"  - parse_mode: {broadcast_data.get('parse_mode')}")
    logger.info(f"  - تعداد کاربران: {len(users)}")
    status_msg = await callback.message.answer(
        "⏳ در حال ارسال پیام همگانی..." if lang=="fa" else "⏳ Sending broadcast..."
    )
    logger.info(f"✅ پیام وضعیت با message_id={status_msg.message_id} ارسال شد")
    sent_count = 0
    failed_count = 0
    failed_users = []
    users_list = list(users.keys())
    total_users = len(users_list)
    
    broadcast_type = broadcast_data.get('type', 'text')
    media = broadcast_data.get('media')
    caption = broadcast_data.get('caption', '')
    parse_mode = broadcast_data.get('parse_mode', None)
    MAX_CAPTION_LENGTH = 1000
    original_caption = caption
    
    if len(caption) > MAX_CAPTION_LENGTH:
        logger.warning(f"⚠️ کپشن طولانی است ({len(caption)} کاراکتر)، در حال کوتاه کردن...")
        
        if broadcast_type in ['photo', 'file', 'audio']:
            truncated = caption[:MAX_CAPTION_LENGTH - 50] + "...\n\n[کپشن کامل در فایل پیوست]"
            caption = truncated
            logger.info(f"✅ کپشن به {len(caption)} کاراکتر کوتاه شد")
            
            try:
                from io import BytesIO
                file_buffer = BytesIO()
                file_buffer.write(original_caption.encode('utf-8'))
                file_buffer.seek(0)
                
                from aiogram.types import BufferedInputFile
                input_file = BufferedInputFile(file_buffer.read(), filename="full_caption.txt")
                
                await callback.message.answer_document(
                    document=input_file,
                    caption="📄 کپشن کامل پیام (به دلیل محدودیت تلگرام، کپشن کامل در این فایل ارسال شد)"
                )
            except Exception as e:
                logger.error(f"خطا در ارسال فایل کپشن کامل: {e}")
    
    clean_caption = sanitize_text_for_broadcast(caption)
    
    if parse_mode == ParseMode.HTML and clean_caption != caption:
        parse_mode = None
        logger.warning(f"⚠️ متن حاوی کاراکترهای غیرمجاز بود، HTML غیرفعال شد")
    for i, uid in enumerate(users_list):
        try:
            user_id = int(uid)
            
            if broadcast_type == 'text':
                if len(clean_caption) > 4096:
                    parts = [clean_caption[i:i+4096] for i in range(0, len(clean_caption), 4096)]
                    for part in parts:
                        await bot.send_message(user_id, part, parse_mode=parse_mode)
                else:
                    await bot.send_message(user_id, clean_caption, parse_mode=parse_mode)
                    
            elif broadcast_type == 'photo':
                if not media:
                    raise ValueError("media_id is None")
                await bot.send_photo(user_id, media, caption=clean_caption, parse_mode=parse_mode)
                
            elif broadcast_type == 'file':
                if not media:
                    raise ValueError("media_id is None")
                await bot.send_document(user_id, media, caption=clean_caption, parse_mode=parse_mode)
                
            elif broadcast_type == 'audio':
                if not media:
                    raise ValueError("media_id is None")
                await bot.send_audio(user_id, media, caption=clean_caption, parse_mode=parse_mode)
            
            sent_count += 1
            if (i + 1) % 10 == 0:
                progress_text = f"⏳ در حال ارسال... {i+1}/{total_users}" if lang=="fa" else f"⏳ Sending... {i+1}/{total_users}"
                try:
                    await status_msg.edit_text(progress_text)
                    logger.debug(f"✅ پیام وضعیت بروزرسانی شد: {i+1}/{total_users}")
                except Exception as e:
                    logger.warning(f"⚠️ خطا در بروزرسانی پیام وضعیت: {e}")
                    try:
                        await status_msg.delete()
                    except:
                        pass
                    status_msg = await callback.message.answer(progress_text)
                    logger.info(f"✅ پیام وضعیت جدید ارسال شد: {progress_text}")
            
            await asyncio.sleep(0.05)
            
        except Exception as e:
            error_str = str(e)
            logger.error(f"❌ خطا در ارسال به کاربر {uid}: {error_str}")
            if "can't parse entities" in error_str and parse_mode == ParseMode.HTML:
                try:
                    if broadcast_type == 'text':
                        await bot.send_message(int(uid), clean_caption, parse_mode=None)
                    elif broadcast_type == 'photo' and media:
                        await bot.send_photo(int(uid), media, caption=clean_caption, parse_mode=None)
                    elif broadcast_type == 'file' and media:
                        await bot.send_document(int(uid), media, caption=clean_caption, parse_mode=None)
                    elif broadcast_type == 'audio' and media:
                        await bot.send_audio(int(uid), media, caption=clean_caption, parse_mode=None)
                    sent_count += 1
                    continue
                except Exception as e2:
                    logger.warning(f"⚠️ تلاش مجدد نیز خطا داد: {e2}")
            
            if "message caption is too long" in error_str and broadcast_type in ['photo', 'file', 'audio']:
                try:
                    if broadcast_type == 'photo' and media:
                        await bot.send_photo(int(uid), media)
                    elif broadcast_type == 'file' and media:
                        await bot.send_document(int(uid), media)
                    elif broadcast_type == 'audio' and media:
                        await bot.send_audio(int(uid), media)
                    sent_count += 1
                    if clean_caption:
                        await bot.send_message(int(uid), clean_caption[:4000], parse_mode=parse_mode)
                    continue
                except Exception as e3:
                    logger.warning(f"⚠️ تلاش مجدد بدون کپشن نیز خطا داد: {e3}")
            
            failed_count += 1
            failed_users.append(uid)
    user_states.pop(callback.from_user.id, None)
    try:
        if status_msg:
            await status_msg.delete()
            logger.info(f"✅ پیام وضعیت با message_id={status_msg.message_id} حذف شد")
        else:
            logger.warning("⚠️ پیام وضعیت وجود ندارد")
    except Exception as e:
        logger.warning(f"⚠️ خطا در حذف پیام وضعیت: {e}")
        try:
            if "message to delete not found" in str(e):
                logger.info("ℹ️ پیام وضعیت قبلاً حذف شده بود")
            else:
                logger.error(f"❌ خطا در حذف پیام وضعیت: {e}")
        except:
            pass
    result_text = f"""
✅ <b>پیام همگانی ارسال شد!</b>

📤 موفق: {sent_count}
❌ ناموفق: {failed_count}
📊 تعداد کل: {total_users}
📝 نوع: {broadcast_type}
🕐 زمان: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}

{f"⚠️ کپشن به {MAX_CAPTION_LENGTH} کاراکتر کوتاه شد" if len(original_caption) > MAX_CAPTION_LENGTH else ""}

{f"❌ کاربران ناموفق: {', '.join(failed_users[:10])}" if failed_users else ""}
{f"⚠️ {len(failed_users) - 10} کاربر دیگر..." if len(failed_users) > 10 else ""}
"""
    keyboard_rows = []
    
    if failed_users:
        keyboard_rows.append([
            InlineKeyboardButton(
                text="🔄 ارسال مجدد به کاربران ناموفق" if lang=="fa" else "🔄 Retry Failed Users",
                callback_data="retry_broadcast_failed",
                style="primary"
            )
        ])
    
    keyboard_rows.append([
        InlineKeyboardButton(
            text="📢 ارسال پیام جدید" if lang=="fa" else "📢 New Broadcast",
            callback_data="admin_broadcast",
            style="primary"
        )
    ])
    
    keyboard_rows.append([
        InlineKeyboardButton(
            text="🔙 برگشت به پنل" if lang=="fa" else "🔙 Back to Panel",
            callback_data="admin_panel"
        )
    ])
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=keyboard_rows)
    try:
        try:
            await callback.message.delete()
        except:
            pass
        await callback.message.answer(result_text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
        logger.info("✅ گزارش ارسال شد")
    except Exception as e:
        logger.error(f"❌ خطا در ارسال گزارش: {e}")
        await callback.message.answer(result_text, parse_mode=ParseMode.HTML)
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")
        
        
        
async def safe_edit_callback(
    callback: CallbackQuery, 
    text: str = None, 
    reply_markup: InlineKeyboardMarkup = None,
    parse_mode: ParseMode = ParseMode.HTML,
    **kwargs
):
    """ویرایش امن پیام با مدیریت خطاهای مختلف"""
    try:
        if callback.message.content_type != 'text' and text:
            try:
                await callback.message.delete()
            except:
                pass
            await callback.message.answer(text, reply_markup=reply_markup, parse_mode=parse_mode, **kwargs)
            return True
        if text and reply_markup:
            await callback.message.edit_text(text, reply_markup=reply_markup, parse_mode=parse_mode, **kwargs)
        elif reply_markup:
            await callback.message.edit_reply_markup(reply_markup=reply_markup)
        elif text:
            await callback.message.edit_text(text, parse_mode=parse_mode, **kwargs)
        return True
        
    except Exception as e:
        error_str = str(e)
        if "message is not modified" in error_str:
            logger.debug(f"Message not modified for user {callback.from_user.id}")
            return True
        elif "there is no text in the message to edit" in error_str:
            try:
                await callback.message.delete()
            except:
                pass
            if text:
                await callback.message.answer(text, reply_markup=reply_markup, parse_mode=parse_mode, **kwargs)
            return True
        elif "can't parse entities" in error_str:
            logger.warning(f"HTML parse error, sending without HTML: {error_str}")
            try:
                if text:
                    import re
                    clean_text = re.sub(r'<[^>]+>', '', text)
                    await callback.message.edit_text(clean_text, reply_markup=reply_markup, parse_mode=None)
                return True
            except:
                pass
            try:
                await callback.message.delete()
            except:
                pass
            if text:
                import re
                clean_text = re.sub(r'<[^>]+>', '', text)
                await callback.message.answer(clean_text, reply_markup=reply_markup, parse_mode=None)
            return True
        else:
            logger.error(f"Error in safe_edit_callback: {e}")
            raise
        
        

def sanitize_text_for_broadcast(text: str) -> str:
    """پاکسازی متن برای ارسال به کاربران"""
    if not text:
        return ""
    dangerous_patterns = [
        r'؟<؟',  # الگوی خاص
        r'<[^a-zA-Z/]',  # تگ‌های ناقص
        r'[^\w\s<>/="\']<[^\w\s<>/="\']',  # کاراکتر قبل از <
    ]
    
    import re
    for pattern in dangerous_patterns:
        text = re.sub(pattern, '', text)
    tags = re.findall(r'<([a-zA-Z][a-zA-Z0-9]*)[^>]*>', text)
    for tag in tags:
        if tag not in ['b', 'i', 'u', 's', 'code', 'pre', 'a', 'tg-emoji']:
            text = text.replace(f'<{tag}', f'&lt;{tag}')
            text = text.replace(f'</{tag}', f'&lt;/{tag}')
    text = ''.join(char for char in text if ord(char) >= 32 or char in '\n\r\t')
    
    return text  
