async def xui_get_client_links(email: str) -> Optional[list]:
    """دریافت لینک‌های کانفیگ از پنل"""
    cookie = await xui_login()
    if not cookie:
        return None
    
    try:
        connector = aiohttp.TCPConnector(ssl=False)
        
        async with aiohttp.ClientSession(connector=connector) as session:
            csrf = await xui_get_csrf_token(session)
            headers = {"X-CSRF-Token": csrf} if csrf else {}
            
            async with session.get(
                f"{SENAI_PANEL_URL}/panel/api/clients/links/{email}",
                cookies={"3x-ui": cookie},
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as response:
                if response.status == 200:
                    data = await response.json()
                    logger.info(f"🔍 Client links: {json.dumps(data, indent=2)}")
                    if data.get("success"):
                        return data.get("obj", [])
                return None
    except Exception as e:
        logger.error(f"❌ خطا در دریافت لینک‌ها: {e}")
        return None


def extract_vless_link(links: list) -> Optional[str]:
    """استخراج لینک VLESS از لیست"""
    if not links:
        return None
    
    for link in links:
        if isinstance(link, str) and link.startswith('vless://'):
            return link
    return None

