def create_chat(user_id: int, feedback_id: int) -> int:
    """ایجاد چت جدید"""
    chat_id = len(chats) + 1
    chats[str(chat_id)] = {
        'id': chat_id,
        'user_id': user_id,
        'feedback_id': feedback_id,
        'status': 'open',  # open, closed
        'messages': [],
        'created_at': datetime.now().isoformat(),
        'updated_at': datetime.now().isoformat()
    }
    save_all()
    return chat_id


def add_message(chat_id: int, sender: str, text: str):
    """اضافه کردن پیام به چت"""
    cid = str(chat_id)
    if cid in chats:
        chats[cid]['messages'].append({
            'sender': sender,  # 'admin' یا 'user'
            'text': text,
            'time': datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        })
        chats[cid]['updated_at'] = datetime.now().isoformat()
        save_all()


def close_chat(chat_id: int, closed_by: str = "user"):
    """بستن چت با اطلاع‌رسانی به ادمین"""
    cid = str(chat_id)
    
    chat = chats.get(cid)
    if chat:
        user_id = chat.get('user_id')
        if log_system and user_id:
            asyncio.create_task(log_system.log_chat_closed(chat_id, user_id, closed_by))
        chat['status'] = 'closed'
        chat['closed_by'] = closed_by
        chat['closed_at'] = datetime.now().isoformat()
        chat['updated_at'] = datetime.now().isoformat()
        save_all()
        if closed_by == "user":
            asyncio.create_task(
                bot.send_message(
                    ADMIN_ID_INT,
                    f"🔒 چت #{chat_id} توسط کاربر بسته شد.\n"
                    f"👤 کاربر: {get_user(user_id).get('name', 'نامشخص')} (ID: {user_id})\n"
                    f"🕐 زمان: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
                )
            )
        
        logger.info(f"چت #{chat_id} بسته شد - توسط: {closed_by}")
        return True
    
    logger.warning(f"چت #{chat_id} برای بسته شدن یافت نشد")
    return False


def get_active_chats() -> list:
    """دریافت چت‌های فعال"""
    return [c for c in chats.values() if c.get('status') == 'open']


def get_user_chat(user_id: int) -> Optional[dict]:
    """دریافت چت فعال کاربر"""
    for c in chats.values():
        if c.get('user_id') == user_id and c.get('status') == 'open':
            return c
    return None


@dp.message(lambda m: user_states.get(m.from_user.id, {}).get('awaiting_chat', False))
async def handle_chat_message(message: Message):
    """دریافت پیام چت از کاربر - با پشتیبانی از فایل"""
    user_id = message.from_user.id
    if await block_unauthorized(message, message.from_user.id):
        return
    
    state = user_states.get(user_id, {})
    chat_id = state.get('chat_id')
    lang = get_user(user_id).get('lang', 'fa')
    
    if not chat_id:
        return
    
    chat = chats.get(str(chat_id))
    if not chat or chat.get('status') == 'closed':
        if lang == "fa":
            await message.reply("❌ این گفتگو بسته شده است.\nبرای شروع مجدد از بخش بازخورد اقدام کنید.")
        else:
            await message.reply("❌ This conversation is closed.\nTo start again, use the feedback section.")
        user_states.pop(user_id, None)
        return
    if message.text and message.text.strip() == '/end':
        close_chat(chat_id, closed_by="user")
        user_states.pop(user_id, None)
        if lang == "fa":
            await message.reply("✅ گفتگو پایان یافت. متشکریم!", reply_markup=get_back_only_keyboard(lang))
        else:
            await message.reply("✅ Conversation ended. Thank you!", reply_markup=get_back_only_keyboard(lang))
        return
    text_content = ""
    file_info = None
    file_type = None
    
    if message.text:
        text_content = message.text
    elif message.caption:
        text_content = message.caption
    elif message.document:
        file_type = "document"
        file_info = f"📄 {message.document.file_name}"
        text_content = f"[فایل: {message.document.file_name}]"
    elif message.photo:
        file_type = "photo"
        file_info = f"📸 عکس"
        text_content = "[عکس]"
    elif message.video:
        file_type = "video"
        file_info = f"🎬 {message.video.file_name if message.video.file_name else 'ویدیو'}"
        text_content = f"[ویدیو: {message.video.file_name if message.video.file_name else 'ویدیو'}]"
    elif message.audio:
        file_type = "audio"
        file_info = f"🎵 {message.audio.file_name if message.audio.file_name else 'صدا'}"
        text_content = f"[صدا: {message.audio.file_name if message.audio.file_name else 'صدا'}]"
    elif message.voice:
        file_type = "voice"
        file_info = f"🎤 ویس"
        text_content = "[ویس]"
    elif message.video_note:
        file_type = "video_note"
        file_info = f"📹 ویدیو نوت"
        text_content = "[ویدیو نوت]"
    elif message.sticker:
        file_type = "sticker"
        file_info = f"🏷️ استیکر"
        text_content = "[استیکر]"
    elif message.animation:
        file_type = "animation"
        file_info = f"🎞️ گیف"
        text_content = "[گیف]"
    else:
        await message.reply("❌ نوع فایل پشتیبانی نمی‌شود.")
        return
    add_message(chat_id, 'user', text_content)
    admin_text = f"💬 <b>پیام جدید از کاربر {user_id}</b>\n🆔 چت: #{chat_id}\n\n{text_content}"
    
    admin_kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="💬 پاسخ", callback_data=f"admin_chat_{chat_id}")]
    ])
    
    try:
        if file_type and message.document:
            await bot.send_document(
                ADMIN_ID_INT,
                message.document.file_id,
                caption=admin_text,
                parse_mode=ParseMode.HTML,
                reply_markup=admin_kb
            )
        elif file_type and message.photo:
            await bot.send_photo(
                ADMIN_ID_INT,
                message.photo[-1].file_id,
                caption=admin_text,
                parse_mode=ParseMode.HTML,
                reply_markup=admin_kb
            )
        elif file_type and message.video:
            await bot.send_video(
                ADMIN_ID_INT,
                message.video.file_id,
                caption=admin_text,
                parse_mode=ParseMode.HTML,
                reply_markup=admin_kb
            )
        elif file_type and message.audio:
            await bot.send_audio(
                ADMIN_ID_INT,
                message.audio.file_id,
                caption=admin_text,
                parse_mode=ParseMode.HTML,
                reply_markup=admin_kb
            )
        elif file_type and message.voice:
            await bot.send_voice(
                ADMIN_ID_INT,
                message.voice.file_id,
                caption=admin_text,
                parse_mode=ParseMode.HTML,
                reply_markup=admin_kb
            )
        elif file_type and message.video_note:
            await bot.send_video_note(
                ADMIN_ID_INT,
                message.video_note.file_id,
                reply_markup=admin_kb
            )
            await bot.send_message(ADMIN_ID_INT, admin_text, parse_mode=ParseMode.HTML)
        else:
            await bot.send_message(ADMIN_ID_INT, admin_text, parse_mode=ParseMode.HTML, reply_markup=admin_kb)
    except Exception as e:
        logger.error(f"خطا در ارسال پیام به ادمین: {e}")
        await bot.send_message(ADMIN_ID_INT, admin_text, parse_mode=ParseMode.HTML, reply_markup=admin_kb)
    
    if lang == "fa":
        await message.reply("✅ پیام شما ارسال شد. منتظر پاسخ باشید.")
    else:
        await message.reply("✅ Message sent. Wait for reply.")
@dp.callback_query(F.data.startswith("feedback_"))
async def handle_feedback(callback: CallbackQuery):
    parts = callback.data.split("_")
    rating = parts[1]
    order_id = int(parts[2]) if len(parts) > 2 else 0
    user_id = callback.from_user.id
    lang = get_user(user_id).get('lang', 'fa')
    
    
    
    logger.info(f"کاربر {user_id} بازخورد {rating} برای سفارش #{order_id} ثبت کرد")
    
    if rating == "nocomment":
        await save_feedback(user_id, order_id, "بدون نظر" if lang == 'fa' else "No comment", "")
        if lang == "fa":
            await callback.message.edit_text(f"{premium_emoji('success', '✅')} از بازخورد شما متشکریم!", reply_markup=get_back_only_keyboard(lang))
        else:
            await callback.message.edit_text(f"{premium_emoji('success', '✅')} Thank you for your feedback!", reply_markup=get_back_only_keyboard(lang))
        try:
            await callback.answer()
        except Exception as e:
            logger.warning(f"خطا در callback.answer: {e}")
        return
    
    rating_map_fa = {"good": "😊 عالی", "medium": "😐 متوسط", "bad": "😞 بد"}
    rating_map_en = {"good": "😊 Excellent", "medium": "😐 Average", "bad": "😞 Bad"}
    rating_text = rating_map_fa.get(rating, "بدون نظر") if lang == 'fa' else rating_map_en.get(rating, "No comment")
    if log_system:
        await log_system.log_feedback(user_id, order_id, rating_text)
    fid = len(feedbacks) + 1
    feedbacks[str(fid)] = {
        'id': fid,
        'user_id': user_id,
        'order_id': order_id,
        'rating': rating,
        'comment': '',
        'date': datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    }
    save_all()
    chat_id = create_chat(user_id, fid)
    try:
        user = get_user(user_id)
        user_name_escaped = html.escape(user.get('name', 'کاربر'))
        await bot.send_message(
            ADMIN_ID_INT,
            f"📝 <b>بازخورد جدید</b>\n\n"
            f"👤 {user_name_escaped} (ID: {user_id})\n"
            f"⭐ {rating_text}\n"
            f"🆔 چت: #{chat_id}\n\n"
            f"برای پاسخ از پنل ادمین اقدام کنید.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="💬 پاسخ", callback_data=f"admin_chat_{chat_id}")]
            ])
        )
    except:
        pass
    
    if lang == "fa":
        await callback.message.edit_text(
            f"{premium_emoji('star', '⭐')} امتیاز شما: {rating_text}\n\n"
            f"💬 می‌توانید پیام خود را بنویسید تا پشتیبانی پاسخ دهد.\n"
            f"برای اتمام گفتگو از /end استفاده کنید.",
            reply_markup=get_back_only_keyboard(lang)
        )
    else:
        await callback.message.edit_text(
            f"{premium_emoji('star', '⭐')} Your rating: {rating_text}\n\n"
            f"💬 Write your message and support will reply.\n"
            f"Use /end to finish the conversation.",
            reply_markup=get_back_only_keyboard(lang)
        )
    user_states[user_id] = {'awaiting_chat': True, 'chat_id': chat_id,'timestamp': datetime.now().isoformat()}
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")

@dp.message(lambda m: user_states.get(m.from_user.id, {}).get('awaiting_feedback_comment'))
async def handle_feedback_comment(message: Message):
    user_id = message.from_user.id
    if await block_unauthorized(message, message.from_user.id):
        return

    
    lang = get_user(user_id).get('lang', 'fa')
    state = user_states.get(user_id, {})
