async def xui_delete_client(email: str) -> bool:
    """حذف کلاینت از پنل 3X-UI"""
    cookie = await xui_login()
    if not cookie:
        return False
    
    try:
        connector = aiohttp.TCPConnector(ssl=False)
        
        async with aiohttp.ClientSession(connector=connector) as session:
            csrf = await xui_get_csrf_token(session)
            headers = {"X-CSRF-Token": csrf} if csrf else {}
            
            async with session.post(
                f"{SENAI_PANEL_URL}/panel/api/clients/del/{email}",
                cookies={"3x-ui": cookie},
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as response:
                if response.status == 200:
                    data = await response.json()
                    if data.get("success"):
                        logger.info(f"✅ کلاینت {email} از پنل حذف شد")
                        return True
                logger.error(f"❌ خطا در حذف کلاینت {email}: {response.status}")
                return False
    except Exception as e:
        logger.error(f"❌ خطا در حذف کلاینت {email}: {e}")
        return False
    
    



    
    

