@dp.callback_query(F.data.startswith("close_chat_"))
async def admin_close_chat(callback: CallbackQuery):
    """بستن چت توسط ادمین"""
    if callback.from_user.id != ADMIN_ID_INT:
        return
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    chat_id = int(callback.data.split("_")[2])
    
    chat = chats.get(str(chat_id))
    
    if log_system and chat:
        await log_system.log_chat_closed(chat_id, chat.get('user_id'), "admin")
    
    close_chat(chat_id, closed_by="admin")
    if chat and chat.get('user_id') in user_states:
        user_states.pop(chat['user_id'], None)
    if callback.from_user.id in user_states:
        user_states.pop(callback.from_user.id, None)
    if chat:
        try:
            user_lang = get_user(chat['user_id']).get('lang', 'fa')
            await bot.send_message(
                chat['user_id'],
                "🔒 گفتگو توسط پشتیبانی بسته شد." if user_lang == "fa" else "🔒 Conversation closed by support."
            )
        except:
            pass
    
    if lang == "fa":
        await callback.message.edit_text(f"✅ چت #{chat_id} بسته شد", reply_markup=get_admin_keyboard(lang))
    else:
        await callback.message.edit_text(f"✅ Chat #{chat_id} closed", reply_markup=get_admin_keyboard(lang))
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")

