@dp.message(F.text)
async def handle_text_messages(message: Message):
    """هندلر یکپارچه برای تمام پیام‌های متنی"""
    
    user_id = message.from_user.id
    user_state = user_states.get(user_id, {})
    lang = get_user(user_id).get('lang', 'fa')
    CustomLogger.log_event('MESSAGE', f'پیام: {message.text[:50]}', user_id)
    if user_state.get('ai_chat_mode'):
        await process_ai_chat_message(message)
        return
    if user_state.get('awaiting_receipt'):
        await message.reply(
            "📸 لطفاً <b>تصویر فیش</b> را ارسال کنید، نه متن\n"
            "برای انصراف از دکمه زیر استفاده کنید",
            reply_markup=get_cancel_inline_keyboard(lang),
            parse_mode=ParseMode.HTML
        )
        return
    if user_state.get('awaiting_amount'):
        await process_balance_amount(message)
        return
    if user_state.get('awaiting_chat'):
        await handle_chat_message(message)
        return
    if user_state.get('awaiting_feedback_comment'):
        await handle_feedback_comment(message)
        return
    if await block_unauthorized(message, user_id):
        return
    if user_id == ADMIN_ID_INT:
        await handle_admin_special_states(message, user_state)
        return
    if AUTO_AI_RESPONSE and (gemini_client or openrouter_client):  # بررسی هر دو سرویس
        if is_ai_question(message.text) and len(message.text.strip()) >= 5:
            can_use, remaining, limit_msg = check_ai_limit(user_id)
            if can_use:
                logger.info(f"🤖 پاسخ خودکار AI به سوال کاربر {user_id}")
                await auto_ai_response(message)
                return
    logger.debug(f"پیام بدون وضعیت از کاربر {user_id}: {message.text[:50]}")
async def get_ai_response(message_text: str, user_id: int = None, username: str = None) -> str:
    """دریافت پاسخ کامل از AI - با تلاش مجدد در صورت ناقص بودن"""
    if gemini_client:
        try:
            logger.info(f"🎯 استفاده از Gemini: {message_text[:50]}...")
            max_tokens = 1500
            full_message = ""
            if user_id and conversation_memory.has_history(user_id):
                history = conversation_memory.get_context(user_id, max_messages=3)
                full_message += f"{history}\n\n"
            if user_id:
                user_info = get_user(user_id) if 'get_user' in globals() else {}
                user_name = user_info.get('name', 'کاربر') if user_info else username or f"کاربر_{user_id}"
                full_message += f"کاربر {user_name}: {message_text}"
            else:
                full_message += f"کاربر: {message_text}"
            payload = {
                "system_instruction": {
                    "parts": [{"text": GEMINI_SYSTEM_PROMPT}]
                },
                "contents": [{
                    "parts": [{"text": full_message}]
                }],
                "generationConfig": {
                    "temperature": GEMINI_TEMPERATURE,
                    "maxOutputTokens": max_tokens,
                    "topP": 0.95,
                    "topK": 40
                }
            }
            
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent?key={GEMINI_API_KEY}"
            
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    url,
                    json=payload,
                    timeout=aiohttp.ClientTimeout(total=45)
                ) as response:
                    
                    if response.status == 200:
                        data = await response.json()
                        candidates = data.get('candidates', [])
                        
                        if candidates:
                            finish_reason = candidates[0].get('finishReason', '')
                            reply = candidates[0].get('content', {}).get('parts', [{}])[0].get('text', '')
                            
                            if reply:
                                reply = reply.strip()
                                import re
                                patterns_to_remove = [
                                    r'\*Iterative refinement\*:?',
                                    r'I\'ll help you with that\.?',
                                    r'Here\'s what I can tell you:?',
                                    r'Let me explain:?',
                                    r'Based on my knowledge:?',
                                    r'Here\'s my response:?',
                                    r'^Thought:?',
                                    r'^Reflection:?',
                                    r'^Analysis:?',
                                    r'^Sure,?',
                                    r'^Of course,?',
                                    r'^Absolutely,?',
                                    r'^Okay,?',
                                ]
                                for pattern in patterns_to_remove:
                                    reply = re.sub(pattern, '', reply, flags=re.IGNORECASE | re.MULTILINE)
                                
                                lines = [line.strip() for line in reply.split('\n') if line.strip()]
                                reply = '\n'.join(lines)
                                
                                if not reply:
                                    return "❌ متأسفانه نتوانستم پاسخ مناسبی پیدا کنم."
                                if finish_reason == 'MAX_TOKENS':
                                    logger.warning(f"⚠️ پاسخ ناقص است (MAX_TOKENS)، تلاش مجدد با توکن بیشتر...")
                                    payload2 = {
                                        "system_instruction": {
                                            "parts": [{"text": GEMINI_SYSTEM_PROMPT}]
                                        },
                                        "contents": [{
                                            "parts": [{"text": full_message}]
                                        }],
                                        "generationConfig": {
                                            "temperature": GEMINI_TEMPERATURE,
                                            "maxOutputTokens": 2500,  # افزایش توکن
                                            "topP": 0.95,
                                            "topK": 40
                                        }
                                    }
                                    
                                    try:
                                        async with session.post(
                                            url,
                                            json=payload2,
                                            timeout=aiohttp.ClientTimeout(total=45)
                                        ) as response2:
                                            
                                            if response2.status == 200:
                                                data2 = await response2.json()
                                                candidates2 = data2.get('candidates', [])
                                                
                                                if candidates2:
                                                    finish_reason2 = candidates2[0].get('finishReason', '')
                                                    reply2 = candidates2[0].get('content', {}).get('parts', [{}])[0].get('text', '')
                                                    
                                                    if reply2:
                                                        reply2 = reply2.strip()
                                                        for pattern in patterns_to_remove:
                                                            reply2 = re.sub(pattern, '', reply2, flags=re.IGNORECASE | re.MULTILINE)
                                                        
                                                        lines2 = [line.strip() for line in reply2.split('\n') if line.strip()]
                                                        reply2 = '\n'.join(lines2)
                                                        
                                                        if reply2 and len(reply2) > len(reply):
                                                            reply = reply2
                                                            finish_reason = finish_reason2
                                                            logger.info(f"✅ پاسخ کامل‌تر دریافت شد - طول: {len(reply)} - finishReason: {finish_reason}")
                                                    else:
                                                        logger.warning("⚠️ پاسخ دوم خالی بود، استفاده از پاسخ اول")
                                                else:
                                                    logger.warning("⚠️ پاسخ دوم نامعتبر بود، استفاده از پاسخ اول")
                                            else:
                                                logger.warning(f"⚠️ درخواست دوم ناموفق: {response2.status}")
                                    except Exception as e2:
                                        logger.error(f"❌ خطا در درخواست دوم: {e2}")
                                    if finish_reason == 'MAX_TOKENS':
                                        reply += "\n\n⚠️ پاسخ کامل نشد. لطفاً سوال خود را کوتاه‌تر بپرسید."
                                if user_id:
                                    conversation_memory.add_message(user_id, 'user', message_text)
                                    conversation_memory.add_message(user_id, 'assistant', reply)
                                
                                logger.info(f"✅ پاسخ Gemini دریافت شد - طول: {len(reply)} کاراکتر - finishReason: {finish_reason}")
                                return reply
                            
                            return "❌ متأسفانه نتوانستم پاسخ مناسبی پیدا کنم."
                        
                        return "❌ متأسفانه نتوانستم پاسخ مناسبی پیدا کنم."
                    elif response.status == 429:
                        logger.warning("⚠️ Gemini Rate Limit")
                        return "⚠️ محدودیت درخواست. لطفاً چند لحظه صبر کنید."
                    
                    elif response.status == 403:
                        logger.error("❌ Gemini 403 - کلید نامعتبر")
                        return "❌ خطای احراز هویت. لطفاً کلید API را بررسی کنید."
                    
                    elif response.status == 503:
                        logger.warning("⚠️ Gemini 503 - سرویس در دسترس نیست")
                        return "⚠️ سرویس شلوغ است. لطفاً چند لحظه صبر کنید."
                    
                    else:
                        error_text = await response.text()
                        logger.error(f"❌ Gemini Error: {response.status} - {error_text[:200]}")
                        return f"❌ خطا در ارتباط با هوش مصنوعی. کد: {response.status}"
                        
        except asyncio.TimeoutError:
            logger.error("⏰ تایم‌اوت در Gemini")
            return "⏰ زمان پاسخگویی به پایان رسید. لطفاً دوباره تلاش کنید."
            
        except aiohttp.ClientError as e:
            logger.error(f"🌐 خطای شبکه در Gemini: {e}")
            return f"❌ خطای شبکه: {str(e)[:100]}"
            
        except Exception as e:
            logger.error(f"❌ خطای غیرمنتظره در Gemini: {e}")
            import traceback
            traceback.print_exc()
            return f"❌ خطا: {str(e)[:100]}"
    
    return "❌ متأسفانه هیچ سرویس هوش مصنوعی در دسترس نیست. لطفاً بعداً تلاش کنید."

def detect_question_topic(text: str) -> str:
    """تشخیص موضوع سوال کاربر"""
    text_lower = text.lower()
    topics = {
        'price': ['قیمت', 'چنده', 'چقدر', 'تومان', 'هزینه', 'ارزان', 'گران'],
        'install': ['نصب', 'راه‌اندازی', 'نحوه', 'چجوری', 'چطور', 'آموزش', 'نرم‌افزار', 'برنامه'],
        'support': ['پشتیبانی', 'تماس', 'مشکل', 'خطا', 'ارور', 'قطعی', 'قطع'],
        'speed': ['سرعت', 'اینترنت', 'مگابیت', 'دانلود', 'آپلود'],
        'device': ['لپتاپ', 'کامپیوتر', 'ویندوز', 'مک', 'اندروید', 'آیفون', 'موبایل']
    }
    
    for topic, keywords in topics.items():
        if any(kw in text_lower for kw in keywords):
            return topic
    
    return 'general'

async def get_openrouter_response(message_text: str, user_id: int = None, username: str = None) -> str:
    """دریافت پاسخ از OpenRouter با درخواست پاسخ کامل"""
    
    if not openrouter_client:
        return "❌ سرویس پشتیبان در دسترس نیست."
    
    try:
        logger.info(f"🎯 OpenRouter: {message_text[:50]}...")
        messages = [
            {"role": "system", "content": OPENROUTER_SYSTEM_PROMPT}
        ]
        if user_id and conversation_memory.has_history(user_id):
            history = conversation_memory.get_history(user_id, max_messages=6)
            for msg in history:
                role = "user" if msg['role'] == 'user' else "assistant"
                messages.append({"role": role, "content": msg['content']})
        if user_id:
            user_info = get_user(user_id) if 'get_user' in globals() else {}
            user_name = user_info.get('name', 'کاربر') if user_info else username or f"کاربر_{user_id}"
            messages.append({"role": "user", "content": f"کاربر {user_name}: {message_text}"})
        else:
            messages.append({"role": "user", "content": message_text})
        model = openrouter_client.default_model
        if not model:
            test_result = await openrouter_client.test_connection()
            if test_result.get('success') and test_result.get('default_model'):
                model = test_result['default_model']
                openrouter_client.default_model = model
            else:
                return "❌ هیچ مدلی در OpenRouter در دسترس نیست."
        async with aiohttp.ClientSession() as session:
            async with session.post(
                f"{OPENROUTER_BASE_URL}/chat/completions",
                headers=openrouter_client.headers,
                json={
                    "model": model,
                    "messages": messages,
                    "temperature": OPENROUTER_TEMPERATURE,
                    "max_tokens": OPENROUTER_MAX_TOKENS,
                    "top_p": OPENROUTER_TOP_P
                },
                timeout=aiohttp.ClientTimeout(total=45)
            ) as response:
                
                if response.status == 200:
                    data = await response.json()
                    reply = data.get('choices', [{}])[0].get('message', {}).get('content', '')
                    
                    if reply:
                        reply = reply.strip()
                        reply = '\n'.join([line for line in reply.split('\n') if line.strip()])
                        if user_id:
                            conversation_memory.add_message(user_id, 'user', message_text)
                            conversation_memory.add_message(user_id, 'assistant', reply)
                        
                        logger.info(f"✅ OpenRouter پاسخ داد - طول: {len(reply)} کاراکتر")
                        return reply
                    else:
                        return "❌ متأسفانه نتوانستم پاسخ مناسبی پیدا کنم."
                
                elif response.status == 429:
                    logger.warning("⚠️ OpenRouter Rate Limit")
                    await asyncio.sleep(3)
                    return "⚠️ محدودیت درخواست در سرویس پشتیبان. لطفاً چند لحظه صبر کنید."
                
                elif response.status == 404:
                    logger.warning(f"⚠️ مدل {model} در OpenRouter موجود نیست")
                    for backup_model in OPENROUTER_MODELS:
                        if backup_model != model:
                            logger.info(f"🔄 تلاش با مدل {backup_model}...")
                            openrouter_client.default_model = backup_model
                            return await get_openrouter_response(message_text, user_id, username)
                    return "❌ هیچ مدل معتبری در OpenRouter یافت نشد."
                
                else:
                    error_text = await response.text()
                    logger.error(f"❌ OpenRouter Error: {response.status} - {error_text[:200]}")
                    return f"❌ خطا در سرویس پشتیبان. کد: {response.status}"
                    
    except asyncio.TimeoutError:
        logger.error("⏰ تایم‌اوت در OpenRouter")
        return "⏰ زمان پاسخگویی به پایان رسید. لطفاً دوباره تلاش کنید."
        
    except aiohttp.ClientError as e:
        logger.error(f"🌐 خطای شبکه در OpenRouter: {e}")
        return f"❌ خطای شبکه در سرویس پشتیبان: {str(e)[:100]}"
        
    except Exception as e:
        logger.error(f"❌ خطا در OpenRouter: {e}")
        return f"❌ خطا: {str(e)[:100]}"
    
