@dp.message(Command("reset_ai_limit"))
async def cmd_reset_ai_limit(message: Message):
    """ریست محدودیت AI یک کاربر خاص (فقط ادمین)"""
    if message.from_user.id != ADMIN_ID_INT:
        return
    
    parts = message.text.split()
    if len(parts) < 2:
        await message.reply(
            "📊 <b>ریست محدودیت AI</b>\n\n"
            "استفاده:\n"
            "<code>/reset_ai_limit 123456789</code>\n\n"
            "برای ریست محدودیت خودت:\n"
            "<code>/reset_ai_limit me</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    target = parts[1]
    if target == "me":
        target_id = message.from_user.id
    else:
        try:
            target_id = int(target)
        except:
            await message.reply("❌ آیدی نامعتبر")
            return
    
    if target_id in user_ai_requests:
        del user_ai_requests[target_id]
        await message.reply(f"✅ محدودیت AI کاربر {target_id} ریست شد!")
    else:
        await message.reply(f"ℹ️ کاربر {target_id} هیچ سوالی نپرسیده بود.")
        
        
async def process_ai_chat_message(message: Message):
    """پردازش پیام در حالت چت با AI"""
    user_id = message.from_user.id
    lang = get_user(user_id).get('lang', 'fa')
    
    logger.info(f"🤖 پردازش پیام AI از کاربر {user_id}: {message.text[:50]}...")
    
    if message.text.strip() == '/cancel':
        user_state = user_states.get(user_id, {})
        coupon_code = user_state.get('coupon_code')
        coupon_discount = user_state.get('coupon_discount')
        coupon_applied = user_state.get('coupon_applied', False)
        user_states.pop(user_id, None)
        if coupon_applied and coupon_code:
            user_states[user_id] = {
                'coupon_code': coupon_code,
                'coupon_discount': coupon_discount,
                'coupon_applied': True
            }
            logger.info(f"🏷️ [process_ai_chat_message] کوپن {coupon_code} حفظ شد")
        
        coupon_message = ""
        if coupon_applied and coupon_code:
            coupon_message = f"\n\n🏷️ کوپن شما ({coupon_code}) همچنان معتبر است."
        
        await message.reply(
            f"✅ از چت AI خارج شدید.{coupon_message}" if lang == "fa" else f"✅ Exited AI chat.{coupon_message}",
            reply_markup=get_main_keyboard(user_id == ADMIN_ID_INT, lang)
        )
        return
    
    
    if not gemini_client:
        await message.reply(
            "❌ هوش مصنوعی در حال حاضر در دسترس نیست." if lang == "fa" else "❌ AI is currently unavailable."
        )
        return
    
    daily_limit = GEMINI_DAILY_LIMIT
    
    can_use, remaining, limit_msg = check_ai_limit(user_id)
    if not can_use:
        await message.reply(limit_msg)
        return
    
    processing_msg = await message.reply("⏳ در حال پردازش سوال شما..." if lang == "fa" else "⏳ Processing your question...")
    
    try:
        answer = await asyncio.wait_for(
            get_ai_response(message.text, user_id, message.from_user.username),
            timeout=90  # افزایش به 90 ثانیه برای پاسخ کامل
        )
        error_keywords = ["❌", "⚠️", "خطا", "متأسفانه", "در دسترس نیست", "شلوغ است", "Error"]
        warning_keywords = ["پاسخ کامل نشد", "کوتاه‌تر بپرسید"]
        
        is_real_error = any(kw in answer for kw in error_keywords) and not any(kw in answer for kw in warning_keywords)
        is_incomplete = any(kw in answer for kw in warning_keywords)
        
        if is_real_error:
            logger.warning(f"⚠️ پاسخ خطا بود، محدودیت کاهش نیافت: {answer[:50]}...")
            await processing_msg.edit_text(
                f"{answer}\n\n💡 محدودیت شما کاهش نیافت. لطفاً دوباره تلاش کنید." if lang == "fa" else f"{answer}\n\n💡 Your limit was not reduced. Please try again.",
                parse_mode=ParseMode.HTML
            )
            return
        
        if is_incomplete:
            logger.warning(f"⚠️ پاسخ ناقص است، محدودیت کاهش نیافت")
            await processing_msg.edit_text(
                "⚠️ پاسخ کامل نشد. لطفاً سوال خود را کوتاه‌تر بپرسید.\n\n💡 محدودیت شما کاهش نیافت." if lang == "fa" else "⚠️ Response was incomplete. Please ask a shorter question.\n\n💡 Your limit was not reduced.",
                parse_mode=ParseMode.HTML
            )
            return
        increment_ai_usage(user_id)
        lines = [line.strip() for line in answer.split('\n') if line.strip()]
        formatted_answer = '\n'.join(lines)
        
        remaining_display = max(0, remaining - 1)
        
        response_text = f"""
{premium_emoji('robot','🤖')} <b>پاسخ هوش مصنوعی:</b>

{formatted_answer}

━━━━━━━━━━━━━━━━━━━
{premium_emoji('star', '📊')} سوالات باقیمانده امروز: {remaining_display}/{daily_limit}
{premium_emoji('light','💡')} سوال بعدی خود را بپرسید...
❌ برای خروج /cancel را ارسال کنید.
"""
        
        await processing_msg.edit_text(
            response_text,
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="🧹 پاک کردن حافظه" if lang == "fa" else "🧹 Clear Memory", callback_data="clear_ai_memory")],
                [InlineKeyboardButton(text="❌ خروج از چت" if lang == "fa" else "❌ Exit Chat", callback_data="exit_ai_chat", style="danger")]
            ])
        )
        
        logger.info(f"✅ پاسخ کامل AI برای کاربر {user_id} ارسال شد - طول: {len(answer)} کاراکتر")
        
    except asyncio.TimeoutError:
        logger.error(f"⏰ تایم‌اوت در AI Chat برای کاربر {user_id}")
        await processing_msg.edit_text(
            "⏰ زمان پاسخگویی به پایان رسید. لطفاً سوال خود را کوتاه‌تر بپرسید یا دوباره تلاش کنید.\n\n💡 محدودیت شما کاهش نیافت." if lang == "fa" else "⏰ Response timeout. Please ask a shorter question or try again.\n\n💡 Your limit was not reduced.",
            parse_mode=ParseMode.HTML
        )
        
    except Exception as e:
        logger.error(f"❌ خطا در AI Chat: {e}", exc_info=True)
        await processing_msg.edit_text(
            "❌ خطا در پردازش. لطفاً بعداً تلاش کنید.\n\n💡 محدودیت شما کاهش نیافت." if lang == "fa" else "❌ Error. Please try again later.\n\n💡 Your limit was not reduced.",
            parse_mode=ParseMode.HTML
        )
        
