async def process_balance_amount(message: Message):
    """پردازش مبلغ شارژ حساب"""
    user_id = message.from_user.id
    lang = get_user(user_id).get('lang', 'fa')
    
    settings = configs_pool.get('price_settings', {})
    min_charge = settings.get('min_charge', 10000)
    max_charge = settings.get('max_charge', 5000000)
    user_state = user_states.get(user_id, {})
    coupon_code = user_state.get('coupon_code')
    coupon_discount = user_state.get('coupon_discount')
    coupon_applied = user_state.get('coupon_applied', False)
    
    logger.info(f"🔍 [process_balance_amount] کوپن قبل: code={coupon_code}, applied={coupon_applied}")
    cancel_text = "❌ انصراف" if lang == "fa" else "❌ Cancel"
    if message.text == cancel_text:
        if user_id in user_states:
            user_states.pop(user_id, None)
        if coupon_applied and coupon_code:
            user_states[user_id] = {
                'coupon_code': coupon_code,
                'coupon_discount': coupon_discount,
                'coupon_applied': True
            }
            logger.info(f"🏷️ [process_balance_amount] کوپن {coupon_code} حفظ شد")
        
        await message.reply("❌ عملیات لغو شد" if lang == "fa" else "❌ Operation cancelled", reply_markup=ReplyKeyboardRemove())
        is_admin = (user_id == ADMIN_ID_INT)
        
        coupon_message = ""
        if coupon_applied and coupon_code:
            coupon_message = f"\n\n{premium_emoji('gift', '🏷️')} کوپن شما ({coupon_code}) همچنان معتبر است."
        
        await message.answer(
            f"{premium_emoji('rocket', '🚀')} {'منوی اصلی' if lang=='fa' else 'Main Menu'}{coupon_message}",
            reply_markup=get_main_keyboard(is_admin, lang)
        )
        return
    
    try:
        amount = int(message.text.replace(',', '').replace('،', '').replace(' ', '').strip())
        
        if min_charge <= amount <= max_charge:
            if user_id in user_states:
                user_states.pop(user_id, None)
            if coupon_applied and coupon_code:
                user_states[user_id] = {
                    'coupon_code': coupon_code,
                    'coupon_discount': coupon_discount,
                    'coupon_applied': True
                }
                logger.info(f"🏷️ [process_balance_amount] کوپن {coupon_code} حفظ شد")
            
            order_id = create_balance_order(user_id, amount)
            
            card_num = ' '.join([BANK_CARD_NUMBER[i:i+4] for i in range(0, 16, 4)])
            if lang == "fa":
                text = f"""
{premium_emoji('card', '💳')} <b>پرداخت برای شارژ حساب</b>

{premium_emoji('id', '🆔')} <b>شماره پیگیری:</b> #{order_id}
{premium_emoji('money', '💰')} <b>مبلغ:</b> {amount:,} تومان

{premium_emoji('card', '💳')} <b>شماره کارت:</b>
<code>{card_num}</code>

{premium_emoji('user', '👤')} <b>به نام:</b> {BANK_CARD_HOLDER}
{premium_emoji('star', '🏦')} <b>بانک:</b> {BANK_NAME}

{premium_emoji('receipt', '📸')} لطفاً تصویر فیش واریزی را ارسال کنید
"""
            else:
                text = f"""
{premium_emoji('card', '💳')} <b>Balance Top-up Payment</b>

{premium_emoji('id', '🆔')} <b>Order Number:</b> #{order_id}
{premium_emoji('money', '💰')} <b>Amount:</b> {amount:,} Toman

{premium_emoji('card', '💳')} <b>Card Number:</b>
<code>{card_num}</code>

{premium_emoji('user', '👤')} <b>Account Holder:</b> {BANK_CARD_HOLDER}
{premium_emoji('star', '🏦')} <b>Bank:</b> {BANK_NAME}

{premium_emoji('receipt', '📸')} Please send the receipt photo
"""
            
            keyboard = InlineKeyboardMarkup(inline_keyboard=[
                [
                    InlineKeyboardButton(
                        text=f"📸 {'ارسال فیش' if lang=='fa' else 'Send Receipt'}", 
                        callback_data=f"send_receipt_{order_id}", 
                        style="primary"
                    ),
                    InlineKeyboardButton(
                        text=f"❌ {'انصراف' if lang=='fa' else 'Cancel'}", 
                        callback_data=f"cancel_order_{order_id}", 
                        style="danger"
                    )
                ]
            ])
            
            await message.answer(text, parse_mode=ParseMode.HTML, reply_markup=keyboard)
            user_states[user_id] = {
                'awaiting_receipt': True,
                'current_order_id': order_id,
                'timestamp': datetime.now().isoformat()
            }
            
            if coupon_applied and coupon_code:
                user_states[user_id]['coupon_code'] = coupon_code
                user_states[user_id]['coupon_applied'] = True
                user_states[user_id]['coupon_discount'] = coupon_discount
                logger.info(f"🏷️ [process_balance_amount] کوپن {coupon_code} در user_states ذخیره شد")
            
        else:
            keyboard = InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(
                    text=f"❌ {'انصراف از شارژ' if lang=='fa' else 'Cancel Charge'}",
                    callback_data="cancel_increase_balance",
                    style="danger"
                )]
            ])
            
            if lang == "fa":
                await message.reply(
                    f"{premium_emoji('danger', '❌')} مبلغ باید بین {min_charge:,} تا {max_charge:,} تومان باشد\n\n"
                    f"{premium_emoji('note', '📝')} لطفاً مجدداً مبلغ را وارد کنید:",
                    reply_markup=keyboard,
                    parse_mode=ParseMode.HTML
                )
            else:
                await message.reply(
                    f"{premium_emoji('danger', '❌')} Amount must be between {min_charge:,} and {max_charge:,} Toman\n\n"
                    f"{premium_emoji('note', '📝')} Please enter the amount again:",
                    reply_markup=keyboard,
                    parse_mode=ParseMode.HTML
                )
            
    except ValueError:
        keyboard = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(
                text=f"❌ {'انصراف از شارژ' if lang=='fa' else 'Cancel Charge'}",
                callback_data="cancel_increase_balance",
                style="danger"
            )]
        ])
        
        if lang == "fa":
            await message.reply(
                f"❌ لطفاً یک عدد معتبر وارد کنید\n\n"
                f"{premium_emoji('note', '📝')} مثال: 50000",
                reply_markup=keyboard,
                parse_mode=ParseMode.HTML
            )
        else:
            await message.reply(
                f"❌ Please enter a valid number\n\n"
                f"{premium_emoji('note', '📝')} Example: 50000",
                reply_markup=keyboard,
                parse_mode=ParseMode.HTML
            )

