@dp.callback_query(F.data == "admin_manage_backups")
async def admin_manage_backups(callback: CallbackQuery):
    """مدیریت بکاپ‌ها (حذف بکاپ‌های قدیمی و پاکسازی کامل)"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    backups = get_backup_list()
    full_backups = [b for b in backups if b.get('type') == 'full_backup']
    before_restore = [b for b in backups if b.get('type') == 'before_restore']
    auto_backups = [b for b in backups if b.get('type') == 'auto_backup']
    
    total_size = sum(b['size'] for b in backups)
    total_size_str = format_size(total_size)
    
    if lang == "fa":
        text = f"🗑 <b>مدیریت بکاپ‌ها</b>\n\n"
        text += f"📊 <b>آمار بکاپ‌ها:</b>\n"
        text += f"• 📦 بکاپ کامل (full_backup): {len(full_backups)}\n"
        text += f"• 🔄 بکاپ قبل از ریستور (before_restore): {len(before_restore)}\n"
        text += f"• 🤖 بکاپ خودکار (auto_backup): {len(auto_backups)}\n"
        text += f"💾 حجم کل: {total_size_str}\n\n"
        
        if backups:
            text += "📋 <b>بکاپ‌های موجود (۱۰ تای آخر):</b>\n"
            for backup in backups[:10]:
                date_str = backup['date'].strftime('%Y-%m-%d %H:%M')
                size_str = format_size(backup['size'])
                type_icon = {
                    'full_backup': '📦',
                    'before_restore': '🔄',
                    'auto_backup': '🤖'
                }.get(backup.get('type'), '📄')
                text += f"{type_icon} {date_str} - {size_str} - {backup['filename']}\n"
            if len(backups) > 10:
                text += f"• ... و {len(backups) - 10} بکاپ دیگر\n"
        else:
            text += "⚠️ <b>هیچ بکاپی یافت نشد!</b>\n\n"
            text += "💡 نکات:\n"
            text += "• از دکمه «💾 بکاپ» برای ایجاد بکاپ استفاده کنید\n"
        
        text += "\n🔽 لطفاً عملیات مورد نظر را انتخاب کنید:"
        
        buttons = [
            [InlineKeyboardButton(text="🗑 حذف همه بکاپ‌ها", callback_data="delete_all_backups_confirm", style="danger")],
            [InlineKeyboardButton(text="🗑 حذف بکاپ‌های قبل از ریستور (>7 روز)", callback_data="delete_old_before_restore")],
            [InlineKeyboardButton(text="🗑 حذف بکاپ‌های قدیمی (>30 روز)", callback_data="delete_old_backups")],
            [InlineKeyboardButton(text="📋 مشاهده همه بکاپ‌ها", callback_data="list_all_backups")],
            [InlineKeyboardButton(text="🔙 برگشت به پنل", callback_data="admin_panel")]
        ]
    else:
        text = f"🗑 <b>Backup Manager</b>\n\n"
        text += f"📊 <b>Backup Statistics:</b>\n"
        text += f"• 📦 Full backups: {len(full_backups)}\n"
        text += f"• 🔄 Before restore backups: {len(before_restore)}\n"
        text += f"• 🤖 Auto backups: {len(auto_backups)}\n"
        text += f"💾 Total size: {total_size_str}\n\n"
        
        if backups:
            text += "📋 <b>Recent backups (last 10):</b>\n"
            for backup in backups[:10]:
                date_str = backup['date'].strftime('%Y-%m-%d %H:%M')
                size_str = format_size(backup['size'])
                type_icon = {
                    'full_backup': '📦',
                    'before_restore': '🔄',
                    'auto_backup': '🤖'
                }.get(backup.get('type'), '📄')
                text += f"{type_icon} {date_str} - {size_str} - {backup['filename']}\n"
            if len(backups) > 10:
                text += f"• ... and {len(backups) - 10} more\n"
        else:
            text += "⚠️ <b>No backups found!</b>\n\n"
            text += "💡 Tips:\n"
            text += "• Use the '💾 Backup' button to create a backup\n"
        
        text += "\n🔽 Select an operation:"
        
        buttons = [
            [InlineKeyboardButton(text="🗑 Delete All Backups", callback_data="delete_all_backups_confirm", style="danger")],
            [InlineKeyboardButton(text="🗑 Delete Old Before Restore (>7 days)", callback_data="delete_old_before_restore")],
            [InlineKeyboardButton(text="🗑 Delete Old Backups (>30 days)", callback_data="delete_old_backups")],
            [InlineKeyboardButton(text="📋 List All Backups", callback_data="list_all_backups")],
            [InlineKeyboardButton(text="🔙 Back to Panel", callback_data="admin_panel")]
        ]
    
    await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")


