@dp.callback_query(F.data == "delete_all_backups_execute")
async def admin_delete_all_backups_execute(callback: CallbackQuery):
    """اجرای حذف همه بکاپ‌ها"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    backups = get_backup_list()
    
    await callback.message.edit_text("⏳ در حال حذف همه بکاپ‌ها..." if lang=="fa" else "⏳ Deleting all backups...")
    
    deleted_count = 0
    failed_count = 0
    total_freed_size = 0
    
    for backup in backups:
        try:
            size = backup['size']
            os.remove(backup['path'])
            deleted_count += 1
            total_freed_size += size
            logger.info(f"🗑 بکاپ حذف شد: {backup['filename']}")
        except Exception as e:
            failed_count += 1
            logger.error(f"❌ خطا در حذف بکاپ {backup['filename']}: {e}")
    
    total_freed_str = format_size(total_freed_size)
    if log_system:
        await log_system.log_admin_action(
            callback.from_user.id,
            "حذف همه بکاپ‌ها" if lang=="fa" else "Delete all backups",
            details=f"تعداد حذف شده: {deleted_count} | حجم آزاد شده: {total_freed_str}" if lang=="fa" else f"Deleted: {deleted_count} | Freed space: {total_freed_str}"
        )
    
    if lang == "fa":
        text = f"""
✅ <b>عملیات حذف بکاپ‌ها کامل شد!</b>

📊 <b>نتیجه:</b>
• حذف شده: {deleted_count} فایل
• خطا: {failed_count} فایل
• حجم آزاد شده: {total_freed_str}

💾 فضای ذخیره‌سازی آزاد شد.
"""
    else:
        text = f"""
✅ <b>Backup deletion completed!</b>

📊 <b>Result:</b>
• Deleted: {deleted_count} files
• Failed: {failed_count} files
• Freed space: {total_freed_str}

💾 Storage space freed.
"""
    
    buttons = [[InlineKeyboardButton(
        text="🔙 برگشت به پنل" if lang=="fa" else "🔙 Back to Panel",
        callback_data="admin_panel"
    )]]
    
    await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")


