async def admin_delete_single_backup(callback: CallbackQuery):
    """حذف یک بکاپ خاص"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    timestamp = callback.data.replace("delete_single_backup_", "")
    
    backups = get_backup_list()
    backup = None
    for b in backups:
        if b['timestamp'] == timestamp:
            backup = b
            break
    
    if not backup:
        await callback.answer("❌ بکاپ یافت نشد" if lang=="fa" else "❌ Backup not found", show_alert=True)
        return
    
    try:
        size_str = format_size(backup['size'])
        os.remove(backup['path'])
        
        if log_system:
            await log_system.log_admin_action(
                callback.from_user.id,
                "حذف بکاپ تکی" if lang=="fa" else "Delete single backup",
                details=f"فایل: {backup['filename']} | حجم: {size_str}" if lang=="fa" else f"File: {backup['filename']} | Size: {size_str}"
            )
        
        await callback.answer(
            f"✅ بکاپ حذف شد ({size_str})" if lang=="fa" else f"✅ Backup deleted ({size_str})",
            show_alert=True
        )
        await admin_list_all_backups(callback)
        
    except Exception as e:
        await callback.answer(f"❌ خطا: {str(e)[:50]}" if lang=="fa" else f"❌ Error: {str(e)[:50]}", show_alert=True)


@dp.callback_query(F.data == "delete_old_backups")
async def admin_delete_old_backups(callback: CallbackQuery):
    """حذف بکاپ‌های قدیمی (بیشتر از 30 روز)"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    await callback.message.edit_text("⏳ در حال بررسی بکاپ‌های قدیمی...")
    
    backups = get_backup_list()
    cutoff = datetime.now() - timedelta(days=30)
    
    deleted_count = 0
    failed_count = 0
    total_freed_mb = 0
    deleted_files = []
    
    for backup in backups:
        if backup['date'] < cutoff:
            try:
                size_mb = backup['size_mb']
                os.remove(backup['path'])
                deleted_count += 1
                total_freed_mb += size_mb
                deleted_files.append(backup['filename'])
                logger.info(f"🗑 بکاپ قدیمی حذف شد: {backup['filename']}")
            except Exception as e:
                failed_count += 1
                logger.error(f"❌ خطا در حذف بکاپ {backup['filename']}: {e}")
    if log_system:
        await log_system.log_admin_action(
            callback.from_user.id,
            "حذف بکاپ‌های قدیمی",
            details=f"تعداد: {deleted_count} | حجم آزاد شده: {total_freed_mb:.1f} MB"
        )
    
    if lang == "fa":
        text = f"""
✅ <b>حذف بکاپ‌های قدیمی انجام شد!</b>

📊 <b>نتیجه:</b>
• بکاپ‌های حذف شده: {deleted_count}
• خطا: {failed_count}
• حجم آزاد شده: {total_freed_mb:.1f} MB

{f"📋 <b>فایل‌های حذف شده:</b>" if deleted_files else ""}
"""
        for f in deleted_files[:5]:
            text += f"• {f}\n"
        if len(deleted_files) > 5:
            text += f"• ... و {len(deleted_files) - 5} فایل دیگر\n"
    else:
        text = f"""
✅ <b>Old backups deleted!</b>

📊 <b>Result:</b>
• Deleted: {deleted_count}
• Failed: {failed_count}
• Freed space: {total_freed_mb:.1f} MB

{f"📋 <b>Deleted files:</b>" if deleted_files else ""}
"""
        for f in deleted_files[:5]:
            text += f"• {f}\n"
        if len(deleted_files) > 5:
            text += f"• ... and {len(deleted_files) - 5} more\n"
    
    buttons = [[InlineKeyboardButton(
        text="🔙 برگشت به مدیریت" if lang=="fa" else "🔙 Back to Manager",
        callback_data="admin_manage_backups"
    )]]
    
    await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")

