@dp.callback_query(F.data.startswith("request_receipt_"))
async def request_receipt(callback: CallbackQuery):
    """درخواست ارسال فیش از کاربر"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    order_id = int(callback.data.split("_")[2])
    order = orders.get(str(order_id))
    
    if not order:
        await callback.answer("❌ سفارش یافت نشد", show_alert=True)
        return
    
    user_id = order['user_id']
    lang = get_user(user_id).get('lang', 'fa')
    try:
        if lang == "fa":
            await bot.send_message(
                user_id,
                f"📸 <b>درخواست ارسال فیش</b>\n\n"
                f"🆔 سفارش: #{order_id}\n"
                f"💰 مبلغ: {order.get('price', 0):,} تومان\n\n"
                f"لطفاً تصویر فیش واریزی را ارسال کنید.\n"
                f"برای انصراف از دکمه زیر استفاده کنید.",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(
                        text="❌ انصراف از سفارش" if lang == "fa" else "❌ Cancel Order",
                        callback_data=f"cancel_order_{order_id}"
                    )]
                ])
            )
        else:
            await bot.send_message(
                user_id,
                f"📸 <b>Receipt Request</b>\n\n"
                f"🆔 Order: #{order_id}\n"
                f"💰 Amount: {order.get('price', 0):,} Toman\n\n"
                f"Please send the receipt photo.\n"
                f"Use the button below to cancel.",
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(
                        text="❌ Cancel Order",
                        callback_data=f"cancel_order_{order_id}"
                    )]
                ])
            )
        user_states[user_id] = {
            'awaiting_receipt': True,
            'current_order_id': order_id,
            'timestamp': datetime.now().isoformat()
        }
        
        await callback.answer("✅ پیام درخواست فیش ارسال شد" if lang == "fa" else "✅ Receipt request sent")
        
    except Exception as e:
        logger.error(f"خطا در ارسال درخواست فیش به کاربر {user_id}: {e}")
        await callback.answer("❌ خطا در ارسال پیام", show_alert=True)
    await view_order(callback)
    
@dp.callback_query(F.data.startswith("view_receipt_"))
async def view_receipt(callback: CallbackQuery):
    """مشاهده فیش ارسال شده"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    order_id = int(callback.data.split("_")[2])
    order = orders.get(str(order_id))
    
    if not order:
        await callback.answer("❌ سفارش یافت نشد", show_alert=True)
        return
    
    photo_id = order.get('receipt_photo_id')
    if not photo_id:
        await callback.answer("❌ فیشی یافت نشد", show_alert=True)
        return
    
    try:
        await bot.send_photo(
            callback.message.chat.id,
            photo_id,
            caption=f"📸 <b>فیش سفارش #{order_id}</b>",
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(
                    text="🔙 برگشت به سفارش" if get_user(callback.from_user.id).get('lang', 'fa') == "fa" else "🔙 Back to Order",
                    callback_data=f"view_order_{order_id}"
                )]
            ])
        )
        await callback.answer()
    except Exception as e:
        logger.error(f"خطا در ارسال فیش: {e}")
        await callback.answer("❌ خطا در نمایش فیش", show_alert=True)
        
@dp.callback_query(F.data.startswith("cancel_order_admin_"))
async def cancel_order_admin(callback: CallbackQuery):
    """لغو سفارش توسط ادمین - با تاییدیه"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    logger.info(f"🔴 [cancel_order_admin] CALLED: {callback.data}")
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    parts = callback.data.split("_")
    if len(parts) < 4:
        await callback.answer("❌ فرمت کالبک نامعتبر", show_alert=True)
        return
    
    try:
        order_id = int(parts[3])
    except ValueError:
        await callback.answer("❌ خطا در پردازش سفارش", show_alert=True)
        return
    
    order = orders.get(str(order_id))
    if not order:
        await callback.answer("❌ سفارش یافت نشد", show_alert=True)
        return
    
    user_id = order['user_id']
    user_info = get_user(user_id)
    user_name_raw = user_info.get('name', f'کاربر_{user_id}')
    user_name_escaped = html.escape(user_name_raw)
    if lang == "fa":
        text = f"""
⚠️ <b>لغو سفارش #{order_id} توسط ادمین</b>

👤 کاربر: {user_name_escaped} (ID: {user_id})
📦 حجم: {order.get('volume', 0)} GB
⏱ مدت: {order.get('days', 0)} روز
💰 قیمت: {order.get('price', 0):,} تومان
📊 وضعیت: {order.get('status', 'نامشخص')}

آیا از لغو این سفارش اطمینان دارید؟
"""
    else:
        text = f"""
⚠️ <b>Cancel Order #{order_id} by Admin</b>

👤 User: {user_name_escaped} (ID: {user_id})
📦 Volume: {order.get('volume', 0)} GB
⏱ Duration: {order.get('days', 0)} days
💰 Price: {order.get('price', 0):,} Toman
📊 Status: {order.get('status', 'Unknown')}

Are you sure?
"""
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [
            InlineKeyboardButton(
                text="✅ بله، لغو کن" if lang == "fa" else "✅ Yes, cancel",
                callback_data=f"confirm_cancel_order_admin_{order_id}",  # ✅ تغییر کلید برای جلوگیری از تداخل
                style="danger"
            ),
            InlineKeyboardButton(
                text="❌ انصراف" if lang == "fa" else "❌ Cancel",
                callback_data=f"view_order_{order_id}"
            )
        ]
    ])
    try:
        await callback.message.delete()
    except:
        pass
    
    await callback.message.answer(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    
    try:
        await callback.answer()
    except:
        pass

@dp.callback_query(F.data.startswith("confirm_cancel_order_admin_"))
async def confirm_cancel_order_admin(callback: CallbackQuery):
    """تایید نهایی لغو سفارش توسط ادمین"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    logger.info(f"🔴 [confirm_cancel_order_admin] CALLED: {callback.data}")
    parts = callback.data.split("_")
    if len(parts) < 5:
        await callback.answer("❌ فرمت کالبک نامعتبر", show_alert=True)
        return
    
    try:
        order_id = int(parts[4])
    except (ValueError, IndexError):
        await callback.answer("❌ خطا در پردازش سفارش", show_alert=True)
        return
    
    order = orders.get(str(order_id))
    if not order:
        await callback.answer("❌ سفارش یافت نشد", show_alert=True)
        return
    
    user_id = order['user_id']
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    user_info = get_user(user_id)
    user_name_raw = user_info.get('name', f'کاربر_{user_id}')
    user_name_escaped = html.escape(user_name_raw)
    coupon_code = None
    coupon_applied = False
    user_state = user_states.get(user_id, {})
    if user_state.get('coupon_applied'):
        coupon_code = user_state.get('coupon_code')
        coupon_applied = True
    old_status = order.get('status', 'unknown')
    price = order.get('price', 0)
    volume = order.get('volume', 0)
    days = order.get('days', 0)
    order_type = order.get('type', 'purchase')
    should_refund = False
    refund_amount = 0
    if old_status == 'approved':
        should_refund = True
        refund_amount = price
        logger.info(f"💰 سفارش #{order_id} تایید شده بود - برگشت {price:,} تومان")
    
    elif old_status == 'pending':
        should_refund = True
        refund_amount = price
        logger.info(f"💰 سفارش #{order_id} در انتظار تایید (فیش ارسال شده) - برگشت {price:,} تومان")
    
    elif old_status == 'pending_balance_charge':
        should_refund = True
        refund_amount = price
        logger.info(f"💰 سفارش #{order_id} درخواست شارژ - برگشت {price:,} تومان")
    elif old_status == 'awaiting_payment':
        should_refund = False
        refund_amount = 0
        logger.info(f"ℹ️ سفارش #{order_id} در انتظار پرداخت است - هیچ موجودی برگشت داده نمی‌شود")
    update_order(order_id, status='cancelled')
    
    logger.info(f"🗑 سفارش #{order_id} توسط ادمین {callback.from_user.id} لغو شد (وضعیت قبلی: {old_status})")
    if should_refund and refund_amount > 0:
        old_balance = get_user(user_id).get('balance', 0)
        new_balance = add_balance(user_id, refund_amount)
        logger.info(f"💰 موجودی کاربر {user_id} برگشت داده شد: {old_balance} -> {new_balance} ({refund_amount:,} تومان)")
        if log_system:
            await log_system.log_balance_change(
                user_id=user_id,
                amount=refund_amount,
                new_balance=new_balance,
                action="add",
                admin_id=callback.from_user.id,
                details=f"برگشت موجودی به دلیل لغو سفارش #{order_id} توسط ادمین (وضعیت قبلی: {old_status})"
            )
    else:
        if old_status == 'awaiting_payment':
            logger.info(f"ℹ️ سفارش #{order_id} در انتظار پرداخت بود - موجودی برگشت داده نشد")
    if coupon_applied and coupon_code:
        coupon = COUPONS.get(coupon_code)
        coupon_consumed = False
        if coupon and user_id in coupon.get('used_by', []):
            coupon_consumed = True
        
        if not coupon_consumed:
            coupon_released = release_coupon_on_cancel(user_id)
            if coupon_released:
                logger.info(f"🏷️ کوپن {coupon_code} برای کاربر {user_id} آزاد شد (لغو سفارش توسط ادمین)")
            else:
                logger.warning(f"⚠️ کوپن {coupon_code} برای کاربر {user_id} آزاد نشد")
        else:
            logger.info(f"ℹ️ کوپن {coupon_code} قبلاً توسط کاربر {user_id} مصرف شده بود")
    try:
        user_lang = get_user(user_id).get('lang', 'fa')
        if old_status == 'awaiting_payment':
            if user_lang == "fa":
                await bot.send_message(
                    user_id,
                    f"{premium_emoji('cancel', '❌')} سفارش #{order_id} منقضی شد.\n\n"
                    f"{premium_emoji('config', '📦')} حجم: {volume} GB\n"
                    f"{premium_emoji('time', '⏱')} مدت: {days} روز\n"
                    f"ℹ️ از آنجایی که شما پرداختی انجام نداده‌اید، هیچ مبلغی از حساب شما کسر نشده است.\n"
                    f"{f'🏷️ کوپن شما ({coupon_code}) همچنان معتبر است.' if coupon_applied and coupon_code else ''}"
                )
            else:
                await bot.send_message(
                    user_id,
                    f"{premium_emoji('cancel', '❌')} Order #{order_id} has been Expired.\n\n"
                    f"{premium_emoji('config', '📦')} Volume: {volume} GB\n"
                    f"{premium_emoji('time', '⏱')} Duration: {days} days\n"
                    f"ℹ️ Since you haven't made any payment, no amount has been deducted from your balance.\n"
                    f"{f'🏷️ Your coupon ({coupon_code}) is still valid.' if coupon_applied and coupon_code else ''}"
                )
        else:
            refund_text = f"💰 مبلغ {refund_amount:,} تومان به حساب شما برگشت داده شد." if should_refund and refund_amount > 0 else ""
            coupon_text = f"🏷️ کوپن شما ({coupon_code}) {'آزاد شد' if coupon_applied and coupon_code else 'ندارد'}"
            
            if user_lang == "fa":
                await bot.send_message(
                    user_id,
                    f"❌ سفارش #{order_id} توسط ادمین لغو شد.\n\n"
                    f"📦 حجم: {volume} GB\n"
                    f"⏱ مدت: {days} روز\n"
                    f"{refund_text}\n"
                    f"{coupon_text}"
                )
            else:
                await bot.send_message(
                    user_id,
                    f"❌ Order #{order_id} has been cancelled by admin.\n\n"
                    f"📦 Volume: {volume} GB\n"
                    f"⏱ Duration: {days} days\n"
                    f"{refund_text}\n"
                    f"{coupon_text}"
                )
        
        logger.info(f"📨 پیام لغو سفارش به کاربر {user_id} ارسال شد")
    except Exception as e:
        logger.error(f"خطا در ارسال پیام لغو سفارش به کاربر {user_id}: {e}")
    if log_system:
        await log_system.log_admin_action(
            callback.from_user.id,
            f"لغو سفارش #{order_id}",
            target_user=user_id,
            details=f"حجم: {volume}GB | مدت: {days} روز | قیمت: {price:,} تومان | وضعیت قبلی: {old_status} | برگشت موجودی: {'بله' if should_refund else 'خیر'}"
        )
    
    CustomLogger.log_event('ORDER_CANCELLED_BY_ADMIN', 
        f'سفارش #{order_id} توسط ادمین لغو شد - کاربر: {user_name_escaped} ({user_id}) - وضعیت قبلی: {old_status} - برگشت موجودی: {should_refund}', 
        user_id)
    if old_status == 'awaiting_payment':
        refund_status = "❌ کاربر هنوز پرداختی انجام نداده بود - موجودی برگشت داده نشد"
    elif should_refund:
        refund_status = f"✅ موجودی کاربر برگشت داده شد ({refund_amount:,} تومان)"
    else:
        refund_status = "ℹ️ بدون تغییر موجودی"
    
    if lang == "fa":
        text = f"""
✅ <b>سفارش #{order_id} با موفقیت لغو شد!</b>

👤 کاربر: {user_name_escaped} (ID: {user_id})
📦 حجم: {volume} GB
⏱ مدت: {days} روز
💰 قیمت: {price:,} تومان
📊 وضعیت قبلی: {old_status}
{f'💰 {refund_status}' if should_refund else f'ℹ️ {refund_status}'}
🏷️ کوپن: {'آزاد شد' if coupon_applied and coupon_code else 'ندارد'}
"""
    else:
        text = f"""
✅ <b>Order #{order_id} cancelled successfully!</b>

👤 User: {user_name_escaped} (ID: {user_id})
📦 Volume: {volume} GB
⏱ Duration: {days} days
💰 Price: {price:,} Toman
📊 Previous status: {old_status}
{f'💰 {refund_status}' if should_refund else f'ℹ️ {refund_status}'}
🏷️ Coupon: {'Released' if coupon_applied and coupon_code else 'None'}
"""
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(
            text="🔙 برگشت به لیست سفارشات" if lang == "fa" else "🔙 Back to Orders",
            callback_data="admin_orders"
        )],
        [InlineKeyboardButton(
            text="👤 مشاهده کاربر" if lang == "fa" else "👤 View User",
            callback_data=f"admin_user_{user_id}"
        )]
    ])
    
    try:
        await callback.message.edit_text(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        try:
            await callback.message.delete()
        except:
            pass
        await callback.message.answer(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    
    await callback.answer("✅ سفارش لغو شد" if lang == "fa" else "✅ Order cancelled", show_alert=True)
    
    
