@dp.callback_query(F.data.startswith("approve_order_"))
async def approve_order(callback: CallbackQuery):
    if callback.from_user.id != ADMIN_ID_INT:
        return
    
    order_id = int(callback.data.split("_")[2])
    order = orders.get(str(order_id))
    
    if not order:
        logger.error(f"سفارش #{order_id} برای تایید یافت نشد")
        await callback.answer("سفارش یافت نشد", show_alert=True)
        return
    
    user_id = order['user_id']
    volume = order['volume']
    days = order['days']
    price = order['price']
    user_info = get_user(user_id)
    user_name = user_info.get('name', f'کاربر_{user_id}')
    lang = user_info.get('lang', 'fa')
    
    logger.info(f"ادمین تایید سفارش #{order_id} را شروع کرد")
    if SENAI_PANEL_ENABLED:
        await callback.message.edit_text(f"⏳ در حال ساخت کلاینت برای سفارش #{order_id}...")
        update_order(order_id, status='approved', approved_date=datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
        await check_referral_bonus(user_id)
        timestamp = int(datetime.now().timestamp())
        email = f"user{user_id}_{timestamp}"
        
        sub_link = await create_client_in_panel(user_id, email, volume, days, user_name)
        
        if sub_link:
            update_order(order_id, config_link=sub_link, email=email)
            await send_config_with_qr_option(user_id, order_id, volume, days, price, sub_link, lang)
            try:
                await bot.send_message(
                    user_id,
                    f"{premium_emoji('star', '⭐')} {'لطفا به سرویس ما امتیاز دهید:' if lang=='fa' else 'Please rate our service:'}",
                    reply_markup=get_feedback_keyboard(order_id, lang)
                )
            except:
                pass
            await callback.message.edit_text(
                f"✅ سفارش #{order_id} تایید و کلاینت ساخته شد!\n"
                f"👤 کاربر: {user_name} ({user_id})\n"
                f"📦 {volume}GB / {days} روز\n"
                f"🔗 لینک: {sub_link[:40]}..."
            )
        else:
            user = get_user(user_id)
            update_user(user_id, 'balance', user['balance'] + price)
            
            await callback.message.edit_text(
                f"❌ خطا در ساخت کلاینت برای سفارش #{order_id}\n"
                f"💰 موجودی کاربر برگشت داده شد."
            )
    else:
        user_states[callback.from_user.id] = {
            'awaiting_config': True,
            'order_id': order_id,
            'user_id': user_id,
            'volume': volume,
            'days': days,
            'price': price
        }
        
        if lang == "fa":
            await callback.message.answer("📝 لطفا لینک کانفیگ را برای این سفارش ارسال کنید:")
        else:
            await callback.message.answer("📝 Please send the config link for this order:")
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")

@dp.callback_query(F.data.startswith("reject_order_"))
async def reject_order(callback: CallbackQuery):
    if callback.from_user.id != ADMIN_ID_INT:
        return
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    order_id = int(callback.data.split("_")[2])
    order = orders.get(str(order_id))
    if order:
        update_order(order_id, status='rejected')
        user_lang = get_user(order['user_id']).get('lang', 'fa')
        try:
            await bot.send_message(order['user_id'], 
                f"{premium_emoji('fail', '❌')} {'سفارش #{order_id} شما رد شد' if user_lang == 'fa' else f'Order #{order_id} has been rejected'}")
            logger.info(f"سفارش #{order_id} رد شد - پیام به کاربر ارسال شد")
        except Exception as e:
            logger.error(f"خطا در ارسال پیام رد سفارش: {e}")
        await callback.answer("✅ سفارش رد شد" if lang == 'fa' else "✅ Order rejected", show_alert=True)
    await admin_orders(callback)

@dp.callback_query(F.data == "admin_balance")
async def admin_balance(callback: CallbackQuery):
    if callback.from_user.id != ADMIN_ID_INT:
        return
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    valid_orders = get_valid_orders()
    pending = [o for o in valid_orders.values() if o.get('type') == 'balance_charge' and o.get('status') == 'pending_balance_charge']
    
    logger.info(f"ادمین لیست درخواست‌های شارژ را مشاهده می‌کند - تعداد: {len(pending)}")
    
    if not pending:
        if lang == "fa":
            await callback.message.edit_text("✅ هیچ درخواست شارژی وجود ندارد", reply_markup=get_admin_keyboard(lang))
        else:
            await callback.message.edit_text("✅ No pending balance requests", reply_markup=get_admin_keyboard(lang))
        try:
            await callback.answer()
        except Exception as e:
            logger.warning(f"خطا در callback.answer: {e}")
        return
    
    buttons = []
    for o in pending:
        try:
            u = await bot.get_chat(o['user_id'])
            name_raw = u.first_name or f"ID:{o['user_id']}"
            name_escaped = html.escape(name_raw[:15])  # ✅ escape و محدود کردن طول
        except:
            name_escaped = f"ID:{o['user_id']}"
        buttons.append([InlineKeyboardButton(
            text=f"💰 #{o['order_id']} - {name_escaped} - {o['amount']:,}",
            callback_data=f"view_balance_{o['order_id']}"
        )])
    buttons.append([InlineKeyboardButton(text=f"🔙 {'برگشت' if lang=='fa' else 'Back'}", callback_data="admin_panel")])
    
    if lang == "fa":
        await callback.message.edit_text("💰 درخواست‌های شارژ", reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    else:
        await callback.message.edit_text("💰 Balance Requests", reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")

