@dp.callback_query(F.data == "admin_list_configs")
async def admin_list_configs(callback: CallbackQuery):
    if callback.from_user.id != ADMIN_ID_INT:
        return
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    configs = get_available_configs()
    
    if not configs:
        if lang == "fa":
            text = "✅ هیچ کانفیگی موجود نیست"
        else:
            text = "✅ No configs available"
        try:
            await callback.message.edit_text(text, reply_markup=get_admin_configs_keyboard(lang))
        except Exception as e:
            if "message is not modified" in str(e):
                try:
                    await callback.message.edit_reply_markup(reply_markup=get_admin_configs_keyboard(lang))
                except:
                    pass
            else:
                raise
        
        try:
            await callback.answer()
        except Exception as e:
            logger.warning(f"خطا در callback.answer: {e}")
        return
    
    buttons = []
    for c in configs:
        buttons.append([InlineKeyboardButton(
            text=f"📦 #{c['id']} - {c['volume']}GB/{c['days']} روز",
            callback_data=f"config_detail_{c['id']}"
        )])
    
    buttons.append([InlineKeyboardButton(
        text=f"🔙 {'برگشت' if lang=='fa' else 'Back'}",
        callback_data="admin_configs"
    )])
    
    if lang == "fa":
        text = f"📋 کانفیگ‌های موجود ({len(configs)} عدد)"
    else:
        text = f"📋 Available Configs ({len(configs)} items)"
    
    try:
        await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    except Exception as e:
        if "message is not modified" in str(e):
            try:
                await callback.message.edit_reply_markup(reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
            except:
                pass
        else:
            raise
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")

