@dp.callback_query(F.data.startswith("confirm_delete_cancelled_"))
async def confirm_delete_cancelled_orders(callback: CallbackQuery):
    """اجرای حذف سفارشات لغو/رد شده"""
    if callback.from_user.id != ADMIN_ID_INT:
        return await callback.answer("⛔", show_alert=True)
    
    target_id = int(callback.data.split("_")[3])
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    valid_orders = get_valid_orders()
    user_orders = [o for o in valid_orders.values() if o.get('user_id') == target_id]
    cancelled_orders = [o for o in user_orders if o.get('status') in ['cancelled', 'rejected']]
    
    deleted_count = 0
    deleted_ids = []
    
    for o in cancelled_orders:
        oid = str(o.get('order_id'))
        if oid in orders:
            deleted_ids.append(o.get('order_id'))
            del orders[oid]
            deleted_count += 1
            logger.info(f"🗑 سفارش #{o.get('order_id')} (لغو/رد شده) حذف شد")
    save_json(DB_FILES['orders'], orders)
    if lang == "fa":
        text = f"""
✅ <b>سفارشات لغو/رد شده حذف شدند!</b>

👤 کاربر: {html.escape(get_user(target_id).get('name', 'کاربر'))} (ID: {target_id})
🗑 تعداد حذف شده: {deleted_count}
📋 شناسه سفارشات: {', '.join(map(str, deleted_ids[:5]))}{'...' if len(deleted_ids) > 5 else ''}

💾 دیتابیس بروزرسانی شد.
"""
    else:
        text = f"""
✅ <b>Cancelled/Rejected orders deleted!</b>

👤 User: {html.escape(get_user(target_id).get('name', 'User'))} (ID: {target_id})
🗑 Deleted: {deleted_count}
📋 Order IDs: {', '.join(map(str, deleted_ids[:5]))}{'...' if len(deleted_ids) > 5 else ''}

💾 Database updated.
"""
    
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(
            text="🔙 برگشت به کاربر" if lang == "fa" else "🔙 Back to User",
            callback_data=f"admin_user_{target_id}"
        )]
    ])
    
    try:
        await callback.message.edit_text(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    except Exception as e:
        try:
            await callback.message.delete()
        except:
            pass
        await callback.message.answer(text, reply_markup=keyboard, parse_mode=ParseMode.HTML)
    
    await callback.answer("✅ سفارشات حذف شدند" if lang == "fa" else "✅ Orders deleted", show_alert=True)



@dp.callback_query(F.data.startswith("admin_add_balance_"))
async def admin_add_balance_cmd(callback: CallbackQuery):
    """شروع افزایش موجودی - با ذخیره کوپن کاربر"""
    if callback.from_user.id != ADMIN_ID_INT:
        return
    
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    target_id = int(callback.data.split("_")[3])
    target = get_user(target_id)
    target_name_raw = target.get('name', f'کاربر_{target_id}')
    target_name_escaped = html.escape(target_name_raw)
    user_state = user_states.get(target_id, {})
    coupon_code = user_state.get('coupon_code')
    coupon_discount = user_state.get('coupon_discount')
    coupon_applied = user_state.get('coupon_applied', False)
    
    logger.info(f"🔍 [admin_add_balance_cmd] کوپن کاربر {target_id}: code={coupon_code}, applied={coupon_applied}")
    user_states[callback.from_user.id] = {
        'awaiting_manual_balance': True, 
        'manual_balance_target': target_id,
        'balance_action': 'add',
        'target_coupon_code': coupon_code,
        'target_coupon_discount': coupon_discount,
        'target_coupon_applied': coupon_applied
    }
    
    logger.info(f"🔍 [admin_add_balance_cmd] state ادمین ذخیره شد: {user_states[callback.from_user.id]}")
    
    if lang == "fa":
        await callback.message.answer(f"💰 لطفا مبلغ مورد نظر برای کاربر {target_name_escaped} را وارد کنید:")
    else:
        await callback.message.answer(f"💰 Please enter the amount for user {target_name_escaped}:")
    
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")



@dp.callback_query(F.data == "admin_stats")
async def admin_stats(callback: CallbackQuery):
    if callback.from_user.id != ADMIN_ID_INT:
        return
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    total_users = len(users)
    valid_orders = get_valid_orders()
    approved = [o for o in valid_orders.values() if o.get('status') == 'approved']
    pending = [o for o in valid_orders.values() if o.get('status') == 'pending']
    
    total_revenue = sum(o.get('price', 0) for o in approved)
    total_balance = sum(u.get('balance', 0) for u in users.values())
    available_configs = get_available_configs_count()
    total_used_gb = 0
    total_capacity_gb = 0
    active_configs_count = 0
    
    if SENAI_PANEL_ENABLED:
        for o in approved:
            if o.get('config_link'):
                email = extract_email_from_sub_link(o.get('config_link', ''))
                if email:
                    client = await xui_get_client_info(email)
                    if client:
                        traffic = await xui_get_client_traffic(email)
                        total_capacity_gb += client.get('totalGB', 0) / (1024**3)
                        up = (traffic.get('up', 0) if traffic else 0) / (1024**3)
                        down = (traffic.get('down', 0) if traffic else 0) / (1024**3)
                        total_used_gb += up + down
                        active_configs_count += 1
    now = datetime.now().strftime("%H:%M:%S")
    
    if lang == "fa":
        text = f"""
📊 <b>آمار کلی سیستم</b>
<code>🕐 {now}</code>

👥 کاربران: {total_users}
📦 کل سفارشات: {len(valid_orders)} | ✅ تایید: {len(approved)} | ⏳ در انتظار: {len(pending)}
💰 فروش کل: {total_revenue:,} تومان
💵 موجودی کاربران: {total_balance:,} تومان

📡 <b>پنل:</b>
🔹 کانفیگ‌های فعال: {active_configs_count}
🔹 ظرفیت کل: {total_capacity_gb:.0f} GB
🔹 مصرف کل: {total_used_gb:.1f} GB
🔹 باقی‌مانده: {total_capacity_gb - total_used_gb:.1f} GB

📦 کانفیگ موجود در مخزن: {available_configs}
"""
    else:
        text = f"""
📊 <b>System Statistics</b>
<code>🕐 {now}</code>

👥 Users: {total_users}
📦 Orders: {len(valid_orders)} | ✅ Approved: {len(approved)} | ⏳ Pending: {len(pending)}
💰 Revenue: {total_revenue:,} Toman
💵 Balances: {total_balance:,} Toman

📡 <b>Panel:</b>
🔹 Active: {active_configs_count}
🔹 Capacity: {total_capacity_gb:.0f} GB
🔹 Used: {total_used_gb:.1f} GB
🔹 Free: {total_capacity_gb - total_used_gb:.1f} GB

📦 Pool: {available_configs}
"""
    
    buttons = [
        [InlineKeyboardButton(text="🔄 بروزرسانی" if lang=="fa" else "🔄 Refresh", callback_data="admin_stats")],
        [InlineKeyboardButton(text="🔙 برگشت" if lang=="fa" else "🔙 Back", callback_data="admin_panel")]
    ]
    await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
    try:
        await callback.answer()
    except Exception as e:
        logger.warning(f"خطا در callback.answer: {e}")


