async def get_panel_status() -> Optional[dict]:
    """دریافت وضعیت سرور پنل"""
    cookie = await xui_login()
    if not cookie:
        return None
    
    try:
        connector = aiohttp.TCPConnector(ssl=False)
        async with aiohttp.ClientSession(connector=connector) as session:
            csrf = await xui_get_csrf_token(session)
            headers = {"X-CSRF-Token": csrf} if csrf else {}
            async with session.get(
                f"{SENAI_PANEL_URL}/panel/api/server/status",
                cookies={"3x-ui": cookie},
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as response:
                if response.status == 200:
                    data = await response.json()
                    if data.get("success"):
                        obj = data.get("obj", {})
                        mem = obj.get("mem", {})
                        mem_total = mem.get("total", 0)
                        mem_current = mem.get("current", 0)
                        mem_percent = mem.get("percent", 0)
                        if mem_total == 0:
                            try:
                                async with session.get(
                                    f"{SENAI_PANEL_URL}/panel/api/server/meminfo",
                                    cookies={"3x-ui": cookie},
                                    headers=headers,
                                    timeout=aiohttp.ClientTimeout(total=5)
                                ) as mem_response:
                                    if mem_response.status == 200:
                                        mem_data = await mem_response.json()
                                        if mem_data.get("success"):
                                            mem_obj = mem_data.get("obj", {})
                                            mem_total = mem_obj.get("total", 0)
                                            mem_current = mem_obj.get("current", 0)
                                            mem_percent = mem_obj.get("percent", 0)
                            except:
                                pass
                        net_io = obj.get("netIO", {})
                        
                        return {
                            "cpu": obj.get("cpu", 0),
                            "mem": {
                                "total": mem_total,
                                "current": mem_current,
                                "percent": mem_percent
                            },
                            "disk": obj.get("disk", {}),
                            "net": obj.get("net", {}),
                            "uptime": obj.get("uptime", 0),
                            "net_up": net_io.get("up", 0),
                            "net_down": net_io.get("down", 0)
                        }
                return None
    except Exception as e:
        logger.error(f"❌ خطا در دریافت وضعیت پنل: {e}")
        return None


@dp.callback_query(F.data == "admin_panel_status")
async def admin_panel_status(callback: CallbackQuery):
    """نمایش وضعیت سرور"""
    if callback.from_user.id != ADMIN_ID_INT:
        return
    lang = get_user(callback.from_user.id).get('lang', 'fa')
    
    if not SENAI_PANEL_ENABLED:
        await callback.answer("❌ پنل متصل نیست", show_alert=True)
        return
    
    await callback.answer("⏳ در حال دریافت...")
    
    status = await get_panel_status()
    
    if status:
        cpu = status.get('cpu', 0)
        mem = status.get('mem', {})
        disk = status.get('disk', {})
        net = status.get('net', {})
        uptime = status.get('uptime', 0)
        
        net_up = status.get('net_up', 0)
        net_down = status.get('net_down', 0)
        mem_total_gb = mem.get('total', 0) / (1024**3)
        mem_current_gb = mem.get('current', 0) / (1024**3)
        mem_percent = mem.get('percent', 0)
        if mem_percent == 0 and mem_total_gb > 0 and mem_current_gb > 0:
            mem_percent = (mem_current_gb / mem_total_gb) * 100
        disk_total_gb = disk.get('total', 0) / (1024**3)
        disk_current_gb = disk.get('current', 0) / (1024**3)
        disk_percent = disk.get('percent', 0)
        
